window.TOEIC_QUESTIONS = [{"category":"Grammaire","topic":"Obligation","sentence":"Factory visitors must _____ safety glasses.","translation":"Les visiteurs de l’usine doivent porter des lunettes de protection.","options":["wear","wearing","wears","wore"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":0,"feedback":["Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wearing porte -ing. Cette forme ne suit pas directement must.","Wears porte un s. Après must, on garde wear sans s.","Wore est au passé. Après must, il faut la forme simple wear."],"id":"q001"},{"category":"Expression professionnelle","topic":"Respecter une échéance","sentence":"We must _____ the deadline for the annual report.","translation":"Nous devons respecter la date limite du rapport annuel.","options":["arrive","attend","join","meet"],"hint":"L’équipe veut finir à temps.","rule":"Meet a deadline = respecter une échéance.","answer":3,"feedback":["Arrive veut dire arriver. On ne dit pas arrive the deadline.","Attend veut dire assister à, comme attend a meeting. Une date limite n’est pas une réunion.","Join veut dire rejoindre, comme rejoindre une équipe.","Meet a deadline = respecter une échéance."],"id":"q002"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The invoices _____ checked by the accountant yesterday.","translation":"Les factures ont été vérifiées par le comptable hier.","options":["have","were","are","was"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":1,"feedback":["Have ne forme pas le passif ici. Les objets reçoivent l’action.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé.","Are est au présent. Le moment indiqué est passé.","Was accompagne une seule chose. Le sujet est au pluriel."],"id":"q003"},{"category":"Expression professionnelle","topic":"Passer une commande","sentence":"Please _____ an order for twenty chairs.","translation":"Merci de passer une commande de vingt chaises.","options":["spend","borrow","place","attend"],"hint":"On veut commander quelque chose.","rule":"Place an order = passer une commande.","answer":2,"feedback":["Spend veut dire dépenser de l’argent ou passer du temps, pas passer une commande.","Borrow veut dire emprunter. Ici, on veut acheter des chaises.","Place an order = passer une commande.","Attend veut dire assister à un événement, pas commander."],"id":"q004"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The parcel _____ delivered by the courier yesterday.","translation":"Le colis a été livré par le coursier hier.","options":["is","was","were","has"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":1,"feedback":["Is est au présent. La phrase indique un moment passé.","Was convient pour une seule chose, dans le passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Has ne forme pas le passif ici. Le sujet reçoit l’action."],"id":"q005"},{"category":"Expression professionnelle","topic":"Demander à obtenir","sentence":"You can apply _____ a refund on our website.","translation":"Tu peux demander un remboursement sur notre site.","options":["with","for","on","at"],"hint":"Repère apply : on demande à obtenir quelque chose.","rule":"Apply for something = faire une demande pour obtenir quelque chose.","answer":1,"feedback":["With veut dire avec. Pour demander un remboursement, on dit apply for.","Apply for something = faire une demande pour obtenir quelque chose.","On ne convient pas après apply pour demander à obtenir quelque chose.","At ne convient pas ici. Apply for a refund signifie demander un remboursement."],"id":"q006"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Each employee _____ a personal access code.","translation":"Chaque employé possède un code d’accès personnel.","options":["are","has","having","have"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":1,"feedback":["Are veut dire sont. Il ne convient ni au singulier ni au sens.","Each ou every présente une personne à la fois : on utilise has.","Having seul ne fait pas un verbe conjugué complet.","Have ne convient pas avec ce sujet singulier."],"id":"q007"},{"category":"Expression professionnelle","topic":"Responsable de","sentence":"Our assistant is responsible _____ booking flights.","translation":"Notre assistant est responsable de la réservation des vols.","options":["for","with","at","by"],"hint":"La phrase indique la tâche dont la personne est responsable.","rule":"Responsible for = responsable de.","answer":0,"feedback":["Responsible for = responsable de.","With ne complète pas responsible pour indiquer une tâche.","At convient dans good at, mais pas dans responsible for.","By ne complète pas responsible pour désigner une responsabilité."],"id":"q008"},{"category":"Grammaire","topic":"Manière de faire","sentence":"Please read the instructions _____ before using the machine.","translation":"Lis les instructions attentivement avant d’utiliser la machine.","options":["careful","care","careless","carefully"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":3,"feedback":["Careful décrit une personne ou une chose. Ici, on décrit une action.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Carefully explique comment faire l’action : avec attention."],"id":"q009"},{"category":"Expression professionnelle","topic":"Participer à","sentence":"All staff can _____ part in the training.","translation":"Tout le personnel peut participer à la formation.","options":["give","take","make","do"],"hint":"On invite les personnes à participer.","rule":"Take part in = participer à.","answer":1,"feedback":["Give veut dire donner. Give part in ne veut pas dire participer.","Take part in = participer à.","Make part in n’est pas l’expression participer à.","Do your part veut dire faire sa part, mais do part in ne convient pas."],"id":"q010"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"We need a _____ supplier for our new shop.","translation":"Nous avons besoin d’un fournisseur fiable pour notre nouvelle boutique.","options":["reliable","reliably","rely","reliability"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":0,"feedback":["Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliably décrit comment on fait une action, pas directement une chose.","Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliability est le nom fiabilité. Ici, on cherche une qualité."],"id":"q011"},{"category":"Expression professionnelle","topic":"À jour","sentence":"Please keep your contact details up to _____.","translation":"Merci de garder tes coordonnées à jour.","options":["day","year","date","hour"],"hint":"Il faut garder les informations actuelles.","rule":"Up to date = à jour.","answer":2,"feedback":["Day veut dire jour, mais up to day ne veut pas dire à jour.","Year veut dire année. L’expression à retenir est up to date.","Up to date = à jour.","Hour veut dire heure. L’expression à retenir est up to date."],"id":"q012"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"We received several _____ for the position.","translation":"Nous avons reçu plusieurs candidatures pour le poste.","options":["applying","applications","applicable","apply"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":1,"feedback":["Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Applications est un nom au pluriel : des candidatures.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné."],"id":"q013"},{"category":"Expression professionnelle","topic":"Gratuit","sentence":"Delivery is free of _____ for orders over fifty euros.","translation":"La livraison est gratuite pour les commandes de plus de cinquante euros.","options":["invoice","salary","price","charge"],"hint":"Le client ne doit rien payer.","rule":"Free of charge = gratuit, sans frais.","answer":3,"feedback":["Invoice veut dire facture. Free of invoice ne signifie pas gratuit.","Salary veut dire salaire. La phrase parle du prix de la livraison.","Price veut dire prix, mais l’expression est free of charge.","Free of charge = gratuit, sans frais."],"id":"q014"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"She has worked here _____ 2021.","translation":"Elle travaille ici depuis 2021.","options":["during","since","for","until"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":1,"feedback":["During veut dire pendant. Il ne marque pas ici le début de la période.","Since indique quand la période a commencé.","For sert à donner une durée, comme for three years.","Until indique une fin. Ici, on indique le début d’une période encore en cours."],"id":"q015"},{"category":"Expression professionnelle","topic":"Sous garantie","sentence":"The printer is still under _____.","translation":"L’imprimante est encore sous garantie.","options":["purchase","invoice","receipt","warranty"],"hint":"Le fabricant couvre encore les réparations.","rule":"Under warranty = sous garantie.","answer":3,"feedback":["Purchase veut dire achat. Under purchase ne veut pas dire sous garantie.","Invoice veut dire facture. Une facture est un document, pas une garantie.","Receipt veut dire reçu. Under receipt ne veut pas dire sous garantie.","Under warranty = sous garantie."],"id":"q016"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"She has managed this department _____ five years.","translation":"Elle dirige ce service depuis cinq ans.","options":["for","from","during","since"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":0,"feedback":["For introduit la durée : combien de temps cela dure.","From donne un départ. Ici, la phrase donne une durée.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","Since introduit un début précis, comme since Monday."],"id":"q017"},{"category":"Expression professionnelle","topic":"Au nom de","sentence":"On _____ of the team, thank you for your help.","translation":"Au nom de l’équipe, merci pour ton aide.","options":["purpose","side","behalf","regard"],"hint":"Une personne parle pour tout un groupe.","rule":"On behalf of = au nom de.","answer":2,"feedback":["On purpose veut dire volontairement. On purpose of ne convient pas ici.","On the side of peut vouloir dire du côté de, mais on side of ne convient pas.","On behalf of = au nom de.","With regard to veut dire concernant. On regard of ne convient pas."],"id":"q018"},{"category":"Grammaire","topic":"Après décider","sentence":"The company decided _____ a new branch.","translation":"L’entreprise a décidé d’ouvrir une nouvelle agence.","options":["to open","open","opened","opening"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":0,"feedback":["Decide to open veut dire décider d’ouvrir.","Il manque to entre decided et open.","Opened est une forme passée. Après decided, on utilise ici to open.","Opening ne suit pas directement decided dans cette construction."],"id":"q019"},{"category":"Expression professionnelle","topic":"À l’avance","sentence":"Please book your room in _____.","translation":"Merci de réserver ta chambre à l’avance.","options":["early","front","advance","ahead"],"hint":"L’action doit se faire avant la date prévue.","rule":"In advance = à l’avance.","answer":2,"feedback":["Early veut dire tôt, mais on ne dit pas in early pour à l’avance.","In front veut dire devant, dans l’espace. Il ne veut pas dire à l’avance.","In advance = à l’avance.","Ahead peut exprimer une avance, mais on ne dit pas in ahead."],"id":"q020"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Turn off the lights before _____ the office.","translation":"Éteins les lumières avant de quitter le bureau.","options":["leaving","left","leaves","leave"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":0,"feedback":["Après before ou after sans nouveau sujet, leaving convient.","Left est au passé. Cette forme ne convient pas directement ici.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici."],"id":"q021"},{"category":"Expression professionnelle","topic":"Être chargé de","sentence":"Who is in _____ of the sales team?","translation":"Qui est responsable de l’équipe commerciale ?","options":["duty","role","task","charge"],"hint":"La personne organise ou dirige l’activité.","rule":"In charge of = chargé de, responsable de.","answer":3,"feedback":["On duty signifie en service. In duty of ne signifie pas responsable de.","Role veut dire rôle. In role of ne convient pas pour cette expression.","Task veut dire tâche, mais in task of ne convient pas.","In charge of = chargé de, responsable de."],"id":"q022"},{"category":"Grammaire","topic":"Comparaison","sentence":"The new system is _____ than the old one.","translation":"Le nouveau système est plus efficace que l’ancien.","options":["efficient","most efficient","efficiently","more efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":3,"feedback":["Efficient seul ne forme pas cette comparaison avec than.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficiently décrit une action. Ici, on compare la qualité de deux choses.","More efficient than veut dire plus efficace que."],"id":"q023"},{"category":"Expression professionnelle","topic":"Suivre quelque chose","sentence":"This tool helps us keep _____ of all orders.","translation":"Cet outil nous aide à suivre toutes les commandes.","options":["part","track","attention","care"],"hint":"On veut savoir où en sont les dossiers.","rule":"Keep track of = suivre, tenir le suivi de.","answer":1,"feedback":["On dit take part in pour participer à. Ce n’est pas assurer le suivi.","Keep track of = suivre, tenir le suivi de.","On dit pay attention to pour faire attention à.","On dit take care of pour s’occuper de, pas keep care of."],"id":"q024"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The room is large _____ to seat twenty guests.","translation":"La salle est assez grande pour accueillir vingt invités assis.","options":["enough","too","very","much"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":0,"feedback":["Enough se place après la qualité : assez grand, assez rapide…","Too se place avant la qualité, pas après.","Very se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif."],"id":"q025"},{"category":"Expression professionnelle","topic":"Peu de préavis","sentence":"Thank you for coming at such short _____.","translation":"Merci d’être venu avec si peu de préavis.","options":["message","news","notice","warning"],"hint":"La personne a été prévenue peu de temps avant.","rule":"At short notice = avec peu de préavis.","answer":2,"feedback":["Message veut dire message. At short message ne signifie pas avec peu de préavis.","News veut dire nouvelles ou actualités. At short news ne convient pas.","At short notice = avec peu de préavis.","On peut dire with little warning, mais pas at short warning pour cette expression."],"id":"q026"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"We do not have _____ time before the meeting.","translation":"Nous n’avons pas beaucoup de temps avant la réunion.","options":["many","several","much","a few"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":2,"feedback":["Many accompagne des choses comptables au pluriel, comme many files.","Several accompagne un nom comptable au pluriel, comme several minutes.","Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","A few accompagne un nom comptable au pluriel, comme a few chairs."],"id":"q027"},{"category":"Expression professionnelle","topic":"Par écrit","sentence":"Please confirm the agreement in _____.","translation":"Merci de confirmer l’accord par écrit.","options":["writing","write","written","wrote"],"hint":"La confirmation doit être écrite.","rule":"In writing = par écrit.","answer":0,"feedback":["In writing = par écrit.","Write est le verbe écrire. In write n’est pas correct.","Written veut dire écrit. On pourrait dire in written form, mais form manque ici.","Wrote est la forme passée de write. Elle ne convient pas après in ici."],"id":"q028"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"Employees should update _____ contact details.","translation":"Les employés doivent mettre leurs coordonnées à jour.","options":["they","them","their","theirs"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":2,"feedback":["They veut dire ils ou elles et sert de sujet.","Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après."],"id":"q029"},{"category":"Expression professionnelle","topic":"Voyage d’affaires","sentence":"He is on a business _____ in Madrid.","translation":"Il est en voyage d’affaires à Madrid.","options":["route","trip","traffic","transport"],"hint":"La personne voyage pour son travail.","rule":"Business trip = voyage d’affaires.","answer":1,"feedback":["Route veut dire itinéraire. Il ne désigne pas ici le voyage lui-même.","Business trip = voyage d’affaires.","Traffic désigne la circulation. Ce n’est pas un voyage.","Transport désigne le transport, mais business transport ne convient pas ici pour un voyage."],"id":"q030"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The company will update _____ website next week.","translation":"L’entreprise mettra son site à jour la semaine prochaine.","options":["it","it’s","itself","its"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":3,"feedback":["It remplace une chose mais n’indique pas la possession devant un nom.","It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose."],"id":"q031"},{"category":"Expression professionnelle","topic":"De suite","sentence":"Sales increased for the fourth month in a _____.","translation":"Les ventes ont augmenté pour le quatrième mois de suite.","options":["row","line","rank","queue"],"hint":"Les périodes se suivent sans interruption.","rule":"In a row = de suite, consécutivement.","answer":0,"feedback":["In a row = de suite, consécutivement.","In a line signifie en ligne, comme des personnes alignées.","Rank peut désigner un rang ou un grade, mais in a rank ne signifie pas de suite.","In a queue signifie dans une file d’attente."],"id":"q032"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The employee _____ organised the event won an award.","translation":"L’employé qui a organisé l’événement a reçu une récompense.","options":["which","whom","who","whose"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":2,"feedback":["Which reprend généralement une chose. Ici, c’est une personne.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Who reprend une personne qui fait l’action juste après.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après."],"id":"q033"},{"category":"Expression professionnelle","topic":"Rupture de stock","sentence":"This model is out of _____; more units will arrive tomorrow.","translation":"Ce modèle est en rupture de stock ; d’autres exemplaires arriveront demain.","options":["sale","stock","invoice","receipt"],"hint":"Il n’en reste plus à vendre ; de nouveaux exemplaires arrivent bientôt.","rule":"Out of stock = en rupture de stock.","answer":1,"feedback":["For sale veut dire à vendre. Out of sale n’est pas l’expression rupture de stock.","Out of stock = en rupture de stock.","Invoice signifie facture. Out of invoice ne convient pas.","Receipt signifie reçu. Out of receipt ne convient pas."],"id":"q034"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The event was cancelled _____ the storm.","translation":"L’événement a été annulé à cause de la tempête.","options":["because of","although","so that","because"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":0,"feedback":["Because of veut dire à cause de et peut être suivi de cette chose.","Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe."],"id":"q035"},{"category":"Expression professionnelle","topic":"Appareil en panne","sentence":"The lift is out of _____; please use the stairs.","translation":"L’ascenseur est en panne ; merci d’utiliser les escaliers.","options":["arrangement","sequence","stock","order"],"hint":"L’appareil ne fonctionne plus.","rule":"Out of order = en panne.","answer":3,"feedback":["Arrangement peut signifier organisation. Out of arrangement ne signifie pas en panne.","Out of sequence veut dire dans le désordre, pas en panne.","Out of stock signifie qu’il n’en reste plus à vendre. Ici, l’appareil est présent mais ne fonctionne pas.","Out of order = en panne."],"id":"q036"},{"category":"Grammaire","topic":"Accord au présent","sentence":"Our receptionist _____ from eight to four every weekday.","translation":"Notre réceptionniste travaille de huit à seize heures chaque jour de semaine.","options":["working","work","to work","works"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":3,"feedback":["Working seul ne constitue pas un verbe conjugué complet.","Work sans s convient notamment avec they, pas avec ce sujet singulier.","To work n’est pas le verbe conjugué nécessaire ici.","Le sujet est une seule personne : au présent, on ajoute s à work."],"id":"q037"},{"category":"Expression professionnelle","topic":"Conformément à","sentence":"Payments must be made in _____ with the contract.","translation":"Les paiements doivent être faits conformément au contrat.","options":["accordingly","accorded","according","accordance"],"hint":"Respecter une règle : in … with.","rule":"In accordance with = conformément à.","answer":3,"feedback":["Accordingly veut dire en conséquence. In accordingly with ne convient pas.","Accorded est une forme verbale. L’expression fixe est in accordance with.","According s’utilise avec to : according to. On ne mélange pas avec in … with.","In accordance with = conformément à."],"id":"q038"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The CEO _____ our factory last Tuesday.","translation":"Le PDG a visité notre usine mardi dernier.","options":["visits","visited","has visited","visiting"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":1,"feedback":["Visits est au présent. La phrase situe l’action dans le passé.","Visited est au passé. Le moment indiqué est terminé.","Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visiting seul n’est pas un verbe conjugué complet."],"id":"q039"},{"category":"Expression professionnelle","topic":"Selon","sentence":"According _____ the report, sales are rising.","translation":"Selon le rapport, les ventes augmentent.","options":["with","to","at","for"],"hint":"Repère according : quel petit mot vient avec lui ?","rule":"According to = selon.","answer":1,"feedback":["With appartient à in accordance with. Avec according, on utilise to.","According to = selon.","According at n’est pas l’expression selon.","According for n’est pas l’expression selon."],"id":"q040"},{"category":"Grammaire","topic":"Condition future","sentence":"If you confirm today, I _____ the contract tomorrow.","translation":"Si tu confirmes aujourd’hui, j’enverrai le contrat demain.","options":["has sent","sent","will send","sending"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":2,"feedback":["Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Sent est au passé. Ici, le résultat attendu est futur.","Will send indique ce qui se passera si la condition se réalise.","Sending seul n’est pas un verbe conjugué complet."],"id":"q041"},{"category":"Expression professionnelle","topic":"Attendre avec plaisir","sentence":"We look forward _____ welcoming you.","translation":"Nous nous réjouissons de t’accueillir.","options":["on","for","at","to"],"hint":"On se réjouit de ce qui va arriver.","rule":"Look forward to + nom ou -ing = attendre avec plaisir.","answer":3,"feedback":["On ne complète pas look forward.","On dit wait for, mais look forward to.","At ne complète pas look forward.","Look forward to + nom ou -ing = attendre avec plaisir."],"id":"q042"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The employees built the display by _____, without outside help.","translation":"Les employés ont construit le présentoir eux-mêmes, sans aide extérieure.","options":["theirs","themselves","they","their"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":1,"feedback":["Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","By themselves veut dire eux-mêmes, sans aide.","They sert de sujet et ne vient pas après by ici.","Their doit être suivi d’un nom, comme their work."],"id":"q043"},{"category":"Expression professionnelle","topic":"Se conformer aux règles","sentence":"All drivers must comply _____ safety regulations.","translation":"Tous les conducteurs doivent respecter les règles de sécurité.","options":["to","with","on","for"],"hint":"Respecter des règles se dit comply…","rule":"Comply with = se conformer à.","answer":1,"feedback":["On dit conform to, mais comply with.","Comply with = se conformer à.","On ne complète pas comply dans cette expression.","For ne complète pas comply dans cette expression."],"id":"q044"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"We need the director’s _____ before signing.","translation":"Nous avons besoin de l’accord du directeur avant de signer.","options":["approve","approval","approves","approved"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":1,"feedback":["Approve est un verbe : approuver. Ici, on cherche une chose.","Approval est un nom : l’accord ou l’approbation.","Approves est un verbe conjugué. Ici, il faut un nom.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même."],"id":"q045"},{"category":"Expression professionnelle","topic":"Compter sur","sentence":"We rely _____ our suppliers to deliver on time.","translation":"Nous comptons sur nos fournisseurs pour livrer à temps.","options":["at","on","for","with"],"hint":"Rely signifie compter sur quelqu’un.","rule":"Rely on = compter sur.","answer":1,"feedback":["At ne convient pas après rely.","Rely on = compter sur.","For peut introduire ce qu’on attend, mais la personne vient après on : rely on someone for help.","With signifie avec. Pour compter sur, on utilise rely on."],"id":"q046"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The delivery will _____ before noon.","translation":"La livraison arrivera avant midi.","options":["arrived","arrives","arriving","arrive"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":3,"feedback":["Arrived est au passé. Après will, on garde arrive.","On n’ajoute pas de s au verbe après will.","Arriving ne suit pas directement will ; il faudrait une autre construction.","Après will, on garde la forme simple : arrive."],"id":"q047"},{"category":"Expression professionnelle","topic":"S’occuper de demandes","sentence":"Our team will deal _____ your complaint.","translation":"Notre équipe traitera ta réclamation.","options":["for","on","with","at"],"hint":"Deal… signifie ici traiter ou gérer.","rule":"Deal with = traiter, s’occuper de.","answer":2,"feedback":["For ne convient pas dans deal with a complaint.","On ne convient pas dans cette expression. Deal with signifie traiter.","Deal with = traiter, s’occuper de.","At ne convient pas après deal pour dire traiter une demande."],"id":"q048"},{"category":"Grammaire","topic":"Après enjoy","sentence":"Our employees enjoy _____ together.","translation":"Nos employés aiment travailler ensemble.","options":["work","worked","working","to work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":2,"feedback":["Work seul ne suit pas enjoy dans cette construction.","Worked est au passé et ne convient pas après enjoy ici.","Après enjoy, on utilise ici working : aimer travailler.","Enjoy ne se construit pas avec to work. On utilise working."],"id":"q049"},{"category":"Expression professionnelle","topic":"Faire attention","sentence":"Please _____ attention to the safety instructions.","translation":"Merci de faire attention aux consignes de sécurité.","options":["do","pay","make","hold"],"hint":"On demande d’être attentif.","rule":"Pay attention to = faire attention à.","answer":1,"feedback":["Do attention ne convient pas. On dit pay attention.","Pay attention to = faire attention à.","Make attention ne convient pas. On dit pay attention.","Hold someone’s attention signifie retenir son attention. Hold attention to ne convient pas."],"id":"q050"},{"category":"Grammaire","topic":"Obligation","sentence":"Kitchen staff must _____ clean uniforms every day.","translation":"Le personnel de cuisine doit porter une tenue propre chaque jour.","options":["wore","wearing","wear","wears"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":2,"feedback":["Wore est au passé. Après must, il faut la forme simple wear.","Wearing porte -ing. Cette forme ne suit pas directement must.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wears porte un s. Après must, on garde wear sans s."],"id":"q051"},{"category":"Expression professionnelle","topic":"Prendre contact","sentence":"Please get in _____ with our office.","translation":"Merci de prendre contact avec notre bureau.","options":["call","speak","reach","touch"],"hint":"Une expression pour contacter quelqu’un : get in…","rule":"Get in touch with = prendre contact avec.","answer":3,"feedback":["Call veut dire appeler, mais get in call with ne convient pas.","Speak veut dire parler. On peut dire speak with someone, mais pas get in speak with.","In reach peut vouloir dire à portée. Get in reach with ne veut pas dire contacter.","Get in touch with = prendre contact avec."],"id":"q052"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The chairs _____ delivered to the office last Monday.","translation":"Les chaises ont été livrées au bureau lundi dernier.","options":["were","was","are","have"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":0,"feedback":["Were convient : il y en a plusieurs et l’action a eu lieu dans le passé.","Was accompagne une seule chose. Le sujet est au pluriel.","Are est au présent. Le moment indiqué est passé.","Have ne forme pas le passif ici. Les objets reçoivent l’action."],"id":"q053"},{"category":"Expression professionnelle","topic":"Effectuer","sentence":"The engineer will _____ out a safety inspection.","translation":"L’ingénieur effectuera une inspection de sécurité.","options":["put","bring","turn","carry"],"hint":"Il faut réaliser une inspection ou un contrôle.","rule":"Carry out = effectuer, réaliser.","answer":3,"feedback":["Put out peut signifier éteindre. Il ne signifie pas effectuer des contrôles.","Bring out peut signifier publier ou faire ressortir. Il ne signifie pas effectuer ici.","Turn out peut signifier se révéler. Il ne signifie pas effectuer une inspection.","Carry out = effectuer, réaliser."],"id":"q054"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The contract _____ signed by both directors last Friday.","translation":"Le contrat a été signé par les deux directeurs vendredi dernier.","options":["has","were","was","is"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":2,"feedback":["Has ne forme pas le passif ici. Le sujet reçoit l’action.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Was convient pour une seule chose, dans le passé.","Is est au présent. La phrase indique un moment passé."],"id":"q055"},{"category":"Expression professionnelle","topic":"Organiser une réunion","sentence":"Can you _____ up a meeting with the client?","translation":"Peux-tu organiser une réunion avec le client ?","options":["give","take","break","set"],"hint":"L’expression avec up signifie organiser.","rule":"Set up = organiser, mettre en place.","answer":3,"feedback":["Give up signifie abandonner.","Take up peut signifier commencer une activité ou occuper du temps. Il ne signifie pas organiser une réunion.","Break up signifie notamment se séparer ou disperser, pas organiser.","Set up = organiser, mettre en place."],"id":"q056"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Every visitor _____ a temporary badge.","translation":"Chaque visiteur possède un badge temporaire.","options":["have","having","are","has"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":3,"feedback":["Have ne convient pas avec ce sujet singulier.","Having seul ne fait pas un verbe conjugué complet.","Are veut dire sont. Il ne convient ni au singulier ni au sens.","Each ou every présente une personne à la fois : on utilise has."],"id":"q057"},{"category":"Expression professionnelle","topic":"Reporter","sentence":"We have to _____ off the meeting until Friday.","translation":"Nous devons reporter la réunion à vendredi.","options":["take","put","set","turn"],"hint":"La date est repoussée à plus tard.","rule":"Put off = reporter à plus tard.","answer":1,"feedback":["Take off peut signifier décoller ou enlever.","Put off = reporter à plus tard.","Set off peut signifier partir ou déclencher. Il ne signifie pas reporter.","Turn off signifie notamment éteindre un appareil."],"id":"q058"},{"category":"Grammaire","topic":"Manière de faire","sentence":"The accountant checked the figures _____.","translation":"Le comptable a vérifié les chiffres avec attention.","options":["care","careful","careless","carefully"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":3,"feedback":["Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Careful décrit une personne ou une chose. Ici, on décrit une action.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Carefully explique comment faire l’action : avec attention."],"id":"q059"},{"category":"Expression professionnelle","topic":"Refuser une offre","sentence":"She turned _____ the job offer because the salary was too low.","translation":"Elle a refusé l’offre d’emploi car le salaire était trop bas.","options":["out","off","into","down"],"hint":"Turn… signifie ici refuser.","rule":"Turn down = refuser une offre ou une demande.","answer":3,"feedback":["Turn out peut signifier se révéler. Il ne signifie pas refuser cette offre.","Turn off signifie notamment éteindre.","Turn into veut dire se transformer en. Ici, il ne s’agit pas d’une transformation.","Turn down = refuser une offre ou une demande."],"id":"q060"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"The team chose a _____ delivery service.","translation":"L’équipe a choisi un service de livraison fiable.","options":["reliability","reliable","rely","reliably"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":1,"feedback":["Reliability est le nom fiabilité. Ici, on cherche une qualité.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliably décrit comment on fait une action, pas directement une chose."],"id":"q061"},{"category":"Expression professionnelle","topic":"Remplir les informations","sentence":"Please _____ in the missing details on the form.","translation":"Merci de compléter les informations manquantes sur le formulaire.","options":["break","fill","set","come"],"hint":"On complète ce qui manque sur un document.","rule":"Fill in = remplir, compléter.","answer":1,"feedback":["Break in peut vouloir dire entrer par effraction.","Fill in = remplir, compléter.","Set in décrit notamment une situation qui s’installe, comme le froid. Il ne signifie pas remplir.","Come in veut dire entrer. Il ne signifie pas remplir les informations."],"id":"q062"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"The recruiter reviewed ten _____ this morning.","translation":"Le recruteur a examiné dix candidatures ce matin.","options":["apply","applicable","applying","applications"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":3,"feedback":["Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature.","Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Applications est un nom au pluriel : des candidatures."],"id":"q063"},{"category":"Expression professionnelle","topic":"Ne plus avoir","sentence":"We have run _____ of printer paper.","translation":"Nous n’avons plus de papier pour l’imprimante.","options":["out","through","over","away"],"hint":"Le stock est épuisé : run… of.","rule":"Run out of = ne plus avoir, épuiser son stock de.","answer":0,"feedback":["Run out of = ne plus avoir, épuiser son stock de.","Run through peut signifier parcourir ou passer en revue. Run through of ne convient pas.","Run over ne forme pas l’expression ne plus avoir avec of.","Run away signifie s’enfuir."],"id":"q064"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"The shop has been closed _____ Monday.","translation":"La boutique est fermée depuis lundi.","options":["during","since","until","for"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":1,"feedback":["During veut dire pendant. Il ne marque pas ici le début de la période.","Since indique quand la période a commencé.","Until indique une fin. Ici, on indique le début d’une période encore en cours.","For sert à donner une durée, comme for three years."],"id":"q065"},{"category":"Expression professionnelle","topic":"Licencier du personnel","sentence":"The factory may _____ off workers because of falling sales.","translation":"L’usine pourrait licencier des ouvriers à cause de la baisse des ventes.","options":["resign","lay","pick","remove"],"hint":"L’entreprise doit supprimer des emplois : … off.","rule":"Lay off = licencier, souvent pour des raisons économiques.","answer":1,"feedback":["Resign veut dire démissionner. On ne dit pas resign off employees.","Lay off = licencier, souvent pour des raisons économiques.","Pick off peut signifier éliminer une cible, pas licencier du personnel.","Remove veut dire retirer. Il ne se construit pas avec off employees pour licencier."],"id":"q066"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"We have been waiting _____ two hours.","translation":"Nous attendons depuis deux heures.","options":["for","during","since","from"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":0,"feedback":["For introduit la durée : combien de temps cela dure.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","Since introduit un début précis, comme since Monday.","From donne un départ. Ici, la phrase donne une durée."],"id":"q067"},{"category":"Expression professionnelle","topic":"Examiner un problème","sentence":"The manager will look _____ the cause of the delay.","translation":"Le responsable examinera la cause du retard.","options":["into","forward","between","after"],"hint":"L’équipe va chercher ce qui ne fonctionne pas.","rule":"Look into = examiner, enquêter sur.","answer":0,"feedback":["Look into = examiner, enquêter sur.","Look forward to signifie attendre avec plaisir. Ici, il n’y a pas to et on examine un problème.","Look between signifie regarder entre des choses. Cela ne convient pas ici.","Look after signifie prendre soin de. Ce n’est pas examiner la cause d’un problème."],"id":"q068"},{"category":"Grammaire","topic":"Après décider","sentence":"The director has decided _____ the meeting with a short speech.","translation":"Le directeur a décidé d’ouvrir la réunion par un petit discours.","options":["opened","open","opening","to open"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":3,"feedback":["Opened est une forme passée. Après decided, on utilise ici to open.","Il manque to entre decided et open.","Opening ne suit pas directement decided dans cette construction.","Decide to open veut dire décider d’ouvrir."],"id":"q069"},{"category":"Expression professionnelle","topic":"Annuler","sentence":"They had to call _____ the outdoor event because of the storm.","translation":"Ils ont dû annuler l’événement extérieur à cause de la tempête.","options":["away","off","down","over"],"hint":"Call… signifie ici annuler complètement.","rule":"Call off = annuler.","answer":1,"feedback":["Away ne forme pas avec call l’expression annuler un événement.","Call off = annuler.","Call down ne signifie pas annuler ce concert.","Call over peut signifier appeler quelqu’un pour qu’il s’approche. Ce n’est pas annuler."],"id":"q070"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Check your bag before _____ the train.","translation":"Vérifie ton sac avant de quitter le train.","options":["leave","left","leaves","leaving"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":3,"feedback":["Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Left est au passé. Cette forme ne convient pas directement ici.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Après before ou after sans nouveau sujet, leaving convient."],"id":"q071"},{"category":"Expression professionnelle","topic":"Réduire","sentence":"We should _____ down on unnecessary printing.","translation":"Nous devrions réduire les impressions inutiles.","options":["make","take","cut","give"],"hint":"On veut réduire une consommation : … down on.","rule":"Cut down on = réduire sa consommation de.","answer":2,"feedback":["Make down on ne convient pas. Pour réduire, on dit cut down on.","Take down peut signifier noter ou démonter, mais take down on ne signifie pas réduire.","Cut down on = réduire sa consommation de.","Give down on ne forme pas cette expression."],"id":"q072"},{"category":"Grammaire","topic":"Comparaison","sentence":"This delivery method is _____ than our previous method.","translation":"Cette méthode de livraison est plus efficace que la précédente.","options":["more efficient","most efficient","efficient","efficiently"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":0,"feedback":["More efficient than veut dire plus efficace que.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficient seul ne forme pas cette comparaison avec than.","Efficiently décrit une action. Ici, on compare la qualité de deux choses."],"id":"q073"},{"category":"Expression professionnelle","topic":"Proposer une idée","sentence":"We need to _____ up with a better solution.","translation":"Nous devons trouver une meilleure solution.","options":["make","bring","come","send"],"hint":"Trouver une idée se dit … up with.","rule":"Come up with = trouver, proposer une idée.","answer":2,"feedback":["Make up a story signifie inventer une histoire, sans with. Make up with ne signifie pas trouver une solution.","Bring up a subject signifie aborder un sujet, sans with. Bring up with ne convient pas ici.","Come up with = trouver, proposer une idée.","Send signifie envoyer. Send up with ne signifie pas proposer une idée."],"id":"q074"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The connection is fast _____ to upload the file.","translation":"La connexion est assez rapide pour envoyer le fichier.","options":["enough","too","very","much"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":0,"feedback":["Enough se place après la qualité : assez grand, assez rapide…","Too se place avant la qualité, pas après.","Very se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif."],"id":"q075"},{"category":"Expression professionnelle","topic":"Provisoirement","sentence":"We will use the old system for the time _____.","translation":"Nous utiliserons l’ancien système pour le moment.","options":["been","was","being","be"],"hint":"Il s’agit d’une solution pour le moment.","rule":"For the time being = pour le moment.","answer":2,"feedback":["Been est une forme de be. L’expression pour le moment est for the time being.","Was indique le passé de be ; il ne complète pas cette expression.","For the time being = pour le moment.","Be ne complète pas cette expression fixe."],"id":"q076"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"The company does not have _____ money for advertising.","translation":"L’entreprise n’a pas beaucoup d’argent pour la publicité.","options":["many","a few","several","much"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":3,"feedback":["Many accompagne des choses comptables au pluriel, comme many files.","A few accompagne un nom comptable au pluriel, comme a few chairs.","Several accompagne un nom comptable au pluriel, comme several minutes.","Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent."],"id":"q077"},{"category":"Expression professionnelle","topic":"Dès que possible","sentence":"Please reply as soon _____ possible.","translation":"Merci de répondre dès que possible.","options":["like","as","than","so"],"hint":"As soon… possible signifie dès que possible.","rule":"As soon as possible = dès que possible.","answer":1,"feedback":["Like peut signifier comme, mais as soon like possible ne convient pas.","As soon as possible = dès que possible.","Than sert souvent à comparer : faster than. Ici, on utilise as … as.","So ne termine pas la construction as soon as possible."],"id":"q078"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"The visitors left _____ coats at reception.","translation":"Les visiteurs ont laissé leurs manteaux à l’accueil.","options":["them","theirs","their","they"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":2,"feedback":["Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","They veut dire ils ou elles et sert de sujet."],"id":"q079"},{"category":"Expression professionnelle","topic":"Au plus tard","sentence":"Send your application no later _____ Friday.","translation":"Envoie ta candidature au plus tard vendredi.","options":["as","than","then","that"],"hint":"No later… indique la dernière date possible.","rule":"No later than = au plus tard.","answer":1,"feedback":["As s’utilise dans as late as, mais ici il faut no later than.","No later than = au plus tard.","Then veut dire ensuite. Ne le confonds pas avec than, utilisé pour comparer.","That ne complète pas la comparaison no later than."],"id":"q080"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The hotel has reopened _____ swimming pool.","translation":"L’hôtel a rouvert sa piscine.","options":["itself","its","it’s","it"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":1,"feedback":["Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose.","It’s veut dire it is ou it has. Ce n’est pas son ou sa.","It remplace une chose mais n’indique pas la possession devant un nom."],"id":"q081"},{"category":"Expression professionnelle","topic":"À côté de","sentence":"The meeting room is next _____ reception.","translation":"La salle de réunion est à côté de l’accueil.","options":["with","for","to","at"],"hint":"Next… indique ce qui se trouve juste à côté.","rule":"Next to = à côté de.","answer":2,"feedback":["With veut dire avec. Pour à côté de, on dit next to.","For ne complète pas next dans cette expression.","Next to = à côté de.","At peut indiquer un lieu, mais next at ne convient pas."],"id":"q082"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The customer _____ called yesterday wants a refund.","translation":"Le client qui a appelé hier souhaite un remboursement.","options":["whose","who","which","whom"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":1,"feedback":["Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Who reprend une personne qui fait l’action juste après.","Which reprend généralement une chose. Ici, c’est une personne.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who."],"id":"q083"},{"category":"Expression professionnelle","topic":"En plus de","sentence":"In _____ to her salary, she receives a bonus.","translation":"En plus de son salaire, elle reçoit une prime.","options":["additionally","additional","added","addition"],"hint":"L’expression introduit une chose supplémentaire.","rule":"In addition to = en plus de.","answer":3,"feedback":["Additionally signifie en plus, mais s’utilise sans in … to.","Additional décrit quelque chose de supplémentaire, comme additional costs. Après in ici, il faut le nom addition.","Added veut dire ajouté. Il ne forme pas in addition to.","In addition to = en plus de."],"id":"q084"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The delivery was delayed _____ heavy traffic.","translation":"La livraison a été retardée à cause de la circulation dense.","options":["so that","although","because","because of"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":3,"feedback":["So that veut dire pour que ; il faudrait un sujet et un verbe après.","Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Because of veut dire à cause de et peut être suivi de cette chose."],"id":"q085"},{"category":"Expression professionnelle","topic":"En raison de","sentence":"The flight was delayed _____ to fog.","translation":"Le vol a été retardé en raison du brouillard.","options":["due","owed","because","cause"],"hint":"Le mot suivant le trou est to.","rule":"Due to = en raison de.","answer":0,"feedback":["Due to = en raison de.","Owed veut dire dû au sens d’une dette. Ici, on indique une cause : due to.","Because se construit avec of devant un nom : because of fog. Ici, to est déjà présent.","Cause veut dire cause ou causer, mais cause to ne forme pas cette expression."],"id":"q086"},{"category":"Grammaire","topic":"Accord au présent","sentence":"The accountant usually _____ from home on Fridays.","translation":"Le comptable travaille généralement chez lui le vendredi.","options":["works","work","working","to work"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":0,"feedback":["Le sujet est une seule personne : au présent, on ajoute s à work.","Work sans s convient notamment avec they, pas avec ce sujet singulier.","Working seul ne constitue pas un verbe conjugué complet.","To work n’est pas le verbe conjugué nécessaire ici."],"id":"q087"},{"category":"Expression professionnelle","topic":"À la demande","sentence":"Further information is available on _____.","translation":"Des informations complémentaires sont disponibles sur demande.","options":["request","ask","requested","requesting"],"hint":"L’expression signifie si quelqu’un le demande.","rule":"On request = sur demande.","answer":0,"feedback":["On request = sur demande.","Ask est un verbe : demander. On request utilise un nom.","Requested signifie demandé. On requested ne convient pas ici.","Requesting est une forme en -ing. L’expression est on request."],"id":"q088"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"Our supplier _____ the warehouse yesterday.","translation":"Notre fournisseur a visité l’entrepôt hier.","options":["has visited","visiting","visits","visited"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":3,"feedback":["Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visiting seul n’est pas un verbe conjugué complet.","Visits est au présent. La phrase situe l’action dans le passé.","Visited est au passé. Le moment indiqué est terminé."],"id":"q089"},{"category":"Expression professionnelle","topic":"À temps","sentence":"The parcel arrived just in _____ for the exhibition.","translation":"Le colis est arrivé juste à temps pour l’exposition.","options":["clock","hour","minute","time"],"hint":"On arrive avant qu’il ne soit trop tard : in…","rule":"In time = à temps.","answer":3,"feedback":["Clock signifie horloge. In clock ne convient pas.","Hour signifie heure, mais in hour ne signifie pas à temps.","Minute ne forme pas cette expression. In a minute voudrait dire dans une minute.","In time = à temps."],"id":"q090"},{"category":"Grammaire","topic":"Condition future","sentence":"If the payment arrives, we _____ your order tomorrow.","translation":"Si le paiement arrive, nous enverrons ta commande demain.","options":["has sent","will send","sending","sent"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":1,"feedback":["Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Will send indique ce qui se passera si la condition se réalise.","Sending seul n’est pas un verbe conjugué complet.","Sent est au passé. Ici, le résultat attendu est futur."],"id":"q091"},{"category":"Expression professionnelle","topic":"D’avance sur le planning","sentence":"The team completed the project _____ of schedule.","translation":"L’équipe a terminé le projet en avance sur le planning.","options":["ahead","early","front","before"],"hint":"La tâche est finie plus tôt que prévu : … of schedule.","rule":"Ahead of schedule = en avance sur le planning.","answer":0,"feedback":["Ahead of schedule = en avance sur le planning.","Early veut dire tôt. Early of schedule ne convient pas.","In front of indique devant dans l’espace. Front of schedule ne convient pas.","Before veut dire avant et peut être suivi directement d’un nom. Before of ne convient pas."],"id":"q092"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The managers organised the event by _____, without an agency.","translation":"Les responsables ont organisé l’événement eux-mêmes, sans agence.","options":["themselves","their","they","theirs"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":0,"feedback":["By themselves veut dire eux-mêmes, sans aide.","Their doit être suivi d’un nom, comme their work.","They sert de sujet et ne vient pas après by ici.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes."],"id":"q093"},{"category":"Expression professionnelle","topic":"Dans les limites du budget","sentence":"We must keep the project _____ budget.","translation":"Nous devons garder le projet dans les limites du budget.","options":["along","between","among","within"],"hint":"Les dépenses ne dépassent pas la somme prévue.","rule":"Within budget = dans les limites du budget.","answer":3,"feedback":["Along veut dire le long de. Il ne convient pas pour parler de dépenses limitées.","Between veut dire entre, par exemple entre deux montants. Ici, il n’y a qu’un budget.","Among veut dire parmi. Il ne signifie pas dans les limites d’une somme.","Within budget = dans les limites du budget."],"id":"q094"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"The project cannot start without official _____.","translation":"Le projet ne peut pas commencer sans approbation officielle.","options":["approved","approves","approval","approve"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":2,"feedback":["Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même.","Approves est un verbe conjugué. Ici, il faut un nom.","Approval est un nom : l’accord ou l’approbation.","Approve est un verbe : approuver. Ici, on cherche une chose."],"id":"q095"},{"category":"Expression professionnelle","topic":"En cas de","sentence":"In _____ of fire, use the stairs.","translation":"En cas d’incendie, utilise les escaliers.","options":["condition","situation","happens","case"],"hint":"Une consigne pour une éventuelle urgence : in… of.","rule":"In case of = en cas de.","answer":3,"feedback":["Condition peut désigner une condition. In condition of ne signifie pas en cas de.","Situation ne forme pas l’expression in case of.","Happens est un verbe : se produit. In happens of n’est pas correct.","In case of = en cas de."],"id":"q096"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"Our guests will _____ at six o’clock.","translation":"Nos invités arriveront à six heures.","options":["arrives","arriving","arrived","arrive"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":3,"feedback":["On n’ajoute pas de s au verbe après will.","Arriving ne suit pas directement will ; il faudrait une autre construction.","Arrived est au passé. Après will, on garde arrive.","Après will, on garde la forme simple : arrive."],"id":"q097"},{"category":"Expression professionnelle","topic":"Changer d’avis","sentence":"Let us know if you change your _____.","translation":"Préviens-nous si tu changes d’avis.","options":["mind","thought","minded","brain"],"hint":"La personne ne veut plus la même chose : change one’s…","rule":"Change your mind = changer d’avis.","answer":0,"feedback":["Change your mind = changer d’avis.","Thought veut dire pensée. L’expression changer d’avis est change your mind.","Minded est une forme qu’on trouve dans des adjectifs comme open-minded. Ici, il faut le nom mind.","Brain veut dire cerveau. Changer d’avis ne signifie pas changer de cerveau !"],"id":"q098"},{"category":"Grammaire","topic":"Après enjoy","sentence":"She enjoys _____ with international clients.","translation":"Elle aime travailler avec des clients internationaux.","options":["work","working","to work","worked"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":1,"feedback":["Work seul ne suit pas enjoy dans cette construction.","Après enjoy, on utilise ici working : aimer travailler.","Enjoy ne se construit pas avec to work. On utilise working.","Worked est au passé et ne convient pas après enjoy ici."],"id":"q099"},{"category":"Expression professionnelle","topic":"Être en congé","sentence":"Our manager is on annual _____ this week.","translation":"Notre responsable est en congé annuel cette semaine.","options":["leaving","leaves","left","leave"],"hint":"La personne ne travaille pas pendant quelques jours.","rule":"On leave = en congé.","answer":3,"feedback":["Leaving évoque l’action de partir. Ici, on cherche le nom congé.","Leaves peut désigner des feuilles ou signifier part au présent. Dans on leave, le nom ne prend pas de s.","Left peut vouloir dire parti ou gauche. Le nom congé est leave.","On leave = en congé."],"id":"q100"},{"category":"Grammaire","topic":"Obligation","sentence":"All cyclists must _____ helmets on the company tour.","translation":"Tous les cyclistes doivent porter un casque pendant la sortie de l’entreprise.","options":["wearing","wears","wore","wear"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":3,"feedback":["Wearing porte -ing. Cette forme ne suit pas directement must.","Wears porte un s. Après must, on garde wear sans s.","Wore est au passé. Après must, il faut la forme simple wear.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle."],"id":"q101"},{"category":"Expression professionnelle","topic":"Respecter une échéance","sentence":"The team worked late to _____ the deadline.","translation":"L’équipe a travaillé tard pour respecter l’échéance.","options":["meet","attend","join","arrive"],"hint":"L’équipe veut finir à temps.","rule":"Meet a deadline = respecter une échéance.","answer":0,"feedback":["Meet a deadline = respecter une échéance.","Attend veut dire assister à un événement. Une date limite n’est pas un événement auquel on assiste.","Join veut dire rejoindre une personne ou un groupe.","Arrive veut dire arriver. Il ne se place pas directement devant the deadline ici."],"id":"q102"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The windows _____ cleaned by a contractor two days ago.","translation":"Les fenêtres ont été nettoyées par un prestataire il y a deux jours.","options":["were","have","are","was"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":0,"feedback":["Were convient : il y en a plusieurs et l’action a eu lieu dans le passé.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Are est au présent. Le moment indiqué est passé.","Was accompagne une seule chose. Le sujet est au pluriel."],"id":"q103"},{"category":"Expression professionnelle","topic":"Passer une commande","sentence":"We will _____ an order with our usual supplier.","translation":"Nous passerons une commande auprès de notre fournisseur habituel.","options":["spend","attend","borrow","place"],"hint":"On veut commander quelque chose.","rule":"Place an order = passer une commande.","answer":3,"feedback":["Spend veut dire dépenser de l’argent ou passer du temps.","Attend veut dire assister à une réunion ou à un événement.","Borrow veut dire emprunter. Ici, on commande des produits.","Place an order = passer une commande."],"id":"q104"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The meeting _____ cancelled by the organiser last night.","translation":"La réunion a été annulée par l’organisateur hier soir.","options":["is","were","was","has"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":2,"feedback":["Is est au présent. La phrase indique un moment passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Was convient pour une seule chose, dans le passé.","Has ne forme pas le passif ici. Le sujet reçoit l’action."],"id":"q105"},{"category":"Expression professionnelle","topic":"Demander à obtenir","sentence":"She plans to apply _____ the manager’s position.","translation":"Elle prévoit de postuler au poste de responsable.","options":["at","for","with","on"],"hint":"Repère apply : on demande à obtenir quelque chose.","rule":"Apply for something = faire une demande pour obtenir quelque chose.","answer":1,"feedback":["At sert notamment à indiquer un lieu. Pour demander à obtenir, on dit apply for.","Apply for something = faire une demande pour obtenir quelque chose.","With veut dire avec. Il ne complète pas cette expression.","On ne convient pas ici : apply for indique ce qu’on demande à obtenir."],"id":"q106"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Each manager _____ a separate office.","translation":"Chaque responsable possède un bureau séparé.","options":["are","having","have","has"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":3,"feedback":["Are veut dire sont. Il ne convient ni au singulier ni au sens.","Having seul ne fait pas un verbe conjugué complet.","Have ne convient pas avec ce sujet singulier.","Each ou every présente une personne à la fois : on utilise has."],"id":"q107"},{"category":"Expression professionnelle","topic":"Responsable de","sentence":"The supervisor is responsible _____ checking the equipment.","translation":"Le superviseur est responsable de la vérification du matériel.","options":["with","at","by","for"],"hint":"La phrase indique la tâche dont la personne est responsable.","rule":"Responsible for = responsable de.","answer":3,"feedback":["With ne complète pas responsible pour indiquer une tâche.","At convient dans good at, mais pas pour dire responsable de.","By ne complète pas responsible pour indiquer la responsabilité.","Responsible for = responsable de."],"id":"q108"},{"category":"Grammaire","topic":"Manière de faire","sentence":"Our driver packed the fragile equipment _____.","translation":"Notre chauffeur a emballé le matériel fragile avec soin.","options":["careless","care","carefully","careful"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":2,"feedback":["Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Carefully explique comment faire l’action : avec attention.","Careful décrit une personne ou une chose. Ici, on décrit une action."],"id":"q109"},{"category":"Expression professionnelle","topic":"Participer à","sentence":"We hope you will _____ part in the survey.","translation":"Nous espérons que tu participeras à l’enquête.","options":["make","give","take","do"],"hint":"On invite les personnes à participer.","rule":"Take part in = participer à.","answer":2,"feedback":["Make part in n’est pas l’expression participer à.","Give veut dire donner. L’expression participer à est take part in.","Take part in = participer à.","Do your part veut dire faire sa part, mais do part in ne convient pas."],"id":"q110"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"The office requires a _____ internet connection.","translation":"Le bureau a besoin d’une connexion Internet fiable.","options":["reliability","reliably","reliable","rely"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":2,"feedback":["Reliability est le nom fiabilité. Ici, on cherche une qualité.","Reliably décrit comment on fait une action, pas directement une chose.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Rely est un verbe : compter sur. Ici, il faut une qualité."],"id":"q111"},{"category":"Expression professionnelle","topic":"À jour","sentence":"Our customer database is now up to _____.","translation":"Notre base de données clients est maintenant à jour.","options":["year","hour","date","day"],"hint":"Il faut garder les informations actuelles.","rule":"Up to date = à jour.","answer":2,"feedback":["Year veut dire année. L’expression correcte reste up to date.","Hour veut dire heure. Up to hour ne signifie pas à jour.","Up to date = à jour.","Day veut dire jour. On ne traduit pas à jour mot par mot."],"id":"q112"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"Only three _____ arrived before the deadline.","translation":"Seules trois candidatures sont arrivées avant la date limite.","options":["applications","applying","apply","applicable"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":0,"feedback":["Applications est un nom au pluriel : des candidatures.","Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature."],"id":"q113"},{"category":"Expression professionnelle","topic":"Gratuit","sentence":"The hotel provides breakfast free of _____.","translation":"L’hôtel propose le petit-déjeuner gratuitement.","options":["charge","salary","invoice","price"],"hint":"Le client ne doit rien payer.","rule":"Free of charge = gratuit, sans frais.","answer":0,"feedback":["Free of charge = gratuit, sans frais.","Salary veut dire salaire. Ici, on parle du prix d’un service.","Invoice veut dire facture. Free of invoice ne signifie pas gratuit.","Price veut dire prix. L’expression est free of charge."],"id":"q114"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"We have used this software _____ January.","translation":"Nous utilisons ce logiciel depuis janvier.","options":["until","for","during","since"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":3,"feedback":["Until indique une fin. Ici, on indique le début d’une période encore en cours.","For sert à donner une durée, comme for three years.","During veut dire pendant. Il ne marque pas ici le début de la période.","Since indique quand la période a commencé."],"id":"q115"},{"category":"Expression professionnelle","topic":"Sous garantie","sentence":"Repairs are free while the device is under _____.","translation":"Les réparations sont gratuites tant que l’appareil est sous garantie.","options":["warranty","invoice","receipt","purchase"],"hint":"Le fabricant couvre encore les réparations.","rule":"Under warranty = sous garantie.","answer":0,"feedback":["Under warranty = sous garantie.","Invoice est une facture, pas une garantie.","Receipt est un reçu. Under receipt ne signifie pas sous garantie.","Purchase signifie achat. Under purchase ne signifie pas sous garantie."],"id":"q116"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"The technician has been on site _____ thirty minutes.","translation":"Le technicien est sur place depuis trente minutes.","options":["from","during","since","for"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":3,"feedback":["From donne un départ. Ici, la phrase donne une durée.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","Since introduit un début précis, comme since Monday.","For introduit la durée : combien de temps cela dure."],"id":"q117"},{"category":"Expression professionnelle","topic":"Au nom de","sentence":"She signed the letter on _____ of the director.","translation":"Elle a signé la lettre au nom du directeur.","options":["side","behalf","purpose","regard"],"hint":"Une personne parle pour tout un groupe.","rule":"On behalf of = au nom de.","answer":1,"feedback":["On the side of signifie du côté de ; on side of ne convient pas.","On behalf of = au nom de.","On purpose veut dire volontairement. On purpose of ne convient pas.","With regard to signifie concernant. On regard of ne convient pas."],"id":"q118"},{"category":"Grammaire","topic":"Après décider","sentence":"The owners decided _____ a second restaurant.","translation":"Les propriétaires ont décidé d’ouvrir un deuxième restaurant.","options":["open","opening","to open","opened"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":2,"feedback":["Il manque to entre decided et open.","Opening ne suit pas directement decided dans cette construction.","Decide to open veut dire décider d’ouvrir.","Opened est une forme passée. Après decided, on utilise ici to open."],"id":"q119"},{"category":"Expression professionnelle","topic":"À l’avance","sentence":"Participants must pay two weeks in _____.","translation":"Les participants doivent payer deux semaines à l’avance.","options":["advance","ahead","front","early"],"hint":"L’action doit se faire avant la date prévue.","rule":"In advance = à l’avance.","answer":0,"feedback":["In advance = à l’avance.","Ahead peut exprimer une avance, mais on ne dit pas in ahead.","In front indique devant dans l’espace, pas à l’avance dans le temps.","Early veut dire tôt. On dit book early, sans in."],"id":"q120"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Please return your badge before _____ the building.","translation":"Rends ton badge avant de quitter le bâtiment.","options":["leave","leaves","left","leaving"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":3,"feedback":["Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Left est au passé. Cette forme ne convient pas directement ici.","Après before ou after sans nouveau sujet, leaving convient."],"id":"q121"},{"category":"Expression professionnelle","topic":"Être chargé de","sentence":"She is in _____ of organising the event.","translation":"Elle est chargée d’organiser l’événement.","options":["role","charge","task","duty"],"hint":"La personne organise ou dirige l’activité.","rule":"In charge of = chargé de, responsable de.","answer":1,"feedback":["Role veut dire rôle. In role of ne convient pas pour cette expression.","In charge of = chargé de, responsable de.","Task veut dire tâche, mais in task of ne convient pas.","On duty signifie en service. In duty of ne signifie pas responsable de."],"id":"q122"},{"category":"Grammaire","topic":"Comparaison","sentence":"The updated process is _____ than the original process.","translation":"Le processus modifié est plus efficace que le processus initial.","options":["more efficient","efficiently","most efficient","efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":0,"feedback":["More efficient than veut dire plus efficace que.","Efficiently décrit une action. Ici, on compare la qualité de deux choses.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficient seul ne forme pas cette comparaison avec than."],"id":"q123"},{"category":"Expression professionnelle","topic":"Suivre quelque chose","sentence":"Please keep _____ of your travel expenses.","translation":"Merci de tenir le suivi de tes frais de déplacement.","options":["care","part","attention","track"],"hint":"On veut savoir où en sont les dossiers.","rule":"Keep track of = suivre, tenir le suivi de.","answer":3,"feedback":["On dit take care of pour s’occuper de, pas keep care of.","On dit take part in pour participer à. Ce n’est pas assurer le suivi.","On dit pay attention to pour faire attention à.","Keep track of = suivre, tenir le suivi de."],"id":"q124"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The box is strong _____ to hold the equipment.","translation":"La boîte est assez solide pour contenir le matériel.","options":["too","very","much","enough"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":3,"feedback":["Too se place avant la qualité, pas après.","Very se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif.","Enough se place après la qualité : assez grand, assez rapide…"],"id":"q125"},{"category":"Expression professionnelle","topic":"Peu de préavis","sentence":"It is difficult to find a replacement at short _____.","translation":"Il est difficile de trouver un remplaçant avec peu de préavis.","options":["message","news","warning","notice"],"hint":"La personne a été prévenue peu de temps avant.","rule":"At short notice = avec peu de préavis.","answer":3,"feedback":["Message veut dire message. At short message ne signifie pas avec peu de préavis.","News veut dire nouvelles ou actualités. At short news ne convient pas.","On peut dire with little warning, mais pas at short warning pour cette expression.","At short notice = avec peu de préavis."],"id":"q126"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"There is not _____ information in this report.","translation":"Il n’y a pas beaucoup d’informations dans ce rapport.","options":["much","several","a few","many"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":0,"feedback":["Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","Several accompagne un nom comptable au pluriel, comme several minutes.","A few accompagne un nom comptable au pluriel, comme a few chairs.","Many accompagne des choses comptables au pluriel, comme many files."],"id":"q127"},{"category":"Expression professionnelle","topic":"Par écrit","sentence":"All complaints must be submitted in _____.","translation":"Toutes les plaintes doivent être envoyées par écrit.","options":["write","writing","written","wrote"],"hint":"La confirmation doit être écrite.","rule":"In writing = par écrit.","answer":1,"feedback":["Write est le verbe écrire. In write n’est pas correct.","In writing = par écrit.","Written veut dire écrit. On pourrait dire in written form, mais form manque ici.","Wrote est la forme passée de write. Elle ne convient pas après in ici."],"id":"q128"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"The managers presented _____ plans to the board.","translation":"Les responsables ont présenté leurs projets au conseil.","options":["they","them","theirs","their"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":3,"feedback":["They veut dire ils ou elles et sert de sujet.","Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…"],"id":"q129"},{"category":"Expression professionnelle","topic":"Voyage d’affaires","sentence":"The company paid for her business _____.","translation":"L’entreprise a payé son voyage d’affaires.","options":["transport","traffic","trip","route"],"hint":"La personne voyage pour son travail.","rule":"Business trip = voyage d’affaires.","answer":2,"feedback":["Transport désigne le transport, mais business transport ne convient pas ici pour un voyage.","Traffic désigne la circulation. Ce n’est pas un voyage.","Business trip = voyage d’affaires.","Route veut dire itinéraire. Il ne désigne pas ici le voyage lui-même."],"id":"q130"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The restaurant changed _____ menu last month.","translation":"Le restaurant a changé sa carte le mois dernier.","options":["itself","its","it’s","it"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":1,"feedback":["Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose.","It’s veut dire it is ou it has. Ce n’est pas son ou sa.","It remplace une chose mais n’indique pas la possession devant un nom."],"id":"q131"},{"category":"Expression professionnelle","topic":"De suite","sentence":"Our hotel won the award three years in a _____.","translation":"Notre hôtel a remporté le prix trois années de suite.","options":["queue","line","rank","row"],"hint":"Les périodes se suivent sans interruption.","rule":"In a row = de suite, consécutivement.","answer":3,"feedback":["In a queue signifie dans une file d’attente.","In a line signifie en ligne, comme des personnes alignées.","Rank peut désigner un rang ou un grade, mais in a rank ne signifie pas de suite.","In a row = de suite, consécutivement."],"id":"q132"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The engineer _____ designed this machine works in Brussels.","translation":"L’ingénieur qui a conçu cette machine travaille à Bruxelles.","options":["whose","whom","who","which"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":2,"feedback":["Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Who reprend une personne qui fait l’action juste après.","Which reprend généralement une chose. Ici, c’est une personne."],"id":"q133"},{"category":"Expression professionnelle","topic":"Rupture de stock","sentence":"The paper is out of _____, so we must wait for the next delivery.","translation":"Le papier est en rupture de stock, nous devons donc attendre la prochaine livraison.","options":["receipt","stock","invoice","sale"],"hint":"Il n’en reste plus à vendre ; de nouveaux exemplaires arrivent bientôt.","rule":"Out of stock = en rupture de stock.","answer":1,"feedback":["Receipt signifie reçu. Out of receipt ne convient pas.","Out of stock = en rupture de stock.","Invoice signifie facture. Out of invoice ne convient pas.","For sale veut dire à vendre. Out of sale n’est pas l’expression rupture de stock."],"id":"q134"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The office closed early _____ a power failure.","translation":"Le bureau a fermé tôt à cause d’une panne de courant.","options":["although","so that","because","because of"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":3,"feedback":["Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Because of veut dire à cause de et peut être suivi de cette chose."],"id":"q135"},{"category":"Expression professionnelle","topic":"Appareil en panne","sentence":"This coffee machine is out of _____ and needs repair.","translation":"Cette machine à café est en panne et doit être réparée.","options":["order","stock","sequence","arrangement"],"hint":"L’appareil ne fonctionne plus.","rule":"Out of order = en panne.","answer":0,"feedback":["Out of order = en panne.","Out of stock signifie qu’il n’en reste plus à vendre. Ici, l’appareil est présent mais ne fonctionne pas.","Out of sequence veut dire dans le désordre, pas en panne.","Arrangement peut signifier organisation. Out of arrangement ne signifie pas en panne."],"id":"q136"},{"category":"Grammaire","topic":"Accord au présent","sentence":"My colleague _____ in the marketing department.","translation":"Mon collègue travaille au service marketing.","options":["to work","working","work","works"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":3,"feedback":["To work n’est pas le verbe conjugué nécessaire ici.","Working seul ne constitue pas un verbe conjugué complet.","Work sans s convient notamment avec they, pas avec ce sujet singulier.","Le sujet est une seule personne : au présent, on ajoute s à work."],"id":"q137"},{"category":"Expression professionnelle","topic":"Conformément à","sentence":"The equipment was installed in _____ with safety rules.","translation":"Le matériel a été installé conformément aux règles de sécurité.","options":["accordingly","accordance","according","accorded"],"hint":"Respecter une règle : in … with.","rule":"In accordance with = conformément à.","answer":1,"feedback":["Accordingly veut dire en conséquence. In accordingly with ne convient pas.","In accordance with = conformément à.","According s’utilise avec to : according to. On ne mélange pas avec in … with.","Accorded est une forme verbale. L’expression fixe est in accordance with."],"id":"q138"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The inspector _____ the restaurant two days ago.","translation":"L’inspecteur a visité le restaurant il y a deux jours.","options":["visits","visited","visiting","has visited"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":1,"feedback":["Visits est au présent. La phrase situe l’action dans le passé.","Visited est au passé. Le moment indiqué est terminé.","Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé."],"id":"q139"},{"category":"Expression professionnelle","topic":"Selon","sentence":"The shop closes at six, according _____ its website.","translation":"La boutique ferme à six heures, selon son site.","options":["with","to","at","for"],"hint":"Repère according : quel petit mot vient avec lui ?","rule":"According to = selon.","answer":1,"feedback":["With appartient à in accordance with. Avec according, on utilise to.","According to = selon.","According at n’est pas l’expression selon.","According for n’est pas l’expression selon."],"id":"q140"},{"category":"Grammaire","topic":"Condition future","sentence":"If you provide your address, the assistant _____ the brochure next week.","translation":"Si tu donnes ton adresse, l’assistant enverra la brochure la semaine prochaine.","options":["has sent","sending","sent","will send"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":3,"feedback":["Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Sending seul n’est pas un verbe conjugué complet.","Sent est au passé. Ici, le résultat attendu est futur.","Will send indique ce qui se passera si la condition se réalise."],"id":"q141"},{"category":"Expression professionnelle","topic":"Attendre avec plaisir","sentence":"I look forward _____ hearing from you.","translation":"J’attends ta réponse avec plaisir.","options":["at","to","for","on"],"hint":"On se réjouit de ce qui va arriver.","rule":"Look forward to + nom ou -ing = attendre avec plaisir.","answer":1,"feedback":["At ne complète pas look forward.","Look forward to + nom ou -ing = attendre avec plaisir.","On dit wait for, mais look forward to.","On ne complète pas look forward."],"id":"q142"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The trainees completed the task by _____, without a supervisor.","translation":"Les stagiaires ont terminé la tâche eux-mêmes, sans superviseur.","options":["their","themselves","theirs","they"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":1,"feedback":["Their doit être suivi d’un nom, comme their work.","By themselves veut dire eux-mêmes, sans aide.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","They sert de sujet et ne vient pas après by ici."],"id":"q143"},{"category":"Expression professionnelle","topic":"Se conformer aux règles","sentence":"Our products comply _____ international standards.","translation":"Nos produits sont conformes aux normes internationales.","options":["for","with","to","on"],"hint":"Respecter des règles se dit comply…","rule":"Comply with = se conformer à.","answer":1,"feedback":["For ne complète pas comply dans cette expression.","Comply with = se conformer à.","On dit conform to, mais comply with.","On ne complète pas comply dans cette expression."],"id":"q144"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"Please obtain written _____ for this expense.","translation":"Merci d’obtenir un accord écrit pour cette dépense.","options":["approve","approves","approval","approved"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":2,"feedback":["Approve est un verbe : approuver. Ici, on cherche une chose.","Approves est un verbe conjugué. Ici, il faut un nom.","Approval est un nom : l’accord ou l’approbation.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même."],"id":"q145"},{"category":"Expression professionnelle","topic":"Compter sur","sentence":"You can rely _____ our support team.","translation":"Tu peux compter sur notre équipe d’assistance.","options":["at","for","on","with"],"hint":"Rely signifie compter sur quelqu’un.","rule":"Rely on = compter sur.","answer":2,"feedback":["At ne convient pas après rely.","For peut introduire ce qu’on attend, mais la personne vient après on : rely on someone for help.","Rely on = compter sur.","With signifie avec. Pour compter sur, on utilise rely on."],"id":"q146"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The replacement parts will _____ next week.","translation":"Les pièces de rechange arriveront la semaine prochaine.","options":["arriving","arrives","arrived","arrive"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":3,"feedback":["Arriving ne suit pas directement will ; il faudrait une autre construction.","On n’ajoute pas de s au verbe après will.","Arrived est au passé. Après will, on garde arrive.","Après will, on garde la forme simple : arrive."],"id":"q147"},{"category":"Expression professionnelle","topic":"S’occuper de demandes","sentence":"The receptionist deals _____ customer enquiries.","translation":"Le réceptionniste traite les demandes des clients.","options":["for","at","on","with"],"hint":"Deal… signifie ici traiter ou gérer.","rule":"Deal with = traiter, s’occuper de.","answer":3,"feedback":["For ne convient pas dans deal with a complaint.","At ne convient pas après deal pour dire traiter une demande.","On ne convient pas dans cette expression. Deal with signifie traiter.","Deal with = traiter, s’occuper de."],"id":"q148"},{"category":"Grammaire","topic":"Après enjoy","sentence":"The designer enjoys _____ on creative projects.","translation":"Le designer aime travailler sur des projets créatifs.","options":["work","worked","working","to work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":2,"feedback":["Work seul ne suit pas enjoy dans cette construction.","Worked est au passé et ne convient pas après enjoy ici.","Après enjoy, on utilise ici working : aimer travailler.","Enjoy ne se construit pas avec to work. On utilise working."],"id":"q149"},{"category":"Expression professionnelle","topic":"Faire attention","sentence":"Drivers must _____ attention to the road signs.","translation":"Les conducteurs doivent faire attention aux panneaux routiers.","options":["pay","make","do","hold"],"hint":"On demande d’être attentif.","rule":"Pay attention to = faire attention à.","answer":0,"feedback":["Pay attention to = faire attention à.","Make attention ne convient pas. On dit pay attention.","Do attention ne convient pas. On dit pay attention.","Hold someone’s attention signifie retenir son attention. Hold attention to ne convient pas."],"id":"q150"},{"category":"Grammaire","topic":"Obligation","sentence":"Construction workers must _____ protective boots on this site.","translation":"Les ouvriers doivent porter des chaussures de protection sur ce chantier.","options":["wearing","wear","wears","wore"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":1,"feedback":["Wearing porte -ing. Cette forme ne suit pas directement must.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wears porte un s. Après must, on garde wear sans s.","Wore est au passé. Après must, il faut la forme simple wear."],"id":"q151"},{"category":"Expression professionnelle","topic":"Prendre contact","sentence":"The supplier will get in _____ with you tomorrow.","translation":"Le fournisseur prendra contact avec toi demain.","options":["speak","touch","call","reach"],"hint":"Une expression pour contacter quelqu’un : get in…","rule":"Get in touch with = prendre contact avec.","answer":1,"feedback":["Speak veut dire parler. On peut dire speak with someone, mais pas get in speak with.","Get in touch with = prendre contact avec.","Call veut dire appeler, mais get in call with ne convient pas.","In reach peut vouloir dire à portée. Get in reach with ne veut pas dire contacter."],"id":"q152"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The invitations _____ printed by our assistant last week.","translation":"Les invitations ont été imprimées par notre assistant la semaine dernière.","options":["were","are","have","was"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":0,"feedback":["Were convient : il y en a plusieurs et l’action a eu lieu dans le passé.","Are est au présent. Le moment indiqué est passé.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Was accompagne une seule chose. Le sujet est au pluriel."],"id":"q153"},{"category":"Expression professionnelle","topic":"Effectuer","sentence":"We must _____ out regular checks on the machine.","translation":"Nous devons effectuer des contrôles réguliers sur la machine.","options":["bring","turn","put","carry"],"hint":"Il faut réaliser une inspection ou un contrôle.","rule":"Carry out = effectuer, réaliser.","answer":3,"feedback":["Bring out peut signifier publier ou faire ressortir. Il ne signifie pas effectuer ici.","Turn out peut signifier se révéler. Il ne signifie pas effectuer une inspection.","Put out peut signifier éteindre. Il ne signifie pas effectuer des contrôles.","Carry out = effectuer, réaliser."],"id":"q154"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The machine _____ repaired by a technician two days ago.","translation":"La machine a été réparée par un technicien il y a deux jours.","options":["were","was","has","is"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":1,"feedback":["Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Was convient pour une seule chose, dans le passé.","Has ne forme pas le passif ici. Le sujet reçoit l’action.","Is est au présent. La phrase indique un moment passé."],"id":"q155"},{"category":"Expression professionnelle","topic":"Organiser une réunion","sentence":"Our assistant will _____ up a video conference.","translation":"Notre assistant organisera une visioconférence.","options":["set","give","take","break"],"hint":"L’expression avec up signifie organiser.","rule":"Set up = organiser, mettre en place.","answer":0,"feedback":["Set up = organiser, mettre en place.","Give up signifie abandonner.","Take up peut signifier commencer une activité ou occuper du temps. Il ne signifie pas organiser une réunion.","Break up signifie notamment se séparer ou disperser, pas organiser."],"id":"q156"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Every customer _____ a unique account number.","translation":"Chaque client possède un numéro de compte unique.","options":["having","are","has","have"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":2,"feedback":["Having seul ne fait pas un verbe conjugué complet.","Are veut dire sont. Il ne convient ni au singulier ni au sens.","Each ou every présente une personne à la fois : on utilise has.","Have ne convient pas avec ce sujet singulier."],"id":"q157"},{"category":"Expression professionnelle","topic":"Reporter","sentence":"They decided to _____ off the launch until next month.","translation":"Ils ont décidé de reporter le lancement au mois prochain.","options":["put","turn","take","set"],"hint":"La date est repoussée à plus tard.","rule":"Put off = reporter à plus tard.","answer":0,"feedback":["Put off = reporter à plus tard.","Turn off signifie notamment éteindre un appareil.","Take off peut signifier décoller ou enlever.","Set off peut signifier partir ou déclencher. Il ne signifie pas reporter."],"id":"q158"},{"category":"Grammaire","topic":"Manière de faire","sentence":"The assistant listened _____ to the client’s request.","translation":"L’assistant a écouté attentivement la demande du client.","options":["carefully","careless","careful","care"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":0,"feedback":["Carefully explique comment faire l’action : avec attention.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Careful décrit une personne ou une chose. Ici, on décrit une action.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici."],"id":"q159"},{"category":"Expression professionnelle","topic":"Refuser une offre","sentence":"The bank turned _____ our loan application.","translation":"La banque a refusé notre demande de prêt.","options":["into","off","down","out"],"hint":"Turn… signifie ici refuser.","rule":"Turn down = refuser une offre ou une demande.","answer":2,"feedback":["Turn into veut dire se transformer en. Ici, il ne s’agit pas d’une transformation.","Turn off signifie notamment éteindre.","Turn down = refuser une offre ou une demande.","Turn out peut signifier se révéler. Il ne signifie pas refuser cette offre."],"id":"q160"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"Our company uses a _____ booking system.","translation":"Notre entreprise utilise un système de réservation fiable.","options":["rely","reliably","reliable","reliability"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":2,"feedback":["Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliably décrit comment on fait une action, pas directement une chose.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliability est le nom fiabilité. Ici, on cherche une qualité."],"id":"q161"},{"category":"Expression professionnelle","topic":"Remplir les informations","sentence":"You must _____ in your name and address in the spaces below.","translation":"Tu dois inscrire ton nom et ton adresse dans les espaces ci-dessous.","options":["break","fill","come","set"],"hint":"On complète ce qui manque sur un document.","rule":"Fill in = remplir, compléter.","answer":1,"feedback":["Break in peut vouloir dire entrer par effraction.","Fill in = remplir, compléter.","Come in veut dire entrer. Il ne signifie pas remplir les informations.","Set in décrit notamment une situation qui s’installe, comme le froid. Il ne signifie pas remplir."],"id":"q162"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"The company rejected two incomplete _____.","translation":"L’entreprise a rejeté deux candidatures incomplètes.","options":["applications","apply","applying","applicable"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":0,"feedback":["Applications est un nom au pluriel : des candidatures.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature."],"id":"q163"},{"category":"Expression professionnelle","topic":"Ne plus avoir","sentence":"The restaurant ran _____ of coffee this morning.","translation":"Le restaurant n’avait plus de café ce matin.","options":["out","away","through","over"],"hint":"Le stock est épuisé : run… of.","rule":"Run out of = ne plus avoir, épuiser son stock de.","answer":0,"feedback":["Run out of = ne plus avoir, épuiser son stock de.","Run away signifie s’enfuir.","Run through peut signifier parcourir ou passer en revue. Run through of ne convient pas.","Run over ne forme pas l’expression ne plus avoir avec of."],"id":"q164"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"The supplier has been our partner _____ 2018.","translation":"Le fournisseur est notre partenaire depuis 2018.","options":["until","during","since","for"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":2,"feedback":["Until indique une fin. Ici, on indique le début d’une période encore en cours.","During veut dire pendant. Il ne marque pas ici le début de la période.","Since indique quand la période a commencé.","For sert à donner une durée, comme for three years."],"id":"q165"},{"category":"Expression professionnelle","topic":"Licencier du personnel","sentence":"The company had to _____ off ten employees.","translation":"L’entreprise a dû licencier dix employés.","options":["resign","pick","lay","remove"],"hint":"L’entreprise doit supprimer des emplois : … off.","rule":"Lay off = licencier, souvent pour des raisons économiques.","answer":2,"feedback":["Resign veut dire démissionner. On ne dit pas resign off employees.","Pick off peut signifier éliminer une cible, pas licencier du personnel.","Lay off = licencier, souvent pour des raisons économiques.","Remove veut dire retirer. Il ne se construit pas avec off employees pour licencier."],"id":"q166"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"They have rented this office _____ six months.","translation":"Ils louent ce bureau depuis six mois.","options":["during","since","from","for"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":3,"feedback":["During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","Since introduit un début précis, comme since Monday.","From donne un départ. Ici, la phrase donne une durée.","For introduit la durée : combien de temps cela dure."],"id":"q167"},{"category":"Expression professionnelle","topic":"Examiner un problème","sentence":"Our team is looking _____ the billing error.","translation":"Notre équipe examine l’erreur de facturation.","options":["into","forward","between","after"],"hint":"L’équipe va chercher ce qui ne fonctionne pas.","rule":"Look into = examiner, enquêter sur.","answer":0,"feedback":["Look into = examiner, enquêter sur.","Look forward to signifie attendre avec plaisir. Ici, il n’y a pas to et on examine un problème.","Look between signifie regarder entre des choses. Cela ne convient pas ici.","Look after signifie prendre soin de. Ce n’est pas examiner la cause d’un problème."],"id":"q168"},{"category":"Grammaire","topic":"Après décider","sentence":"The bank has decided _____ its offices on Saturday mornings.","translation":"La banque a décidé d’ouvrir ses bureaux le samedi matin.","options":["open","opening","to open","opened"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":2,"feedback":["Il manque to entre decided et open.","Opening ne suit pas directement decided dans cette construction.","Decide to open veut dire décider d’ouvrir.","Opened est une forme passée. Après decided, on utilise ici to open."],"id":"q169"},{"category":"Expression professionnelle","topic":"Annuler","sentence":"The organisers will call _____ the concert if it is unsafe.","translation":"Les organisateurs annuleront le concert si les conditions sont dangereuses.","options":["away","over","down","off"],"hint":"Call… signifie ici annuler complètement.","rule":"Call off = annuler.","answer":3,"feedback":["Away ne forme pas avec call l’expression annuler un événement.","Call over peut signifier appeler quelqu’un pour qu’il s’approche. Ce n’est pas annuler.","Call down ne signifie pas annuler ce concert.","Call off = annuler."],"id":"q170"},{"category":"Grammaire","topic":"Après une préposition","sentence":"She called the client after _____ the conference.","translation":"Elle a appelé le client après avoir quitté la conférence.","options":["leaving","leaves","leave","left"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":0,"feedback":["Après before ou after sans nouveau sujet, leaving convient.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Left est au passé. Cette forme ne convient pas directement ici."],"id":"q171"},{"category":"Expression professionnelle","topic":"Réduire","sentence":"The office wants to _____ down on electricity use.","translation":"Le bureau veut réduire sa consommation d’électricité.","options":["give","make","cut","take"],"hint":"On veut réduire une consommation : … down on.","rule":"Cut down on = réduire sa consommation de.","answer":2,"feedback":["Give down on ne forme pas cette expression.","Make down on ne convient pas. Pour réduire, on dit cut down on.","Cut down on = réduire sa consommation de.","Take down peut signifier noter ou démonter, mais take down on ne signifie pas réduire."],"id":"q172"},{"category":"Grammaire","topic":"Comparaison","sentence":"Our new printer is _____ than the model we replaced.","translation":"Notre nouvelle imprimante est plus efficace que celle que nous avons remplacée.","options":["more efficient","most efficient","efficient","efficiently"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":0,"feedback":["More efficient than veut dire plus efficace que.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficient seul ne forme pas cette comparaison avec than.","Efficiently décrit une action. Ici, on compare la qualité de deux choses."],"id":"q173"},{"category":"Expression professionnelle","topic":"Proposer une idée","sentence":"Can you _____ up with a name for the new product?","translation":"Peux-tu trouver un nom pour le nouveau produit ?","options":["come","send","make","bring"],"hint":"Trouver une idée se dit … up with.","rule":"Come up with = trouver, proposer une idée.","answer":0,"feedback":["Come up with = trouver, proposer une idée.","Send signifie envoyer. Send up with ne signifie pas proposer une idée.","Make up a story signifie inventer une histoire, sans with. Make up with ne signifie pas trouver une solution.","Bring up a subject signifie aborder un sujet, sans with. Bring up with ne convient pas ici."],"id":"q174"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The instructions are clear _____ to understand without help.","translation":"Les instructions sont assez claires pour être comprises sans aide.","options":["too","very","much","enough"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":3,"feedback":["Too se place avant la qualité, pas après.","Very se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif.","Enough se place après la qualité : assez grand, assez rapide…"],"id":"q175"},{"category":"Expression professionnelle","topic":"Provisoirement","sentence":"For the time _____, the office will remain closed.","translation":"Pour le moment, le bureau restera fermé.","options":["being","be","been","was"],"hint":"Il s’agit d’une solution pour le moment.","rule":"For the time being = pour le moment.","answer":0,"feedback":["For the time being = pour le moment.","Be ne complète pas cette expression fixe.","Been est une forme de be. L’expression pour le moment est for the time being.","Was indique le passé de be ; il ne complète pas cette expression."],"id":"q176"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"We do not need _____ furniture for this small office.","translation":"Nous n’avons pas besoin de beaucoup de meubles pour ce petit bureau.","options":["much","several","a few","many"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":0,"feedback":["Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","Several accompagne un nom comptable au pluriel, comme several minutes.","A few accompagne un nom comptable au pluriel, comme a few chairs.","Many accompagne des choses comptables au pluriel, comme many files."],"id":"q177"},{"category":"Expression professionnelle","topic":"Dès que possible","sentence":"The technician will visit as soon _____ possible.","translation":"Le technicien passera dès que possible.","options":["as","so","like","than"],"hint":"As soon… possible signifie dès que possible.","rule":"As soon as possible = dès que possible.","answer":0,"feedback":["As soon as possible = dès que possible.","So ne termine pas la construction as soon as possible.","Like peut signifier comme, mais as soon like possible ne convient pas.","Than sert souvent à comparer : faster than. Ici, on utilise as … as."],"id":"q178"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"Customers can track _____ orders online.","translation":"Les clients peuvent suivre leurs commandes en ligne.","options":["them","they","their","theirs"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":2,"feedback":["Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","They veut dire ils ou elles et sert de sujet.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après."],"id":"q179"},{"category":"Expression professionnelle","topic":"Au plus tard","sentence":"Payment must arrive no later _____ the fifth of May.","translation":"Le paiement doit arriver au plus tard le cinq mai.","options":["that","then","than","as"],"hint":"No later… indique la dernière date possible.","rule":"No later than = au plus tard.","answer":2,"feedback":["That ne complète pas la comparaison no later than.","Then veut dire ensuite. Ne le confonds pas avec than, utilisé pour comparer.","No later than = au plus tard.","As s’utilise dans as late as, mais ici il faut no later than."],"id":"q180"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The museum extended _____ opening hours.","translation":"Le musée a prolongé ses heures d’ouverture.","options":["it","itself","its","it’s"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":2,"feedback":["It remplace une chose mais n’indique pas la possession devant un nom.","Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose.","It’s veut dire it is ou it has. Ce n’est pas son ou sa."],"id":"q181"},{"category":"Expression professionnelle","topic":"À côté de","sentence":"Our new shop is next _____ the station.","translation":"Notre nouvelle boutique est à côté de la gare.","options":["for","with","to","at"],"hint":"Next… indique ce qui se trouve juste à côté.","rule":"Next to = à côté de.","answer":2,"feedback":["For ne complète pas next dans cette expression.","With veut dire avec. Pour à côté de, on dit next to.","Next to = à côté de.","At peut indiquer un lieu, mais next at ne convient pas."],"id":"q182"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The assistant _____ booked the tickets is on holiday.","translation":"L’assistant qui a réservé les billets est en vacances.","options":["which","whose","whom","who"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":3,"feedback":["Which reprend généralement une chose. Ici, c’est une personne.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Who reprend une personne qui fait l’action juste après."],"id":"q183"},{"category":"Expression professionnelle","topic":"En plus de","sentence":"We offer training in _____ to technical support.","translation":"Nous proposons une formation en plus de l’assistance technique.","options":["addition","added","additional","additionally"],"hint":"L’expression introduit une chose supplémentaire.","rule":"In addition to = en plus de.","answer":0,"feedback":["In addition to = en plus de.","Added veut dire ajouté. Il ne forme pas in addition to.","Additional décrit quelque chose de supplémentaire, comme additional costs. Après in ici, il faut le nom addition.","Additionally signifie en plus, mais s’utilise sans in … to."],"id":"q184"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The price increased _____ higher transport costs.","translation":"Le prix a augmenté à cause de frais de transport plus élevés.","options":["so that","because of","because","although"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":1,"feedback":["So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because of veut dire à cause de et peut être suivi de cette chose.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Although veut dire bien que et demande ici une phrase avec un sujet et un verbe."],"id":"q185"},{"category":"Expression professionnelle","topic":"En raison de","sentence":"The office is closed _____ to renovation work.","translation":"Le bureau est fermé en raison de travaux de rénovation.","options":["cause","due","owed","because"],"hint":"Le mot suivant le trou est to.","rule":"Due to = en raison de.","answer":1,"feedback":["Cause veut dire cause ou causer, mais cause to ne forme pas cette expression.","Due to = en raison de.","Owed veut dire dû au sens d’une dette. Ici, on indique une cause : due to.","Because se construit avec of devant un nom : because of fog. Ici, to est déjà présent."],"id":"q186"},{"category":"Grammaire","topic":"Accord au présent","sentence":"The director _____ closely with the design team.","translation":"Le directeur travaille en étroite collaboration avec l’équipe de conception.","options":["work","works","working","to work"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":1,"feedback":["Work sans s convient notamment avec they, pas avec ce sujet singulier.","Le sujet est une seule personne : au présent, on ajoute s à work.","Working seul ne constitue pas un verbe conjugué complet.","To work n’est pas le verbe conjugué nécessaire ici."],"id":"q187"},{"category":"Expression professionnelle","topic":"À la demande","sentence":"We can provide a printed copy on _____.","translation":"Nous pouvons fournir un exemplaire papier sur demande.","options":["requesting","request","requested","ask"],"hint":"L’expression signifie si quelqu’un le demande.","rule":"On request = sur demande.","answer":1,"feedback":["Requesting est une forme en -ing. L’expression est on request.","On request = sur demande.","Requested signifie demandé. On requested ne convient pas ici.","Ask est un verbe : demander. On request utilise un nom."],"id":"q188"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The manager _____ our Paris office last month.","translation":"Le responsable a visité notre bureau parisien le mois dernier.","options":["visits","visiting","has visited","visited"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":3,"feedback":["Visits est au présent. La phrase situe l’action dans le passé.","Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visited est au passé. Le moment indiqué est terminé."],"id":"q189"},{"category":"Expression professionnelle","topic":"À temps","sentence":"We finished the repairs in _____ for the reopening.","translation":"Nous avons terminé les réparations à temps pour la réouverture.","options":["clock","minute","hour","time"],"hint":"On arrive avant qu’il ne soit trop tard : in…","rule":"In time = à temps.","answer":3,"feedback":["Clock signifie horloge. In clock ne convient pas.","Minute ne forme pas cette expression. In a minute voudrait dire dans une minute.","Hour signifie heure, mais in hour ne signifie pas à temps.","In time = à temps."],"id":"q190"},{"category":"Grammaire","topic":"Condition future","sentence":"If the director agrees, she _____ the invitation tomorrow.","translation":"Si le directeur est d’accord, elle enverra l’invitation demain.","options":["has sent","will send","sending","sent"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":1,"feedback":["Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Will send indique ce qui se passera si la condition se réalise.","Sending seul n’est pas un verbe conjugué complet.","Sent est au passé. Ici, le résultat attendu est futur."],"id":"q191"},{"category":"Expression professionnelle","topic":"D’avance sur le planning","sentence":"The renovation is running _____ of schedule.","translation":"La rénovation avance plus vite que prévu.","options":["before","ahead","early","front"],"hint":"La tâche est finie plus tôt que prévu : … of schedule.","rule":"Ahead of schedule = en avance sur le planning.","answer":1,"feedback":["Before veut dire avant et peut être suivi directement d’un nom. Before of ne convient pas.","Ahead of schedule = en avance sur le planning.","Early veut dire tôt. Early of schedule ne convient pas.","In front of indique devant dans l’espace. Front of schedule ne convient pas."],"id":"q192"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The owners decorated the shop by _____, without a designer.","translation":"Les propriétaires ont décoré la boutique eux-mêmes, sans décorateur.","options":["theirs","themselves","their","they"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":1,"feedback":["Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","By themselves veut dire eux-mêmes, sans aide.","Their doit être suivi d’un nom, comme their work.","They sert de sujet et ne vient pas après by ici."],"id":"q193"},{"category":"Expression professionnelle","topic":"Dans les limites du budget","sentence":"The repairs were completed _____ budget.","translation":"Les réparations ont été terminées sans dépasser le budget.","options":["along","between","among","within"],"hint":"Les dépenses ne dépassent pas la somme prévue.","rule":"Within budget = dans les limites du budget.","answer":3,"feedback":["Along veut dire le long de. Il ne convient pas pour parler de dépenses limitées.","Between veut dire entre, par exemple entre deux montants. Ici, il n’y a qu’un budget.","Among veut dire parmi. Il ne signifie pas dans les limites d’une somme.","Within budget = dans les limites du budget."],"id":"q194"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"The manager gave her _____ yesterday.","translation":"La responsable a donné son accord hier.","options":["approval","approves","approved","approve"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":0,"feedback":["Approval est un nom : l’accord ou l’approbation.","Approves est un verbe conjugué. Ici, il faut un nom.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même.","Approve est un verbe : approuver. Ici, on cherche une chose."],"id":"q195"},{"category":"Expression professionnelle","topic":"En cas de","sentence":"Call this number in _____ of an emergency.","translation":"Appelle ce numéro en cas d’urgence.","options":["happens","condition","case","situation"],"hint":"Une consigne pour une éventuelle urgence : in… of.","rule":"In case of = en cas de.","answer":2,"feedback":["Happens est un verbe : se produit. In happens of n’est pas correct.","Condition peut désigner une condition. In condition of ne signifie pas en cas de.","In case of = en cas de.","Situation ne forme pas l’expression in case of."],"id":"q196"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The new employee will _____ on Monday.","translation":"Le nouvel employé arrivera lundi.","options":["arriving","arrives","arrive","arrived"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":2,"feedback":["Arriving ne suit pas directement will ; il faudrait une autre construction.","On n’ajoute pas de s au verbe après will.","Après will, on garde la forme simple : arrive.","Arrived est au passé. Après will, on garde arrive."],"id":"q197"},{"category":"Expression professionnelle","topic":"Changer d’avis","sentence":"The customer changed her _____ and chose another colour.","translation":"La cliente a changé d’avis et choisi une autre couleur.","options":["thought","brain","minded","mind"],"hint":"La personne ne veut plus la même chose : change one’s…","rule":"Change your mind = changer d’avis.","answer":3,"feedback":["Thought veut dire pensée. L’expression changer d’avis est change your mind.","Brain veut dire cerveau. Changer d’avis ne signifie pas changer de cerveau !","Minded est une forme qu’on trouve dans des adjectifs comme open-minded. Ici, il faut le nom mind.","Change your mind = changer d’avis."],"id":"q198"},{"category":"Grammaire","topic":"Après enjoy","sentence":"I enjoy _____ in a small team.","translation":"J’aime travailler dans une petite équipe.","options":["worked","working","work","to work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":1,"feedback":["Worked est au passé et ne convient pas après enjoy ici.","Après enjoy, on utilise ici working : aimer travailler.","Work seul ne suit pas enjoy dans cette construction.","Enjoy ne se construit pas avec to work. On utilise working."],"id":"q199"},{"category":"Expression professionnelle","topic":"Être en congé","sentence":"Please contact her assistant while she is on _____.","translation":"Merci de contacter son assistant pendant son congé.","options":["leave","left","leaves","leaving"],"hint":"La personne ne travaille pas pendant quelques jours.","rule":"On leave = en congé.","answer":0,"feedback":["On leave = en congé.","Left peut vouloir dire parti ou gauche. Le nom congé est leave.","Leaves peut désigner des feuilles ou signifier part au présent. Dans on leave, le nom ne prend pas de s.","Leaving évoque l’action de partir. Ici, on cherche le nom congé."],"id":"q200"},{"category":"Grammaire","topic":"Obligation","sentence":"Visitors must _____ their badges while they are in the building.","translation":"Les visiteurs doivent porter leur badge pendant qu’ils sont dans le bâtiment.","options":["wearing","wear","wears","wore"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":1,"feedback":["Wearing porte -ing. Cette forme ne suit pas directement must.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wears porte un s. Après must, on garde wear sans s.","Wore est au passé. Après must, il faut la forme simple wear."],"id":"q201"},{"category":"Expression professionnelle","topic":"Respecter une échéance","sentence":"The design team worked late to _____ the deadline.","translation":"L’équipe de conception a travaillé tard pour respecter l’échéance.","options":["attend","join","meet","arrive"],"hint":"L’équipe veut finir à temps.","rule":"Meet a deadline = respecter une échéance.","answer":2,"feedback":["Attend veut dire assister à un événement. Une date limite n’est pas un événement auquel on assiste.","Join veut dire rejoindre une personne ou un groupe.","Meet a deadline = respecter une échéance.","Arrive veut dire arriver. Il ne se place pas directement devant the deadline ici."],"id":"q202"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The reports _____ reviewed by the board last Thursday.","translation":"Les rapports ont été examinés par le conseil d’administration jeudi dernier.","options":["was","have","are","were"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":3,"feedback":["Was accompagne une seule chose. Le sujet est au pluriel.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Are est au présent. Le moment indiqué est passé.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé."],"id":"q203"},{"category":"Expression professionnelle","topic":"Passer une commande","sentence":"The restaurant will _____ an order for new tables.","translation":"Le restaurant passera une commande pour de nouvelles tables.","options":["spend","borrow","attend","place"],"hint":"On veut commander quelque chose.","rule":"Place an order = passer une commande.","answer":3,"feedback":["Spend veut dire dépenser de l’argent ou passer du temps.","Borrow veut dire emprunter. Ici, on commande des produits.","Attend veut dire assister à une réunion ou à un événement.","Place an order = passer une commande."],"id":"q204"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The payment _____ approved by the finance director yesterday.","translation":"Le paiement a été approuvé par le directeur financier hier.","options":["was","has","is","were"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":0,"feedback":["Was convient pour une seule chose, dans le passé.","Has ne forme pas le passif ici. Le sujet reçoit l’action.","Is est au présent. La phrase indique un moment passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose."],"id":"q205"},{"category":"Expression professionnelle","topic":"Demander à obtenir","sentence":"Employees may apply _____ travel assistance online.","translation":"Les employés peuvent demander une aide au déplacement en ligne.","options":["with","on","at","for"],"hint":"Repère apply : on demande à obtenir quelque chose.","rule":"Apply for something = faire une demande pour obtenir quelque chose.","answer":3,"feedback":["With veut dire avec. Il ne complète pas cette expression.","On ne convient pas ici : apply for indique ce qu’on demande à obtenir.","At sert notamment à indiquer un lieu. Pour demander à obtenir, on dit apply for.","Apply for something = faire une demande pour obtenir quelque chose."],"id":"q206"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Each department _____ its own training budget.","translation":"Chaque département possède son propre budget de formation.","options":["having","have","are","has"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":3,"feedback":["Having seul ne fait pas un verbe conjugué complet.","Have ne convient pas avec ce sujet singulier.","Are veut dire sont. Il ne convient ni au singulier ni au sens.","Each ou every présente une personne à la fois : on utilise has."],"id":"q207"},{"category":"Expression professionnelle","topic":"Responsable de","sentence":"Maya is responsible _____ checking the invoices.","translation":"Maya est responsable de la vérification des factures.","options":["with","for","at","by"],"hint":"La phrase indique la tâche dont la personne est responsable.","rule":"Responsible for = responsable de.","answer":1,"feedback":["With ne complète pas responsible pour indiquer une tâche.","Responsible for = responsable de.","At convient dans good at, mais pas pour dire responsable de.","By ne complète pas responsible pour indiquer la responsabilité."],"id":"q208"},{"category":"Grammaire","topic":"Manière de faire","sentence":"Please check the delivery address _____ before confirming your order.","translation":"Vérifie soigneusement l’adresse de livraison avant de confirmer ta commande.","options":["care","carefully","careful","careless"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":1,"feedback":["Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Carefully explique comment faire l’action : avec attention.","Careful décrit une personne ou une chose. Ici, on décrit une action.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme."],"id":"q209"},{"category":"Expression professionnelle","topic":"Participer à","sentence":"More than fifty employees will _____ part in the survey.","translation":"Plus de cinquante employés participeront à l’enquête.","options":["make","give","do","take"],"hint":"On invite les personnes à participer.","rule":"Take part in = participer à.","answer":3,"feedback":["Make part in n’est pas l’expression participer à.","Give veut dire donner. L’expression participer à est take part in.","Do your part veut dire faire sa part, mais do part in ne convient pas.","Take part in = participer à."],"id":"q210"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"The hospital needs a _____ source of electricity.","translation":"L’hôpital a besoin d’une source d’électricité fiable.","options":["reliably","rely","reliable","reliability"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":2,"feedback":["Reliably décrit comment on fait une action, pas directement une chose.","Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliability est le nom fiabilité. Ici, on cherche une qualité."],"id":"q211"},{"category":"Expression professionnelle","topic":"À jour","sentence":"Make sure the price list is up to _____.","translation":"Assure-toi que la liste des prix est à jour.","options":["day","date","year","hour"],"hint":"Il faut garder les informations actuelles.","rule":"Up to date = à jour.","answer":1,"feedback":["Day veut dire jour. On ne traduit pas à jour mot par mot.","Up to date = à jour.","Year veut dire année. L’expression correcte reste up to date.","Hour veut dire heure. Up to hour ne signifie pas à jour."],"id":"q212"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"The HR team is reviewing several _____ for the marketing role.","translation":"L’équipe des ressources humaines examine plusieurs candidatures pour le poste en marketing.","options":["applying","applicable","applications","apply"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":2,"feedback":["Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature.","Applications est un nom au pluriel : des candidatures.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné."],"id":"q213"},{"category":"Expression professionnelle","topic":"Gratuit","sentence":"Parking is available free of _____ for hotel guests.","translation":"Le stationnement est gratuit pour les clients de l’hôtel.","options":["invoice","charge","salary","price"],"hint":"Le client ne doit rien payer.","rule":"Free of charge = gratuit, sans frais.","answer":1,"feedback":["Invoice veut dire facture. Free of invoice ne signifie pas gratuit.","Free of charge = gratuit, sans frais.","Salary veut dire salaire. Ici, on parle du prix d’un service.","Price veut dire prix. L’expression est free of charge."],"id":"q214"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"The shop has been open _____ September.","translation":"Le magasin est ouvert depuis septembre.","options":["during","until","since","for"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":2,"feedback":["During veut dire pendant. Il ne marque pas ici le début de la période.","Until indique une fin. Ici, on indique le début d’une période encore en cours.","Since indique quand la période a commencé.","For sert à donner une durée, comme for three years."],"id":"q215"},{"category":"Expression professionnelle","topic":"Sous garantie","sentence":"This coffee machine remains under _____ until December.","translation":"Cette machine à café reste sous garantie jusqu’en décembre.","options":["warranty","receipt","purchase","invoice"],"hint":"Le fabricant couvre encore les réparations.","rule":"Under warranty = sous garantie.","answer":0,"feedback":["Under warranty = sous garantie.","Receipt est un reçu. Under receipt ne signifie pas sous garantie.","Purchase signifie achat. Under purchase ne signifie pas sous garantie.","Invoice est une facture, pas une garantie."],"id":"q216"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"The engineer has been inspecting the machine _____ two hours.","translation":"L’ingénieur inspecte la machine depuis deux heures.","options":["during","from","for","since"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":2,"feedback":["During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","From donne un départ. Ici, la phrase donne une durée.","For introduit la durée : combien de temps cela dure.","Since introduit un début précis, comme since Monday."],"id":"q217"},{"category":"Expression professionnelle","topic":"Au nom de","sentence":"I am writing on _____ of our managing director.","translation":"Je vous écris au nom de notre directeur général.","options":["behalf","side","purpose","regard"],"hint":"Une personne parle pour tout un groupe.","rule":"On behalf of = au nom de.","answer":0,"feedback":["On behalf of = au nom de.","On the side of signifie du côté de ; on side of ne convient pas.","On purpose veut dire volontairement. On purpose of ne convient pas.","With regard to signifie concernant. On regard of ne convient pas."],"id":"q218"},{"category":"Grammaire","topic":"Après décider","sentence":"The retailer decided _____ a store near the station.","translation":"Le détaillant a décidé d’ouvrir un magasin près de la gare.","options":["to open","opened","opening","open"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":0,"feedback":["Decide to open veut dire décider d’ouvrir.","Opened est une forme passée. Après decided, on utilise ici to open.","Opening ne suit pas directement decided dans cette construction.","Il manque to entre decided et open."],"id":"q219"},{"category":"Expression professionnelle","topic":"À l’avance","sentence":"Tickets should be purchased in _____.","translation":"Les billets doivent être achetés à l’avance.","options":["advance","ahead","front","early"],"hint":"L’action doit se faire avant la date prévue.","rule":"In advance = à l’avance.","answer":0,"feedback":["In advance = à l’avance.","Ahead peut exprimer une avance, mais on ne dit pas in ahead.","In front indique devant dans l’espace, pas à l’avance dans le temps.","Early veut dire tôt. On dit book early, sans in."],"id":"q220"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Please return your visitor badge before _____ the building.","translation":"Rends ton badge de visiteur avant de quitter le bâtiment.","options":["left","leaving","leaves","leave"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":1,"feedback":["Left est au passé. Cette forme ne convient pas directement ici.","Après before ou after sans nouveau sujet, leaving convient.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici."],"id":"q221"},{"category":"Expression professionnelle","topic":"Être chargé de","sentence":"Lena is in _____ of customer complaints.","translation":"Lena est chargée des réclamations des clients.","options":["task","charge","role","duty"],"hint":"La personne organise ou dirige l’activité.","rule":"In charge of = chargé de, responsable de.","answer":1,"feedback":["Task veut dire tâche, mais in task of ne convient pas.","In charge of = chargé de, responsable de.","Role veut dire rôle. In role of ne convient pas pour cette expression.","On duty signifie en service. In duty of ne signifie pas responsable de."],"id":"q222"},{"category":"Grammaire","topic":"Comparaison","sentence":"The new printer is _____ than the one we used last year.","translation":"La nouvelle imprimante est plus efficace que celle que nous utilisions l’année dernière.","options":["most efficient","efficient","efficiently","more efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":3,"feedback":["Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficient seul ne forme pas cette comparaison avec than.","Efficiently décrit une action. Ici, on compare la qualité de deux choses.","More efficient than veut dire plus efficace que."],"id":"q223"},{"category":"Expression professionnelle","topic":"Suivre quelque chose","sentence":"Use this table to keep _____ of monthly expenses.","translation":"Utilise ce tableau pour suivre les dépenses mensuelles.","options":["attention","care","part","track"],"hint":"On veut savoir où en sont les dossiers.","rule":"Keep track of = suivre, tenir le suivi de.","answer":3,"feedback":["On dit pay attention to pour faire attention à.","On dit take care of pour s’occuper de, pas keep care of.","On dit take part in pour participer à. Ce n’est pas assurer le suivi.","Keep track of = suivre, tenir le suivi de."],"id":"q224"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The storage cabinet is wide _____ to hold these folders.","translation":"L’armoire de rangement est assez large pour contenir ces classeurs.","options":["much","very","enough","too"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":2,"feedback":["Much ne convient pas directement après cet adjectif.","Very se place avant la qualité, pas après.","Enough se place après la qualité : assez grand, assez rapide…","Too se place avant la qualité, pas après."],"id":"q225"},{"category":"Expression professionnelle","topic":"Peu de préavis","sentence":"We apologise for changing the schedule at short _____.","translation":"Nous nous excusons d’avoir modifié l’horaire avec peu de préavis.","options":["warning","news","message","notice"],"hint":"La personne a été prévenue peu de temps avant.","rule":"At short notice = avec peu de préavis.","answer":3,"feedback":["On peut dire with little warning, mais pas at short warning pour cette expression.","News veut dire nouvelles ou actualités. At short news ne convient pas.","Message veut dire message. At short message ne signifie pas avec peu de préavis.","At short notice = avec peu de préavis."],"id":"q226"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"We do not have _____ information about the new supplier yet.","translation":"Nous n’avons pas encore beaucoup d’informations sur le nouveau fournisseur.","options":["much","many","several","a few"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":0,"feedback":["Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","Many accompagne des choses comptables au pluriel, comme many files.","Several accompagne un nom comptable au pluriel, comme several minutes.","A few accompagne un nom comptable au pluriel, comme a few chairs."],"id":"q227"},{"category":"Expression professionnelle","topic":"Par écrit","sentence":"All requests must be submitted in _____.","translation":"Toutes les demandes doivent être présentées par écrit.","options":["write","written","writing","wrote"],"hint":"La confirmation doit être écrite.","rule":"In writing = par écrit.","answer":2,"feedback":["Write est le verbe écrire. In write n’est pas correct.","Written veut dire écrit. On pourrait dire in written form, mais form manque ici.","In writing = par écrit.","Wrote est la forme passée de write. Elle ne convient pas après in ici."],"id":"q228"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"The guests left _____ luggage at reception.","translation":"Les clients ont laissé leurs bagages à la réception.","options":["they","them","theirs","their"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":3,"feedback":["They veut dire ils ou elles et sert de sujet.","Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…"],"id":"q229"},{"category":"Expression professionnelle","topic":"Voyage d’affaires","sentence":"Sara is away on a business _____ this week.","translation":"Sara est en voyage d’affaires cette semaine.","options":["transport","traffic","route","trip"],"hint":"La personne voyage pour son travail.","rule":"Business trip = voyage d’affaires.","answer":3,"feedback":["Transport désigne le transport, mais business transport ne convient pas ici pour un voyage.","Traffic désigne la circulation. Ce n’est pas un voyage.","Route veut dire itinéraire. Il ne désigne pas ici le voyage lui-même.","Business trip = voyage d’affaires."],"id":"q230"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The museum has extended _____ opening hours.","translation":"Le musée a prolongé ses heures d’ouverture.","options":["it’s","itself","its","it"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":2,"feedback":["It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose.","It remplace une chose mais n’indique pas la possession devant un nom."],"id":"q231"},{"category":"Expression professionnelle","topic":"De suite","sentence":"The shop exceeded its target for three weeks in a _____.","translation":"Le magasin a dépassé son objectif pendant trois semaines de suite.","options":["queue","rank","line","row"],"hint":"Les périodes se suivent sans interruption.","rule":"In a row = de suite, consécutivement.","answer":3,"feedback":["In a queue signifie dans une file d’attente.","Rank peut désigner un rang ou un grade, mais in a rank ne signifie pas de suite.","In a line signifie en ligne, comme des personnes alignées.","In a row = de suite, consécutivement."],"id":"q232"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The accountant _____ prepared the figures is on holiday.","translation":"Le comptable qui a préparé les chiffres est en vacances.","options":["which","whom","whose","who"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":3,"feedback":["Which reprend généralement une chose. Ici, c’est une personne.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Who reprend une personne qui fait l’action juste après."],"id":"q233"},{"category":"Expression professionnelle","topic":"Rupture de stock","sentence":"The blue jackets are currently out of _____.","translation":"Les vestes bleues sont actuellement en rupture de stock.","options":["stock","receipt","sale","invoice"],"hint":"Il n’en reste plus à vendre ; de nouveaux exemplaires arrivent bientôt.","rule":"Out of stock = en rupture de stock.","answer":0,"feedback":["Out of stock = en rupture de stock.","Receipt signifie reçu. Out of receipt ne convient pas.","For sale veut dire à vendre. Out of sale n’est pas l’expression rupture de stock.","Invoice signifie facture. Out of invoice ne convient pas."],"id":"q234"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The shipment arrived late _____ heavy traffic.","translation":"La livraison est arrivée en retard à cause d’une circulation dense.","options":["so that","because of","because","although"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":1,"feedback":["So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because of veut dire à cause de et peut être suivi de cette chose.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Although veut dire bien que et demande ici une phrase avec un sujet et un verbe."],"id":"q235"},{"category":"Expression professionnelle","topic":"Appareil en panne","sentence":"The photocopier is out of _____ again.","translation":"La photocopieuse est de nouveau en panne.","options":["arrangement","order","sequence","stock"],"hint":"L’appareil ne fonctionne plus.","rule":"Out of order = en panne.","answer":1,"feedback":["Arrangement peut signifier organisation. Out of arrangement ne signifie pas en panne.","Out of order = en panne.","Out of sequence veut dire dans le désordre, pas en panne.","Out of stock signifie qu’il n’en reste plus à vendre. Ici, l’appareil est présent mais ne fonctionne pas."],"id":"q236"},{"category":"Grammaire","topic":"Accord au présent","sentence":"The shop assistant _____ until six every Saturday.","translation":"Le vendeur travaille jusqu’à six heures chaque samedi.","options":["working","to work","works","work"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":2,"feedback":["Working seul ne constitue pas un verbe conjugué complet.","To work n’est pas le verbe conjugué nécessaire ici.","Le sujet est une seule personne : au présent, on ajoute s à work.","Work sans s convient notamment avec they, pas avec ce sujet singulier."],"id":"q237"},{"category":"Expression professionnelle","topic":"Conformément à","sentence":"The data will be stored in _____ with company policy.","translation":"Les données seront conservées conformément à la politique de l’entreprise.","options":["accordance","accorded","according","accordingly"],"hint":"Respecter une règle : in … with.","rule":"In accordance with = conformément à.","answer":0,"feedback":["In accordance with = conformément à.","Accorded est une forme verbale. L’expression fixe est in accordance with.","According s’utilise avec to : according to. On ne mélange pas avec in … with.","Accordingly veut dire en conséquence. In accordingly with ne convient pas."],"id":"q238"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The regional manager _____ our shop yesterday.","translation":"Le responsable régional a visité notre magasin hier.","options":["visiting","visits","visited","has visited"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":2,"feedback":["Visiting seul n’est pas un verbe conjugué complet.","Visits est au présent. La phrase situe l’action dans le passé.","Visited est au passé. Le moment indiqué est terminé.","Has visited ne s’utilise pas ici avec ce moment passé terminé."],"id":"q239"},{"category":"Expression professionnelle","topic":"Selon","sentence":"According _____ the timetable, the train leaves at six.","translation":"Selon l’horaire, le train part à six heures.","options":["at","with","to","for"],"hint":"Repère according : quel petit mot vient avec lui ?","rule":"According to = selon.","answer":2,"feedback":["According at n’est pas l’expression selon.","With appartient à in accordance with. Avec according, on utilise to.","According to = selon.","According for n’est pas l’expression selon."],"id":"q240"},{"category":"Grammaire","topic":"Condition future","sentence":"If you approve the design today, we _____ the files tomorrow.","translation":"Si tu approuves le modèle aujourd’hui, nous enverrons les fichiers demain.","options":["has sent","sent","sending","will send"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":3,"feedback":["Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Sent est au passé. Ici, le résultat attendu est futur.","Sending seul n’est pas un verbe conjugué complet.","Will send indique ce qui se passera si la condition se réalise."],"id":"q241"},{"category":"Expression professionnelle","topic":"Attendre avec plaisir","sentence":"We look forward _____ hearing from you soon.","translation":"Nous attendons avec plaisir de tes nouvelles prochainement.","options":["for","at","on","to"],"hint":"On se réjouit de ce qui va arriver.","rule":"Look forward to + nom ou -ing = attendre avec plaisir.","answer":3,"feedback":["On dit wait for, mais look forward to.","At ne complète pas look forward.","On ne complète pas look forward.","Look forward to + nom ou -ing = attendre avec plaisir."],"id":"q242"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The owners painted the shop by _____, without hiring a decorator.","translation":"Les propriétaires ont peint le magasin eux-mêmes, sans engager de décorateur.","options":["theirs","their","they","themselves"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":3,"feedback":["Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","Their doit être suivi d’un nom, comme their work.","They sert de sujet et ne vient pas après by ici.","By themselves veut dire eux-mêmes, sans aide."],"id":"q243"},{"category":"Expression professionnelle","topic":"Se conformer aux règles","sentence":"Suppliers must comply _____ our quality standards.","translation":"Les fournisseurs doivent respecter nos normes de qualité.","options":["with","to","on","for"],"hint":"Respecter des règles se dit comply…","rule":"Comply with = se conformer à.","answer":0,"feedback":["Comply with = se conformer à.","On dit conform to, mais comply with.","On ne complète pas comply dans cette expression.","For ne complète pas comply dans cette expression."],"id":"q244"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"We are waiting for the manager’s _____ before placing the order.","translation":"Nous attendons l’accord du responsable avant de passer la commande.","options":["approve","approves","approval","approved"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":2,"feedback":["Approve est un verbe : approuver. Ici, on cherche une chose.","Approves est un verbe conjugué. Ici, il faut un nom.","Approval est un nom : l’accord ou l’approbation.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même."],"id":"q245"},{"category":"Expression professionnelle","topic":"Compter sur","sentence":"You can rely _____ our support team for help.","translation":"Tu peux compter sur notre équipe d’assistance.","options":["with","at","on","for"],"hint":"Rely signifie compter sur quelqu’un.","rule":"Rely on = compter sur.","answer":2,"feedback":["With signifie avec. Pour compter sur, on utilise rely on.","At ne convient pas après rely.","Rely on = compter sur.","For peut introduire ce qu’on attend, mais la personne vient après on : rely on someone for help."],"id":"q246"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The replacement parts will _____ on Thursday.","translation":"Les pièces de rechange arriveront jeudi.","options":["arrived","arrive","arrives","arriving"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":1,"feedback":["Arrived est au passé. Après will, on garde arrive.","Après will, on garde la forme simple : arrive.","On n’ajoute pas de s au verbe après will.","Arriving ne suit pas directement will ; il faudrait une autre construction."],"id":"q247"},{"category":"Expression professionnelle","topic":"S’occuper de demandes","sentence":"Our agent will deal _____ the booking change.","translation":"Notre agent s’occupera de la modification de la réservation.","options":["with","on","at","for"],"hint":"Deal… signifie ici traiter ou gérer.","rule":"Deal with = traiter, s’occuper de.","answer":0,"feedback":["Deal with = traiter, s’occuper de.","On ne convient pas dans cette expression. Deal with signifie traiter.","At ne convient pas après deal pour dire traiter une demande.","For ne convient pas dans deal with a complaint."],"id":"q248"},{"category":"Grammaire","topic":"Après enjoy","sentence":"The designers enjoy _____ on challenging projects.","translation":"Les designers aiment travailler sur des projets difficiles.","options":["worked","to work","working","work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":2,"feedback":["Worked est au passé et ne convient pas après enjoy ici.","Enjoy ne se construit pas avec to work. On utilise working.","Après enjoy, on utilise ici working : aimer travailler.","Work seul ne suit pas enjoy dans cette construction."],"id":"q249"},{"category":"Expression professionnelle","topic":"Faire attention","sentence":"Please _____ attention to the expiry date.","translation":"Fais attention à la date d’expiration.","options":["hold","pay","do","make"],"hint":"On demande d’être attentif.","rule":"Pay attention to = faire attention à.","answer":1,"feedback":["Hold someone’s attention signifie retenir son attention. Hold attention to ne convient pas.","Pay attention to = faire attention à.","Do attention ne convient pas. On dit pay attention.","Make attention ne convient pas. On dit pay attention."],"id":"q250"},{"category":"Grammaire","topic":"Obligation","sentence":"Laboratory assistants must _____ gloves when handling these samples.","translation":"Les assistants de laboratoire doivent porter des gants lorsqu’ils manipulent ces échantillons.","options":["wearing","wore","wears","wear"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":3,"feedback":["Wearing porte -ing. Cette forme ne suit pas directement must.","Wore est au passé. Après must, il faut la forme simple wear.","Wears porte un s. Après must, on garde wear sans s.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle."],"id":"q251"},{"category":"Expression professionnelle","topic":"Prendre contact","sentence":"Get in _____ with us if your address changes.","translation":"Prends contact avec nous si ton adresse change.","options":["speak","touch","reach","call"],"hint":"Une expression pour contacter quelqu’un : get in…","rule":"Get in touch with = prendre contact avec.","answer":1,"feedback":["Speak veut dire parler. On peut dire speak with someone, mais pas get in speak with.","Get in touch with = prendre contact avec.","In reach peut vouloir dire à portée. Get in reach with ne veut pas dire contacter.","Call veut dire appeler, mais get in call with ne convient pas."],"id":"q252"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The tickets _____ sent to all participants yesterday.","translation":"Les billets ont été envoyés à tous les participants hier.","options":["are","have","were","was"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":2,"feedback":["Are est au présent. Le moment indiqué est passé.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé.","Was accompagne une seule chose. Le sujet est au pluriel."],"id":"q253"},{"category":"Expression professionnelle","topic":"Effectuer","sentence":"The company will _____ out a customer survey.","translation":"L’entreprise effectuera une enquête auprès des clients.","options":["turn","put","carry","bring"],"hint":"Il faut réaliser une inspection ou un contrôle.","rule":"Carry out = effectuer, réaliser.","answer":2,"feedback":["Turn out peut signifier se révéler. Il ne signifie pas effectuer une inspection.","Put out peut signifier éteindre. Il ne signifie pas effectuer des contrôles.","Carry out = effectuer, réaliser.","Bring out peut signifier publier ou faire ressortir. Il ne signifie pas effectuer ici."],"id":"q254"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The presentation _____ prepared by the sales team last week.","translation":"La présentation a été préparée par l’équipe commerciale la semaine dernière.","options":["was","were","is","has"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":0,"feedback":["Was convient pour une seule chose, dans le passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Is est au présent. La phrase indique un moment passé.","Has ne forme pas le passif ici. Le sujet reçoit l’action."],"id":"q255"},{"category":"Expression professionnelle","topic":"Organiser une réunion","sentence":"Let us _____ up a meeting for Tuesday morning.","translation":"Organisons une réunion mardi matin.","options":["break","give","take","set"],"hint":"L’expression avec up signifie organiser.","rule":"Set up = organiser, mettre en place.","answer":3,"feedback":["Break up signifie notamment se séparer ou disperser, pas organiser.","Give up signifie abandonner.","Take up peut signifier commencer une activité ou occuper du temps. Il ne signifie pas organiser une réunion.","Set up = organiser, mettre en place."],"id":"q256"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Every applicant _____ a scheduled interview time.","translation":"Chaque candidat a un horaire d’entretien fixé.","options":["has","have","are","having"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":0,"feedback":["Each ou every présente une personne à la fois : on utilise has.","Have ne convient pas avec ce sujet singulier.","Are veut dire sont. Il ne convient ni au singulier ni au sens.","Having seul ne fait pas un verbe conjugué complet."],"id":"q257"},{"category":"Expression professionnelle","topic":"Reporter","sentence":"We may have to _____ off the product launch.","translation":"Nous devrons peut-être reporter le lancement du produit.","options":["put","turn","set","take"],"hint":"La date est repoussée à plus tard.","rule":"Put off = reporter à plus tard.","answer":0,"feedback":["Put off = reporter à plus tard.","Turn off signifie notamment éteindre un appareil.","Set off peut signifier partir ou déclencher. Il ne signifie pas reporter.","Take off peut signifier décoller ou enlever."],"id":"q258"},{"category":"Grammaire","topic":"Manière de faire","sentence":"The technician examined the damaged cable _____.","translation":"Le technicien a examiné le câble endommagé avec attention.","options":["careful","care","careless","carefully"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":3,"feedback":["Careful décrit une personne ou une chose. Ici, on décrit une action.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Carefully explique comment faire l’action : avec attention."],"id":"q259"},{"category":"Expression professionnelle","topic":"Refuser une offre","sentence":"The candidate may turn _____ our offer.","translation":"Le candidat pourrait refuser notre offre.","options":["off","out","into","down"],"hint":"Turn… signifie ici refuser.","rule":"Turn down = refuser une offre ou une demande.","answer":3,"feedback":["Turn off signifie notamment éteindre.","Turn out peut signifier se révéler. Il ne signifie pas refuser cette offre.","Turn into veut dire se transformer en. Ici, il ne s’agit pas d’une transformation.","Turn down = refuser une offre ou une demande."],"id":"q260"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"We are looking for a _____ courier to deliver legal documents.","translation":"Nous recherchons un coursier fiable pour livrer des documents juridiques.","options":["rely","reliability","reliable","reliably"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":2,"feedback":["Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliability est le nom fiabilité. Ici, on cherche une qualité.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliably décrit comment on fait une action, pas directement une chose."],"id":"q261"},{"category":"Expression professionnelle","topic":"Remplir les informations","sentence":"Please _____ in your contact information below.","translation":"Complète tes coordonnées ci-dessous.","options":["fill","set","break","come"],"hint":"On complète ce qui manque sur un document.","rule":"Fill in = remplir, compléter.","answer":0,"feedback":["Fill in = remplir, compléter.","Set in décrit notamment une situation qui s’installe, comme le froid. Il ne signifie pas remplir.","Break in peut vouloir dire entrer par effraction.","Come in veut dire entrer. Il ne signifie pas remplir les informations."],"id":"q262"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"Several _____ for the trainee position arrived this morning.","translation":"Plusieurs candidatures pour le poste de stagiaire sont arrivées ce matin.","options":["applicable","applying","apply","applications"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":3,"feedback":["Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature.","Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applications est un nom au pluriel : des candidatures."],"id":"q263"},{"category":"Expression professionnelle","topic":"Ne plus avoir","sentence":"The office has run _____ of envelopes.","translation":"Le bureau n’a plus d’enveloppes.","options":["through","away","out","over"],"hint":"Le stock est épuisé : run… of.","rule":"Run out of = ne plus avoir, épuiser son stock de.","answer":2,"feedback":["Run through peut signifier parcourir ou passer en revue. Run through of ne convient pas.","Run away signifie s’enfuir.","Run out of = ne plus avoir, épuiser son stock de.","Run over ne forme pas l’expression ne plus avoir avec of."],"id":"q264"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"We have used this accounting software _____ 2022.","translation":"Nous utilisons ce logiciel de comptabilité depuis 2022.","options":["since","for","until","during"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":0,"feedback":["Since indique quand la période a commencé.","For sert à donner une durée, comme for three years.","Until indique une fin. Ici, on indique le début d’une période encore en cours.","During veut dire pendant. Il ne marque pas ici le début de la période."],"id":"q265"},{"category":"Expression professionnelle","topic":"Licencier du personnel","sentence":"The company does not plan to _____ off any employees.","translation":"L’entreprise ne prévoit de licencier aucun employé.","options":["remove","pick","lay","resign"],"hint":"L’entreprise doit supprimer des emplois : … off.","rule":"Lay off = licencier, souvent pour des raisons économiques.","answer":2,"feedback":["Remove veut dire retirer. Il ne se construit pas avec off employees pour licencier.","Pick off peut signifier éliminer une cible, pas licencier du personnel.","Lay off = licencier, souvent pour des raisons économiques.","Resign veut dire démissionner. On ne dit pas resign off employees."],"id":"q266"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"We have supplied this restaurant _____ ten years.","translation":"Nous fournissons ce restaurant depuis dix ans.","options":["from","since","for","during"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":2,"feedback":["From donne un départ. Ici, la phrase donne une durée.","Since introduit un début précis, comme since Monday.","For introduit la durée : combien de temps cela dure.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule."],"id":"q267"},{"category":"Expression professionnelle","topic":"Examiner un problème","sentence":"The IT team is looking _____ the connection problem.","translation":"L’équipe informatique examine le problème de connexion.","options":["forward","between","after","into"],"hint":"L’équipe va chercher ce qui ne fonctionne pas.","rule":"Look into = examiner, enquêter sur.","answer":3,"feedback":["Look forward to signifie attendre avec plaisir. Ici, il n’y a pas to et on examine un problème.","Look between signifie regarder entre des choses. Cela ne convient pas ici.","Look after signifie prendre soin de. Ce n’est pas examiner la cause d’un problème.","Look into = examiner, enquêter sur."],"id":"q268"},{"category":"Grammaire","topic":"Après décider","sentence":"We decided _____ a second account for travel expenses.","translation":"Nous avons décidé d’ouvrir un deuxième compte pour les frais de déplacement.","options":["opening","to open","opened","open"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":1,"feedback":["Opening ne suit pas directement decided dans cette construction.","Decide to open veut dire décider d’ouvrir.","Opened est une forme passée. Après decided, on utilise ici to open.","Il manque to entre decided et open."],"id":"q269"},{"category":"Expression professionnelle","topic":"Annuler","sentence":"The organiser decided to call _____ tomorrow’s concert.","translation":"L’organisateur a décidé d’annuler le concert de demain.","options":["off","over","away","down"],"hint":"Call… signifie ici annuler complètement.","rule":"Call off = annuler.","answer":0,"feedback":["Call off = annuler.","Call over peut signifier appeler quelqu’un pour qu’il s’approche. Ce n’est pas annuler.","Away ne forme pas avec call l’expression annuler un événement.","Call down ne signifie pas annuler ce concert."],"id":"q270"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Check that all windows are closed before _____ the meeting room.","translation":"Vérifie que toutes les fenêtres sont fermées avant de quitter la salle de réunion.","options":["leave","leaving","left","leaves"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":1,"feedback":["Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Après before ou after sans nouveau sujet, leaving convient.","Left est au passé. Cette forme ne convient pas directement ici.","Leaves aurait besoin d’un sujet, par exemple she leaves."],"id":"q271"},{"category":"Expression professionnelle","topic":"Réduire","sentence":"The hotel wants to _____ down on water use.","translation":"L’hôtel veut réduire sa consommation d’eau.","options":["make","cut","take","give"],"hint":"On veut réduire une consommation : … down on.","rule":"Cut down on = réduire sa consommation de.","answer":1,"feedback":["Make down on ne convient pas. Pour réduire, on dit cut down on.","Cut down on = réduire sa consommation de.","Take down peut signifier noter ou démonter, mais take down on ne signifie pas réduire.","Give down on ne forme pas cette expression."],"id":"q272"},{"category":"Grammaire","topic":"Comparaison","sentence":"This heating system is _____ than our previous model.","translation":"Ce système de chauffage est plus efficace que notre modèle précédent.","options":["more efficient","most efficient","efficiently","efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":0,"feedback":["More efficient than veut dire plus efficace que.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficiently décrit une action. Ici, on compare la qualité de deux choses.","Efficient seul ne forme pas cette comparaison avec than."],"id":"q273"},{"category":"Expression professionnelle","topic":"Proposer une idée","sentence":"Can anyone _____ up with a better name?","translation":"Quelqu’un peut-il proposer un meilleur nom ?","options":["make","send","bring","come"],"hint":"Trouver une idée se dit … up with.","rule":"Come up with = trouver, proposer une idée.","answer":3,"feedback":["Make up a story signifie inventer une histoire, sans with. Make up with ne signifie pas trouver une solution.","Send signifie envoyer. Send up with ne signifie pas proposer une idée.","Bring up a subject signifie aborder un sujet, sans with. Bring up with ne convient pas ici.","Come up with = trouver, proposer une idée."],"id":"q274"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The report is clear _____ for a new employee to understand.","translation":"Le rapport est assez clair pour qu’un nouvel employé le comprenne.","options":["enough","very","much","too"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":0,"feedback":["Enough se place après la qualité : assez grand, assez rapide…","Very se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif.","Too se place avant la qualité, pas après."],"id":"q275"},{"category":"Expression professionnelle","topic":"Provisoirement","sentence":"The reception desk is upstairs for the time _____.","translation":"L’accueil se trouve provisoirement à l’étage.","options":["being","be","been","was"],"hint":"Il s’agit d’une solution pour le moment.","rule":"For the time being = pour le moment.","answer":0,"feedback":["For the time being = pour le moment.","Be ne complète pas cette expression fixe.","Been est une forme de be. L’expression pour le moment est for the time being.","Was indique le passé de be ; il ne complète pas cette expression."],"id":"q276"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"There is not _____ space in the delivery van.","translation":"Il n’y a pas beaucoup de place dans la camionnette de livraison.","options":["many","much","several","a few"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":1,"feedback":["Many accompagne des choses comptables au pluriel, comme many files.","Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","Several accompagne un nom comptable au pluriel, comme several minutes.","A few accompagne un nom comptable au pluriel, comme a few chairs."],"id":"q277"},{"category":"Expression professionnelle","topic":"Dès que possible","sentence":"Please return the signed form as soon _____ possible.","translation":"Rends le formulaire signé dès que possible.","options":["so","like","than","as"],"hint":"As soon… possible signifie dès que possible.","rule":"As soon as possible = dès que possible.","answer":3,"feedback":["So ne termine pas la construction as soon as possible.","Like peut signifier comme, mais as soon like possible ne convient pas.","Than sert souvent à comparer : faster than. Ici, on utilise as … as.","As soon as possible = dès que possible."],"id":"q278"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"All drivers must check _____ vehicles before starting work.","translation":"Tous les chauffeurs doivent vérifier leur véhicule avant de commencer le travail.","options":["theirs","they","their","them"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":2,"feedback":["Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","They veut dire ils ou elles et sert de sujet.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","Them remplace des personnes après un verbe ou une préposition, pas devant ce nom."],"id":"q279"},{"category":"Expression professionnelle","topic":"Au plus tard","sentence":"The invoice must be paid no later _____ the end of the month.","translation":"La facture doit être payée au plus tard à la fin du mois.","options":["as","than","then","that"],"hint":"No later… indique la dernière date possible.","rule":"No later than = au plus tard.","answer":1,"feedback":["As s’utilise dans as late as, mais ici il faut no later than.","No later than = au plus tard.","Then veut dire ensuite. Ne le confonds pas avec than, utilisé pour comparer.","That ne complète pas la comparaison no later than."],"id":"q280"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The hotel is renovating _____ main entrance.","translation":"L’hôtel rénove son entrée principale.","options":["it’s","itself","its","it"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":2,"feedback":["It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose.","It remplace une chose mais n’indique pas la possession devant un nom."],"id":"q281"},{"category":"Expression professionnelle","topic":"À côté de","sentence":"The printer is next _____ the filing cabinet.","translation":"L’imprimante se trouve à côté du classeur.","options":["to","at","for","with"],"hint":"Next… indique ce qui se trouve juste à côté.","rule":"Next to = à côté de.","answer":0,"feedback":["Next to = à côté de.","At peut indiquer un lieu, mais next at ne convient pas.","For ne complète pas next dans cette expression.","With veut dire avec. Pour à côté de, on dit next to."],"id":"q282"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The technician _____ repaired the lift will return tomorrow.","translation":"Le technicien qui a réparé l’ascenseur reviendra demain.","options":["which","whose","who","whom"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":2,"feedback":["Which reprend généralement une chose. Ici, c’est une personne.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Who reprend une personne qui fait l’action juste après.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who."],"id":"q283"},{"category":"Expression professionnelle","topic":"En plus de","sentence":"In _____ to free delivery, customers receive a discount.","translation":"En plus de la livraison gratuite, les clients bénéficient d’une réduction.","options":["addition","added","additionally","additional"],"hint":"L’expression introduit une chose supplémentaire.","rule":"In addition to = en plus de.","answer":0,"feedback":["In addition to = en plus de.","Added veut dire ajouté. Il ne forme pas in addition to.","Additionally signifie en plus, mais s’utilise sans in … to.","Additional décrit quelque chose de supplémentaire, comme additional costs. Après in ici, il faut le nom addition."],"id":"q284"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The office was closed _____ a power failure.","translation":"Le bureau était fermé à cause d’une panne de courant.","options":["although","so that","because","because of"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":3,"feedback":["Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Because of veut dire à cause de et peut être suivi de cette chose."],"id":"q285"},{"category":"Expression professionnelle","topic":"En raison de","sentence":"The museum closed early _____ to a water leak.","translation":"Le musée a fermé plus tôt en raison d’une fuite d’eau.","options":["because","due","cause","owed"],"hint":"Le mot suivant le trou est to.","rule":"Due to = en raison de.","answer":1,"feedback":["Because se construit avec of devant un nom : because of fog. Ici, to est déjà présent.","Due to = en raison de.","Cause veut dire cause ou causer, mais cause to ne forme pas cette expression.","Owed veut dire dû au sens d’une dette. Ici, on indique une cause : due to."],"id":"q286"},{"category":"Grammaire","topic":"Accord au présent","sentence":"Our accountant _____ from home on Fridays.","translation":"Notre comptable travaille à domicile le vendredi.","options":["working","work","to work","works"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":3,"feedback":["Working seul ne constitue pas un verbe conjugué complet.","Work sans s convient notamment avec they, pas avec ce sujet singulier.","To work n’est pas le verbe conjugué nécessaire ici.","Le sujet est une seule personne : au présent, on ajoute s à work."],"id":"q287"},{"category":"Expression professionnelle","topic":"À la demande","sentence":"Large-print documents are available on _____.","translation":"Des documents en grands caractères sont disponibles sur demande.","options":["ask","requested","request","requesting"],"hint":"L’expression signifie si quelqu’un le demande.","rule":"On request = sur demande.","answer":2,"feedback":["Ask est un verbe : demander. On request utilise un nom.","Requested signifie demandé. On requested ne convient pas ici.","On request = sur demande.","Requesting est une forme en -ing. L’expression est on request."],"id":"q288"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"Our new director _____ the warehouse last Friday.","translation":"Notre nouvelle directrice a visité l’entrepôt vendredi dernier.","options":["visiting","has visited","visited","visits"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":2,"feedback":["Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visited est au passé. Le moment indiqué est terminé.","Visits est au présent. La phrase situe l’action dans le passé."],"id":"q289"},{"category":"Expression professionnelle","topic":"À temps","sentence":"The technician arrived in _____ to prevent further damage.","translation":"Le technicien est arrivé à temps pour éviter d’autres dégâts.","options":["hour","minute","clock","time"],"hint":"On arrive avant qu’il ne soit trop tard : in…","rule":"In time = à temps.","answer":3,"feedback":["Hour signifie heure, mais in hour ne signifie pas à temps.","Minute ne forme pas cette expression. In a minute voudrait dire dans une minute.","Clock signifie horloge. In clock ne convient pas.","In time = à temps."],"id":"q290"},{"category":"Grammaire","topic":"Condition future","sentence":"If the payment arrives today, I _____ your receipt tomorrow morning.","translation":"Si le paiement arrive aujourd’hui, j’enverrai ton reçu demain matin.","options":["will send","has sent","sending","sent"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":0,"feedback":["Will send indique ce qui se passera si la condition se réalise.","Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Sending seul n’est pas un verbe conjugué complet.","Sent est au passé. Ici, le résultat attendu est futur."],"id":"q291"},{"category":"Expression professionnelle","topic":"D’avance sur le planning","sentence":"Construction is two weeks _____ of schedule.","translation":"La construction a deux semaines d’avance sur le planning.","options":["early","before","front","ahead"],"hint":"La tâche est finie plus tôt que prévu : … of schedule.","rule":"Ahead of schedule = en avance sur le planning.","answer":3,"feedback":["Early veut dire tôt. Early of schedule ne convient pas.","Before veut dire avant et peut être suivi directement d’un nom. Before of ne convient pas.","In front of indique devant dans l’espace. Front of schedule ne convient pas.","Ahead of schedule = en avance sur le planning."],"id":"q292"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The students organised the event by _____, without any help.","translation":"Les étudiants ont organisé l’événement seuls, sans aucune aide.","options":["they","themselves","theirs","their"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":1,"feedback":["They sert de sujet et ne vient pas après by ici.","By themselves veut dire eux-mêmes, sans aide.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","Their doit être suivi d’un nom, comme their work."],"id":"q293"},{"category":"Expression professionnelle","topic":"Dans les limites du budget","sentence":"The event stayed _____ budget despite the late changes.","translation":"L’événement est resté dans les limites du budget malgré les changements tardifs.","options":["among","within","along","between"],"hint":"Les dépenses ne dépassent pas la somme prévue.","rule":"Within budget = dans les limites du budget.","answer":1,"feedback":["Among veut dire parmi. Il ne signifie pas dans les limites d’une somme.","Within budget = dans les limites du budget.","Along veut dire le long de. Il ne convient pas pour parler de dépenses limitées.","Between veut dire entre, par exemple entre deux montants. Ici, il n’y a qu’un budget."],"id":"q294"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"The project cannot start without the board’s _____.","translation":"Le projet ne peut pas commencer sans l’approbation du conseil d’administration.","options":["approved","approval","approve","approves"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":1,"feedback":["Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même.","Approval est un nom : l’accord ou l’approbation.","Approve est un verbe : approuver. Ici, on cherche une chose.","Approves est un verbe conjugué. Ici, il faut un nom."],"id":"q295"},{"category":"Expression professionnelle","topic":"En cas de","sentence":"In _____ of an accident, inform your supervisor.","translation":"En cas d’accident, informe ton superviseur.","options":["condition","situation","case","happens"],"hint":"Une consigne pour une éventuelle urgence : in… of.","rule":"In case of = en cas de.","answer":2,"feedback":["Condition peut désigner une condition. In condition of ne signifie pas en cas de.","Situation ne forme pas l’expression in case of.","In case of = en cas de.","Happens est un verbe : se produit. In happens of n’est pas correct."],"id":"q296"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"Our overseas guests will _____ at the hotel this evening.","translation":"Nos invités étrangers arriveront à l’hôtel ce soir.","options":["arriving","arrived","arrives","arrive"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":3,"feedback":["Arriving ne suit pas directement will ; il faudrait une autre construction.","Arrived est au passé. Après will, on garde arrive.","On n’ajoute pas de s au verbe après will.","Après will, on garde la forme simple : arrive."],"id":"q297"},{"category":"Expression professionnelle","topic":"Changer d’avis","sentence":"You can cancel the booking if you change your _____.","translation":"Tu peux annuler la réservation si tu changes d’avis.","options":["thought","mind","brain","minded"],"hint":"La personne ne veut plus la même chose : change one’s…","rule":"Change your mind = changer d’avis.","answer":1,"feedback":["Thought veut dire pensée. L’expression changer d’avis est change your mind.","Change your mind = changer d’avis.","Brain veut dire cerveau. Changer d’avis ne signifie pas changer de cerveau !","Minded est une forme qu’on trouve dans des adjectifs comme open-minded. Ici, il faut le nom mind."],"id":"q298"},{"category":"Grammaire","topic":"Après enjoy","sentence":"She enjoys _____ with international customers.","translation":"Elle aime travailler avec des clients internationaux.","options":["working","worked","work","to work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":0,"feedback":["Après enjoy, on utilise ici working : aimer travailler.","Worked est au passé et ne convient pas après enjoy ici.","Work seul ne suit pas enjoy dans cette construction.","Enjoy ne se construit pas avec to work. On utilise working."],"id":"q299"},{"category":"Expression professionnelle","topic":"Être en congé","sentence":"Two members of our team are on _____ today.","translation":"Deux membres de notre équipe sont en congé aujourd’hui.","options":["leaves","leave","leaving","left"],"hint":"La personne ne travaille pas pendant quelques jours.","rule":"On leave = en congé.","answer":1,"feedback":["Leaves peut désigner des feuilles ou signifier part au présent. Dans on leave, le nom ne prend pas de s.","On leave = en congé.","Leaving évoque l’action de partir. Ici, on cherche le nom congé.","Left peut vouloir dire parti ou gauche. Le nom congé est leave."],"id":"q300"},{"category":"Grammaire","topic":"Obligation","sentence":"Hotel staff must _____ name tags during their shifts.","translation":"Le personnel de l’hôtel doit porter un badge nominatif pendant ses heures de travail.","options":["wear","wears","wore","wearing"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":0,"feedback":["Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wears porte un s. Après must, on garde wear sans s.","Wore est au passé. Après must, il faut la forme simple wear.","Wearing porte -ing. Cette forme ne suit pas directement must."],"id":"q301"},{"category":"Expression professionnelle","topic":"Respecter une échéance","sentence":"Can we _____ the deadline without hiring extra staff?","translation":"Pouvons-nous respecter l’échéance sans engager de personnel supplémentaire ?","options":["arrive","join","attend","meet"],"hint":"L’équipe veut finir à temps.","rule":"Meet a deadline = respecter une échéance.","answer":3,"feedback":["Arrive veut dire arriver. Il ne se place pas directement devant the deadline ici.","Join veut dire rejoindre une personne ou un groupe.","Attend veut dire assister à un événement. Une date limite n’est pas un événement auquel on assiste.","Meet a deadline = respecter une échéance."],"id":"q302"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The computers _____ installed by the IT team two weeks ago.","translation":"Les ordinateurs ont été installés par l’équipe informatique il y a deux semaines.","options":["are","have","was","were"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":3,"feedback":["Are est au présent. Le moment indiqué est passé.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Was accompagne une seule chose. Le sujet est au pluriel.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé."],"id":"q303"},{"category":"Expression professionnelle","topic":"Passer une commande","sentence":"Please _____ your order before noon.","translation":"Passe ta commande avant midi, s’il te plaît.","options":["borrow","attend","place","spend"],"hint":"On veut commander quelque chose.","rule":"Place an order = passer une commande.","answer":2,"feedback":["Borrow veut dire emprunter. Ici, on commande des produits.","Attend veut dire assister à une réunion ou à un événement.","Place an order = passer une commande.","Spend veut dire dépenser de l’argent ou passer du temps."],"id":"q304"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The entrance _____ blocked by a fallen tree yesterday morning.","translation":"L’entrée a été bloquée par un arbre tombé hier matin.","options":["is","were","was","has"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":2,"feedback":["Is est au présent. La phrase indique un moment passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Was convient pour une seule chose, dans le passé.","Has ne forme pas le passif ici. Le sujet reçoit l’action."],"id":"q305"},{"category":"Expression professionnelle","topic":"Demander à obtenir","sentence":"She plans to apply _____ the vacant position.","translation":"Elle prévoit de postuler au poste vacant.","options":["on","at","with","for"],"hint":"Repère apply : on demande à obtenir quelque chose.","rule":"Apply for something = faire une demande pour obtenir quelque chose.","answer":3,"feedback":["On ne convient pas ici : apply for indique ce qu’on demande à obtenir.","At sert notamment à indiquer un lieu. Pour demander à obtenir, on dit apply for.","With veut dire avec. Il ne complète pas cette expression.","Apply for something = faire une demande pour obtenir quelque chose."],"id":"q306"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Each package _____ a tracking number.","translation":"Chaque colis possède un numéro de suivi.","options":["has","are","have","having"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":0,"feedback":["Each ou every présente une personne à la fois : on utilise has.","Are veut dire sont. Il ne convient ni au singulier ni au sens.","Have ne convient pas avec ce sujet singulier.","Having seul ne fait pas un verbe conjugué complet."],"id":"q307"},{"category":"Expression professionnelle","topic":"Responsable de","sentence":"Who is responsible _____ updating the website?","translation":"Qui est responsable de la mise à jour du site Internet ?","options":["for","by","with","at"],"hint":"La phrase indique la tâche dont la personne est responsable.","rule":"Responsible for = responsable de.","answer":0,"feedback":["Responsible for = responsable de.","By ne complète pas responsible pour indiquer la responsabilité.","With ne complète pas responsible pour indiquer une tâche.","At convient dans good at, mais pas pour dire responsable de."],"id":"q308"},{"category":"Grammaire","topic":"Manière de faire","sentence":"Read the small print _____ before signing the agreement.","translation":"Lis attentivement les clauses en petits caractères avant de signer l’accord.","options":["careless","care","carefully","careful"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":2,"feedback":["Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Carefully explique comment faire l’action : avec attention.","Careful décrit une personne ou une chose. Ici, on décrit une action."],"id":"q309"},{"category":"Expression professionnelle","topic":"Participer à","sentence":"Would you like to _____ part in the workshop?","translation":"Voudrais-tu participer à l’atelier ?","options":["make","do","give","take"],"hint":"On invite les personnes à participer.","rule":"Take part in = participer à.","answer":3,"feedback":["Make part in n’est pas l’expression participer à.","Do your part veut dire faire sa part, mais do part in ne convient pas.","Give veut dire donner. L’expression participer à est take part in.","Take part in = participer à."],"id":"q310"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"The survey provides _____ information about customer preferences.","translation":"L’enquête fournit des informations fiables sur les préférences des clients.","options":["rely","reliably","reliable","reliability"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":2,"feedback":["Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliably décrit comment on fait une action, pas directement une chose.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliability est le nom fiabilité. Ici, on cherche une qualité."],"id":"q311"},{"category":"Expression professionnelle","topic":"À jour","sentence":"The directory is updated regularly to keep it up to _____.","translation":"L’annuaire est régulièrement actualisé pour rester à jour.","options":["year","day","hour","date"],"hint":"Il faut garder les informations actuelles.","rule":"Up to date = à jour.","answer":3,"feedback":["Year veut dire année. L’expression correcte reste up to date.","Day veut dire jour. On ne traduit pas à jour mot par mot.","Hour veut dire heure. Up to hour ne signifie pas à jour.","Up to date = à jour."],"id":"q312"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"We have shortlisted several _____ for the assistant manager vacancy.","translation":"Nous avons présélectionné plusieurs candidatures pour le poste vacant de responsable adjoint.","options":["applying","apply","applications","applicable"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":2,"feedback":["Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applications est un nom au pluriel : des candidatures.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature."],"id":"q313"},{"category":"Expression professionnelle","topic":"Gratuit","sentence":"The replacement will be delivered free of _____.","translation":"Le produit de remplacement sera livré gratuitement.","options":["invoice","salary","price","charge"],"hint":"Le client ne doit rien payer.","rule":"Free of charge = gratuit, sans frais.","answer":3,"feedback":["Invoice veut dire facture. Free of invoice ne signifie pas gratuit.","Salary veut dire salaire. Ici, on parle du prix d’un service.","Price veut dire prix. L’expression est free of charge.","Free of charge = gratuit, sans frais."],"id":"q314"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"Our receptionist has worked here _____ last spring.","translation":"Notre réceptionniste travaille ici depuis le printemps dernier.","options":["since","until","for","during"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":0,"feedback":["Since indique quand la période a commencé.","Until indique une fin. Ici, on indique le début d’une période encore en cours.","For sert à donner une durée, comme for three years.","During veut dire pendant. Il ne marque pas ici le début de la période."],"id":"q315"},{"category":"Expression professionnelle","topic":"Sous garantie","sentence":"Repairs remain free while the product is under _____.","translation":"Les réparations restent gratuites tant que le produit est sous garantie.","options":["purchase","invoice","receipt","warranty"],"hint":"Le fabricant couvre encore les réparations.","rule":"Under warranty = sous garantie.","answer":3,"feedback":["Purchase signifie achat. Under purchase ne signifie pas sous garantie.","Invoice est une facture, pas une garantie.","Receipt est un reçu. Under receipt ne signifie pas sous garantie.","Under warranty = sous garantie."],"id":"q316"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"The office has been empty _____ six months.","translation":"Le bureau est vide depuis six mois.","options":["since","for","from","during"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":1,"feedback":["Since introduit un début précis, comme since Monday.","For introduit la durée : combien de temps cela dure.","From donne un départ. Ici, la phrase donne une durée.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule."],"id":"q317"},{"category":"Expression professionnelle","topic":"Au nom de","sentence":"She accepted the prize on _____ of the entire team.","translation":"Elle a accepté le prix au nom de toute l’équipe.","options":["behalf","regard","side","purpose"],"hint":"Une personne parle pour tout un groupe.","rule":"On behalf of = au nom de.","answer":0,"feedback":["On behalf of = au nom de.","With regard to signifie concernant. On regard of ne convient pas.","On the side of signifie du côté de ; on side of ne convient pas.","On purpose veut dire volontairement. On purpose of ne convient pas."],"id":"q318"},{"category":"Grammaire","topic":"Après décider","sentence":"The owners decided _____ the restaurant on Sundays.","translation":"Les propriétaires ont décidé d’ouvrir le restaurant le dimanche.","options":["opening","open","opened","to open"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":3,"feedback":["Opening ne suit pas directement decided dans cette construction.","Il manque to entre decided et open.","Opened est une forme passée. Après decided, on utilise ici to open.","Decide to open veut dire décider d’ouvrir."],"id":"q319"},{"category":"Expression professionnelle","topic":"À l’avance","sentence":"Please tell us in _____ if you need special assistance.","translation":"Préviens-nous à l’avance si tu as besoin d’une assistance particulière.","options":["advance","front","ahead","early"],"hint":"L’action doit se faire avant la date prévue.","rule":"In advance = à l’avance.","answer":0,"feedback":["In advance = à l’avance.","In front indique devant dans l’espace, pas à l’avance dans le temps.","Ahead peut exprimer une avance, mais on ne dit pas in ahead.","Early veut dire tôt. On dit book early, sans in."],"id":"q320"},{"category":"Grammaire","topic":"Après une préposition","sentence":"After _____ the warehouse, the driver called his supervisor.","translation":"Après avoir quitté l’entrepôt, le chauffeur a appelé son superviseur.","options":["leave","leaves","left","leaving"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":3,"feedback":["Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Left est au passé. Cette forme ne convient pas directement ici.","Après before ou after sans nouveau sujet, leaving convient."],"id":"q321"},{"category":"Expression professionnelle","topic":"Être chargé de","sentence":"The person in _____ will contact you tomorrow.","translation":"La personne responsable te contactera demain.","options":["task","role","duty","charge"],"hint":"La personne organise ou dirige l’activité.","rule":"In charge of = chargé de, responsable de.","answer":3,"feedback":["Task veut dire tâche, mais in task of ne convient pas.","Role veut dire rôle. In role of ne convient pas pour cette expression.","On duty signifie en service. In duty of ne signifie pas responsable de.","In charge of = chargé de, responsable de."],"id":"q322"},{"category":"Grammaire","topic":"Comparaison","sentence":"The updated booking process is _____ than the old procedure.","translation":"La procédure de réservation mise à jour est plus efficace que l’ancienne.","options":["more efficient","efficient","most efficient","efficiently"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":0,"feedback":["More efficient than veut dire plus efficace que.","Efficient seul ne forme pas cette comparaison avec than.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficiently décrit une action. Ici, on compare la qualité de deux choses."],"id":"q323"},{"category":"Expression professionnelle","topic":"Suivre quelque chose","sentence":"The app helps drivers keep _____ of their deliveries.","translation":"L’application aide les chauffeurs à suivre leurs livraisons.","options":["track","care","attention","part"],"hint":"On veut savoir où en sont les dossiers.","rule":"Keep track of = suivre, tenir le suivi de.","answer":0,"feedback":["Keep track of = suivre, tenir le suivi de.","On dit take care of pour s’occuper de, pas keep care of.","On dit pay attention to pour faire attention à.","On dit take part in pour participer à. Ce n’est pas assurer le suivi."],"id":"q324"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"This laptop is light _____ to carry on business trips.","translation":"Cet ordinateur portable est assez léger pour être emporté en voyage d’affaires.","options":["much","very","enough","too"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":2,"feedback":["Much ne convient pas directement après cet adjectif.","Very se place avant la qualité, pas après.","Enough se place après la qualité : assez grand, assez rapide…","Too se place avant la qualité, pas après."],"id":"q325"},{"category":"Expression professionnelle","topic":"Peu de préavis","sentence":"Thank you for replacing your colleague at such short _____.","translation":"Merci d’avoir remplacé ton collègue avec si peu de préavis.","options":["notice","news","warning","message"],"hint":"La personne a été prévenue peu de temps avant.","rule":"At short notice = avec peu de préavis.","answer":0,"feedback":["At short notice = avec peu de préavis.","News veut dire nouvelles ou actualités. At short news ne convient pas.","On peut dire with little warning, mais pas at short warning pour cette expression.","Message veut dire message. At short message ne signifie pas avec peu de préavis."],"id":"q326"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"The task does not require _____ effort.","translation":"La tâche ne demande pas beaucoup d’effort.","options":["several","a few","many","much"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":3,"feedback":["Several accompagne un nom comptable au pluriel, comme several minutes.","A few accompagne un nom comptable au pluriel, comme a few chairs.","Many accompagne des choses comptables au pluriel, comme many files.","Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent."],"id":"q327"},{"category":"Expression professionnelle","topic":"Par écrit","sentence":"The supplier confirmed the new price in _____.","translation":"Le fournisseur a confirmé le nouveau prix par écrit.","options":["wrote","writing","written","write"],"hint":"La confirmation doit être écrite.","rule":"In writing = par écrit.","answer":1,"feedback":["Wrote est la forme passée de write. Elle ne convient pas après in ici.","In writing = par écrit.","Written veut dire écrit. On pourrait dire in written form, mais form manque ici.","Write est le verbe écrire. In write n’est pas correct."],"id":"q328"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"The candidates should bring _____ certificates to the interview.","translation":"Les candidats doivent apporter leurs certificats à l’entretien.","options":["their","theirs","they","them"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":0,"feedback":["Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","They veut dire ils ou elles et sert de sujet.","Them remplace des personnes après un verbe ou une préposition, pas devant ce nom."],"id":"q329"},{"category":"Expression professionnelle","topic":"Voyage d’affaires","sentence":"The company paid for his business _____ to Berlin.","translation":"L’entreprise a payé son voyage d’affaires à Berlin.","options":["traffic","transport","route","trip"],"hint":"La personne voyage pour son travail.","rule":"Business trip = voyage d’affaires.","answer":3,"feedback":["Traffic désigne la circulation. Ce n’est pas un voyage.","Transport désigne le transport, mais business transport ne convient pas ici pour un voyage.","Route veut dire itinéraire. Il ne désigne pas ici le voyage lui-même.","Business trip = voyage d’affaires."],"id":"q330"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The agency has moved _____ headquarters to Brussels.","translation":"L’agence a transféré son siège à Bruxelles.","options":["itself","it","it’s","its"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":3,"feedback":["Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","It remplace une chose mais n’indique pas la possession devant un nom.","It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose."],"id":"q331"},{"category":"Expression professionnelle","topic":"De suite","sentence":"He has arrived early five days in a _____.","translation":"Il est arrivé tôt cinq jours de suite.","options":["queue","rank","row","line"],"hint":"Les périodes se suivent sans interruption.","rule":"In a row = de suite, consécutivement.","answer":2,"feedback":["In a queue signifie dans une file d’attente.","Rank peut désigner un rang ou un grade, mais in a rank ne signifie pas de suite.","In a row = de suite, consécutivement.","In a line signifie en ligne, comme des personnes alignées."],"id":"q332"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"We thanked the volunteers _____ helped at the conference.","translation":"Nous avons remercié les bénévoles qui ont aidé lors de la conférence.","options":["who","whom","whose","which"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":0,"feedback":["Who reprend une personne qui fait l’action juste après.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Which reprend généralement une chose. Ici, c’est une personne."],"id":"q333"},{"category":"Expression professionnelle","topic":"Rupture de stock","sentence":"This item will remain out of _____ until next week.","translation":"Cet article restera en rupture de stock jusqu’à la semaine prochaine.","options":["stock","sale","invoice","receipt"],"hint":"Il n’en reste plus à vendre ; de nouveaux exemplaires arrivent bientôt.","rule":"Out of stock = en rupture de stock.","answer":0,"feedback":["Out of stock = en rupture de stock.","For sale veut dire à vendre. Out of sale n’est pas l’expression rupture de stock.","Invoice signifie facture. Out of invoice ne convient pas.","Receipt signifie reçu. Out of receipt ne convient pas."],"id":"q334"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"We changed suppliers _____ repeated delivery problems.","translation":"Nous avons changé de fournisseur à cause de problèmes de livraison répétés.","options":["although","because","because of","so that"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":2,"feedback":["Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Because of veut dire à cause de et peut être suivi de cette chose.","So that veut dire pour que ; il faudrait un sujet et un verbe après."],"id":"q335"},{"category":"Expression professionnelle","topic":"Appareil en panne","sentence":"One ticket machine is out of _____.","translation":"Un distributeur de billets est en panne.","options":["sequence","arrangement","stock","order"],"hint":"L’appareil ne fonctionne plus.","rule":"Out of order = en panne.","answer":3,"feedback":["Out of sequence veut dire dans le désordre, pas en panne.","Arrangement peut signifier organisation. Out of arrangement ne signifie pas en panne.","Out of stock signifie qu’il n’en reste plus à vendre. Ici, l’appareil est présent mais ne fonctionne pas.","Out of order = en panne."],"id":"q336"},{"category":"Grammaire","topic":"Accord au présent","sentence":"The security officer _____ at the main entrance every night.","translation":"L’agent de sécurité travaille à l’entrée principale chaque nuit.","options":["work","to work","working","works"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":3,"feedback":["Work sans s convient notamment avec they, pas avec ce sujet singulier.","To work n’est pas le verbe conjugué nécessaire ici.","Working seul ne constitue pas un verbe conjugué complet.","Le sujet est une seule personne : au présent, on ajoute s à work."],"id":"q337"},{"category":"Expression professionnelle","topic":"Conformément à","sentence":"Expenses must be reported in _____ with these guidelines.","translation":"Les dépenses doivent être déclarées conformément à ces directives.","options":["accordingly","accorded","according","accordance"],"hint":"Respecter une règle : in … with.","rule":"In accordance with = conformément à.","answer":3,"feedback":["Accordingly veut dire en conséquence. In accordingly with ne convient pas.","Accorded est une forme verbale. L’expression fixe est in accordance with.","According s’utilise avec to : according to. On ne mélange pas avec in … with.","In accordance with = conformément à."],"id":"q338"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The inspector _____ the kitchen two days ago.","translation":"L’inspecteur a visité la cuisine il y a deux jours.","options":["visited","visits","visiting","has visited"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":0,"feedback":["Visited est au passé. Le moment indiqué est terminé.","Visits est au présent. La phrase situe l’action dans le passé.","Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé."],"id":"q339"},{"category":"Expression professionnelle","topic":"Selon","sentence":"According _____ our records, the invoice is unpaid.","translation":"Selon nos dossiers, la facture est impayée.","options":["with","to","for","at"],"hint":"Repère according : quel petit mot vient avec lui ?","rule":"According to = selon.","answer":1,"feedback":["With appartient à in accordance with. Avec according, on utilise to.","According to = selon.","According for n’est pas l’expression selon.","According at n’est pas l’expression selon."],"id":"q340"},{"category":"Grammaire","topic":"Condition future","sentence":"If she accepts the offer, we _____ the contract next week.","translation":"Si elle accepte l’offre, nous enverrons le contrat la semaine prochaine.","options":["has sent","sending","will send","sent"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":2,"feedback":["Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Sending seul n’est pas un verbe conjugué complet.","Will send indique ce qui se passera si la condition se réalise.","Sent est au passé. Ici, le résultat attendu est futur."],"id":"q341"},{"category":"Expression professionnelle","topic":"Attendre avec plaisir","sentence":"I look forward _____ meeting the new team.","translation":"Je me réjouis de rencontrer la nouvelle équipe.","options":["on","to","at","for"],"hint":"On se réjouit de ce qui va arriver.","rule":"Look forward to + nom ou -ing = attendre avec plaisir.","answer":1,"feedback":["On ne complète pas look forward.","Look forward to + nom ou -ing = attendre avec plaisir.","At ne complète pas look forward.","On dit wait for, mais look forward to."],"id":"q342"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The assistants moved the furniture by _____, without help from the movers.","translation":"Les assistants ont déplacé les meubles eux-mêmes, sans l’aide des déménageurs.","options":["themselves","they","their","theirs"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":0,"feedback":["By themselves veut dire eux-mêmes, sans aide.","They sert de sujet et ne vient pas après by ici.","Their doit être suivi d’un nom, comme their work.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes."],"id":"q343"},{"category":"Expression professionnelle","topic":"Se conformer aux règles","sentence":"The new building complies _____ fire regulations.","translation":"Le nouveau bâtiment respecte les règles de sécurité incendie.","options":["to","on","with","for"],"hint":"Respecter des règles se dit comply…","rule":"Comply with = se conformer à.","answer":2,"feedback":["On dit conform to, mais comply with.","On ne complète pas comply dans cette expression.","Comply with = se conformer à.","For ne complète pas comply dans cette expression."],"id":"q344"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"Please obtain the supervisor’s _____ before changing your schedule.","translation":"Obtiens l’accord du superviseur avant de modifier ton horaire.","options":["approval","approve","approves","approved"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":0,"feedback":["Approval est un nom : l’accord ou l’approbation.","Approve est un verbe : approuver. Ici, on cherche une chose.","Approves est un verbe conjugué. Ici, il faut un nom.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même."],"id":"q345"},{"category":"Expression professionnelle","topic":"Compter sur","sentence":"The restaurant relies _____ local farmers for fresh produce.","translation":"Le restaurant compte sur les agriculteurs locaux pour ses produits frais.","options":["for","on","at","with"],"hint":"Rely signifie compter sur quelqu’un.","rule":"Rely on = compter sur.","answer":1,"feedback":["For peut introduire ce qu’on attend, mais la personne vient après on : rely on someone for help.","Rely on = compter sur.","At ne convient pas après rely.","With signifie avec. Pour compter sur, on utilise rely on."],"id":"q346"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The courier will _____ between nine and ten.","translation":"Le coursier arrivera entre neuf et dix heures.","options":["arrives","arriving","arrived","arrive"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":3,"feedback":["On n’ajoute pas de s au verbe après will.","Arriving ne suit pas directement will ; il faudrait une autre construction.","Arrived est au passé. Après will, on garde arrive.","Après will, on garde la forme simple : arrive."],"id":"q347"},{"category":"Expression professionnelle","topic":"S’occuper de demandes","sentence":"Who will deal _____ this urgent request?","translation":"Qui s’occupera de cette demande urgente ?","options":["with","on","for","at"],"hint":"Deal… signifie ici traiter ou gérer.","rule":"Deal with = traiter, s’occuper de.","answer":0,"feedback":["Deal with = traiter, s’occuper de.","On ne convient pas dans cette expression. Deal with signifie traiter.","For ne convient pas dans deal with a complaint.","At ne convient pas après deal pour dire traiter une demande."],"id":"q348"},{"category":"Grammaire","topic":"Après enjoy","sentence":"Our volunteers enjoy _____ at the visitor information desk.","translation":"Nos bénévoles aiment travailler au bureau d’information des visiteurs.","options":["worked","working","work","to work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":1,"feedback":["Worked est au passé et ne convient pas après enjoy ici.","Après enjoy, on utilise ici working : aimer travailler.","Work seul ne suit pas enjoy dans cette construction.","Enjoy ne se construit pas avec to work. On utilise working."],"id":"q349"},{"category":"Expression professionnelle","topic":"Faire attention","sentence":"Drivers should _____ close attention to road signs.","translation":"Les chauffeurs doivent faire très attention aux panneaux routiers.","options":["make","hold","pay","do"],"hint":"On demande d’être attentif.","rule":"Pay attention to = faire attention à.","answer":2,"feedback":["Make attention ne convient pas. On dit pay attention.","Hold someone’s attention signifie retenir son attention. Hold attention to ne convient pas.","Pay attention to = faire attention à.","Do attention ne convient pas. On dit pay attention."],"id":"q350"},{"category":"Grammaire","topic":"Obligation","sentence":"Delivery riders must _____ reflective jackets after dark.","translation":"Les livreurs à vélo doivent porter une veste réfléchissante après la tombée de la nuit.","options":["wear","wearing","wore","wears"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":0,"feedback":["Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wearing porte -ing. Cette forme ne suit pas directement must.","Wore est au passé. Après must, il faut la forme simple wear.","Wears porte un s. Après must, on garde wear sans s."],"id":"q351"},{"category":"Expression professionnelle","topic":"Prendre contact","sentence":"I will get in _____ with the supplier this afternoon.","translation":"Je prendrai contact avec le fournisseur cet après-midi.","options":["call","reach","speak","touch"],"hint":"Une expression pour contacter quelqu’un : get in…","rule":"Get in touch with = prendre contact avec.","answer":3,"feedback":["Call veut dire appeler, mais get in call with ne convient pas.","In reach peut vouloir dire à portée. Get in reach with ne veut pas dire contacter.","Speak veut dire parler. On peut dire speak with someone, mais pas get in speak with.","Get in touch with = prendre contact avec."],"id":"q352"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The samples _____ tested by an independent laboratory last month.","translation":"Les échantillons ont été testés par un laboratoire indépendant le mois dernier.","options":["was","have","are","were"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":3,"feedback":["Was accompagne une seule chose. Le sujet est au pluriel.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Are est au présent. Le moment indiqué est passé.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé."],"id":"q353"},{"category":"Expression professionnelle","topic":"Effectuer","sentence":"We need to _____ out a final inspection.","translation":"Nous devons effectuer une dernière inspection.","options":["bring","carry","turn","put"],"hint":"Il faut réaliser une inspection ou un contrôle.","rule":"Carry out = effectuer, réaliser.","answer":1,"feedback":["Bring out peut signifier publier ou faire ressortir. Il ne signifie pas effectuer ici.","Carry out = effectuer, réaliser.","Turn out peut signifier se révéler. Il ne signifie pas effectuer une inspection.","Put out peut signifier éteindre. Il ne signifie pas effectuer des contrôles."],"id":"q354"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The complaint _____ handled by our supervisor last Monday.","translation":"La réclamation a été traitée par notre superviseur lundi dernier.","options":["is","was","were","has"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":1,"feedback":["Is est au présent. La phrase indique un moment passé.","Was convient pour une seule chose, dans le passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Has ne forme pas le passif ici. Le sujet reçoit l’action."],"id":"q355"},{"category":"Expression professionnelle","topic":"Organiser une réunion","sentence":"Her assistant will _____ up a meeting with the supplier.","translation":"Son assistante organisera une réunion avec le fournisseur.","options":["take","give","set","break"],"hint":"L’expression avec up signifie organiser.","rule":"Set up = organiser, mettre en place.","answer":2,"feedback":["Take up peut signifier commencer une activité ou occuper du temps. Il ne signifie pas organiser une réunion.","Give up signifie abandonner.","Set up = organiser, mettre en place.","Break up signifie notamment se séparer ou disperser, pas organiser."],"id":"q356"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Every desk _____ a reading lamp.","translation":"Chaque bureau possède une lampe de lecture.","options":["has","have","having","are"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":0,"feedback":["Each ou every présente une personne à la fois : on utilise has.","Have ne convient pas avec ce sujet singulier.","Having seul ne fait pas un verbe conjugué complet.","Are veut dire sont. Il ne convient ni au singulier ni au sens."],"id":"q357"},{"category":"Expression professionnelle","topic":"Reporter","sentence":"Do not _____ off the inspection any longer.","translation":"Ne reporte pas davantage l’inspection.","options":["turn","set","put","take"],"hint":"La date est repoussée à plus tard.","rule":"Put off = reporter à plus tard.","answer":2,"feedback":["Turn off signifie notamment éteindre un appareil.","Set off peut signifier partir ou déclencher. Il ne signifie pas reporter.","Put off = reporter à plus tard.","Take off peut signifier décoller ou enlever."],"id":"q358"},{"category":"Grammaire","topic":"Manière de faire","sentence":"The receptionist wrote down the caller’s details _____.","translation":"La réceptionniste a noté les coordonnées de la personne qui appelait avec soin.","options":["careful","careless","carefully","care"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":2,"feedback":["Careful décrit une personne ou une chose. Ici, on décrit une action.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Carefully explique comment faire l’action : avec attention.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici."],"id":"q359"},{"category":"Expression professionnelle","topic":"Refuser une offre","sentence":"They turned _____ the proposal because it was too expensive.","translation":"Ils ont refusé la proposition parce qu’elle était trop chère.","options":["out","down","into","off"],"hint":"Turn… signifie ici refuser.","rule":"Turn down = refuser une offre ou une demande.","answer":1,"feedback":["Turn out peut signifier se révéler. Il ne signifie pas refuser cette offre.","Turn down = refuser une offre ou une demande.","Turn into veut dire se transformer en. Ici, il ne s’agit pas d’une transformation.","Turn off signifie notamment éteindre."],"id":"q360"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"A _____ alarm system protects the warehouse.","translation":"Un système d’alarme fiable protège l’entrepôt.","options":["reliable","reliably","reliability","rely"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":0,"feedback":["Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliably décrit comment on fait une action, pas directement une chose.","Reliability est le nom fiabilité. Ici, on cherche une qualité.","Rely est un verbe : compter sur. Ici, il faut une qualité."],"id":"q361"},{"category":"Expression professionnelle","topic":"Remplir les informations","sentence":"Visitors must _____ in this registration card.","translation":"Les visiteurs doivent remplir cette fiche d’inscription.","options":["fill","break","set","come"],"hint":"On complète ce qui manque sur un document.","rule":"Fill in = remplir, compléter.","answer":0,"feedback":["Fill in = remplir, compléter.","Break in peut vouloir dire entrer par effraction.","Set in décrit notamment une situation qui s’installe, comme le froid. Il ne signifie pas remplir.","Come in veut dire entrer. Il ne signifie pas remplir les informations."],"id":"q362"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"The recruiter compared several _____ before arranging interviews.","translation":"Le recruteur a comparé plusieurs candidatures avant d’organiser les entretiens.","options":["applications","apply","applying","applicable"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":0,"feedback":["Applications est un nom au pluriel : des candidatures.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature."],"id":"q363"},{"category":"Expression professionnelle","topic":"Ne plus avoir","sentence":"We are about to run _____ of cleaning supplies.","translation":"Nous allons bientôt manquer de produits de nettoyage.","options":["out","through","over","away"],"hint":"Le stock est épuisé : run… of.","rule":"Run out of = ne plus avoir, épuiser son stock de.","answer":0,"feedback":["Run out of = ne plus avoir, épuiser son stock de.","Run through peut signifier parcourir ou passer en revue. Run through of ne convient pas.","Run over ne forme pas l’expression ne plus avoir avec of.","Run away signifie s’enfuir."],"id":"q364"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"The lift has been out of service _____ Monday.","translation":"L’ascenseur est hors service depuis lundi.","options":["until","during","for","since"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":3,"feedback":["Until indique une fin. Ici, on indique le début d’une période encore en cours.","During veut dire pendant. Il ne marque pas ici le début de la période.","For sert à donner une durée, comme for three years.","Since indique quand la période a commencé."],"id":"q365"},{"category":"Expression professionnelle","topic":"Licencier du personnel","sentence":"Several factories had to _____ off temporary workers.","translation":"Plusieurs usines ont dû licencier des travailleurs temporaires.","options":["pick","resign","lay","remove"],"hint":"L’entreprise doit supprimer des emplois : … off.","rule":"Lay off = licencier, souvent pour des raisons économiques.","answer":2,"feedback":["Pick off peut signifier éliminer une cible, pas licencier du personnel.","Resign veut dire démissionner. On ne dit pas resign off employees.","Lay off = licencier, souvent pour des raisons économiques.","Remove veut dire retirer. Il ne se construit pas avec off employees pour licencier."],"id":"q366"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"He has been waiting for a reply _____ three days.","translation":"Il attend une réponse depuis trois jours.","options":["since","during","from","for"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":3,"feedback":["Since introduit un début précis, comme since Monday.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","From donne un départ. Ici, la phrase donne une durée.","For introduit la durée : combien de temps cela dure."],"id":"q367"},{"category":"Expression professionnelle","topic":"Examiner un problème","sentence":"We will look _____ your complaint immediately.","translation":"Nous examinerons ta réclamation immédiatement.","options":["after","into","forward","between"],"hint":"L’équipe va chercher ce qui ne fonctionne pas.","rule":"Look into = examiner, enquêter sur.","answer":1,"feedback":["Look after signifie prendre soin de. Ce n’est pas examiner la cause d’un problème.","Look into = examiner, enquêter sur.","Look forward to signifie attendre avec plaisir. Ici, il n’y a pas to et on examine un problème.","Look between signifie regarder entre des choses. Cela ne convient pas ici."],"id":"q368"},{"category":"Grammaire","topic":"Après décider","sentence":"The board decided _____ a distribution centre in the north.","translation":"Le conseil d’administration a décidé d’ouvrir un centre de distribution dans le nord.","options":["to open","open","opened","opening"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":0,"feedback":["Decide to open veut dire décider d’ouvrir.","Il manque to entre decided et open.","Opened est une forme passée. Après decided, on utilise ici to open.","Opening ne suit pas directement decided dans cette construction."],"id":"q369"},{"category":"Expression professionnelle","topic":"Annuler","sentence":"Bad weather could force us to call _____ the trip.","translation":"Le mauvais temps pourrait nous obliger à annuler le voyage.","options":["away","down","over","off"],"hint":"Call… signifie ici annuler complètement.","rule":"Call off = annuler.","answer":3,"feedback":["Away ne forme pas avec call l’expression annuler un événement.","Call down ne signifie pas annuler ce concert.","Call over peut signifier appeler quelqu’un pour qu’il s’approche. Ce n’est pas annuler.","Call off = annuler."],"id":"q370"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Remember to collect your receipt before _____ the hotel.","translation":"Pense à récupérer ton reçu avant de quitter l’hôtel.","options":["left","leaves","leaving","leave"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":2,"feedback":["Left est au passé. Cette forme ne convient pas directement ici.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Après before ou after sans nouveau sujet, leaving convient.","Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici."],"id":"q371"},{"category":"Expression professionnelle","topic":"Réduire","sentence":"We need to _____ down on delivery costs.","translation":"Nous devons réduire les frais de livraison.","options":["make","take","cut","give"],"hint":"On veut réduire une consommation : … down on.","rule":"Cut down on = réduire sa consommation de.","answer":2,"feedback":["Make down on ne convient pas. Pour réduire, on dit cut down on.","Take down peut signifier noter ou démonter, mais take down on ne signifie pas réduire.","Cut down on = réduire sa consommation de.","Give down on ne forme pas cette expression."],"id":"q372"},{"category":"Grammaire","topic":"Comparaison","sentence":"Our new packing method is _____ than the manual process.","translation":"Notre nouvelle méthode d’emballage est plus efficace que le procédé manuel.","options":["efficient","most efficient","efficiently","more efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":3,"feedback":["Efficient seul ne forme pas cette comparaison avec than.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficiently décrit une action. Ici, on compare la qualité de deux choses.","More efficient than veut dire plus efficace que."],"id":"q373"},{"category":"Expression professionnelle","topic":"Proposer une idée","sentence":"The team must _____ up with a simple solution.","translation":"L’équipe doit trouver une solution simple.","options":["come","bring","send","make"],"hint":"Trouver une idée se dit … up with.","rule":"Come up with = trouver, proposer une idée.","answer":0,"feedback":["Come up with = trouver, proposer une idée.","Bring up a subject signifie aborder un sujet, sans with. Bring up with ne convient pas ici.","Send signifie envoyer. Send up with ne signifie pas proposer une idée.","Make up a story signifie inventer une histoire, sans with. Make up with ne signifie pas trouver une solution."],"id":"q374"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The training room is quiet _____ for us to record the presentation.","translation":"La salle de formation est assez calme pour que nous enregistrions la présentation.","options":["too","much","enough","very"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":2,"feedback":["Too se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif.","Enough se place après la qualité : assez grand, assez rapide…","Very se place avant la qualité, pas après."],"id":"q375"},{"category":"Expression professionnelle","topic":"Provisoirement","sentence":"For the time _____, please use the side entrance.","translation":"Pour le moment, utilise l’entrée latérale.","options":["be","been","being","was"],"hint":"Il s’agit d’une solution pour le moment.","rule":"For the time being = pour le moment.","answer":2,"feedback":["Be ne complète pas cette expression fixe.","Been est une forme de be. L’expression pour le moment est for the time being.","For the time being = pour le moment.","Was indique le passé de be ; il ne complète pas cette expression."],"id":"q376"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"We did not receive _____ feedback after the workshop.","translation":"Nous n’avons pas reçu beaucoup de retours après l’atelier.","options":["much","several","many","a few"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":0,"feedback":["Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","Several accompagne un nom comptable au pluriel, comme several minutes.","Many accompagne des choses comptables au pluriel, comme many files.","A few accompagne un nom comptable au pluriel, comme a few chairs."],"id":"q377"},{"category":"Expression professionnelle","topic":"Dès que possible","sentence":"We will replace the damaged item as soon _____ possible.","translation":"Nous remplacerons l’article endommagé dès que possible.","options":["so","like","as","than"],"hint":"As soon… possible signifie dès que possible.","rule":"As soon as possible = dès que possible.","answer":2,"feedback":["So ne termine pas la construction as soon as possible.","Like peut signifier comme, mais as soon like possible ne convient pas.","As soon as possible = dès que possible.","Than sert souvent à comparer : faster than. Ici, on utilise as … as."],"id":"q378"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"Our suppliers have changed _____ delivery schedules.","translation":"Nos fournisseurs ont modifié leurs horaires de livraison.","options":["them","theirs","they","their"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":3,"feedback":["Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","They veut dire ils ou elles et sert de sujet.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…"],"id":"q379"},{"category":"Expression professionnelle","topic":"Au plus tard","sentence":"Please arrive no later _____ 8:45.","translation":"Arrive au plus tard à 8 h 45.","options":["that","then","as","than"],"hint":"No later… indique la dernière date possible.","rule":"No later than = au plus tard.","answer":3,"feedback":["That ne complète pas la comparaison no later than.","Then veut dire ensuite. Ne le confonds pas avec than, utilisé pour comparer.","As s’utilise dans as late as, mais ici il faut no later than.","No later than = au plus tard."],"id":"q380"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The restaurant is changing _____ menu for the summer.","translation":"Le restaurant change sa carte pour l’été.","options":["it","its","it’s","itself"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":1,"feedback":["It remplace une chose mais n’indique pas la possession devant un nom.","Its indique ce qui appartient à l’entreprise ou à la chose.","It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa."],"id":"q381"},{"category":"Expression professionnelle","topic":"À côté de","sentence":"Our office is next _____ the central station.","translation":"Notre bureau est à côté de la gare centrale.","options":["to","with","for","at"],"hint":"Next… indique ce qui se trouve juste à côté.","rule":"Next to = à côté de.","answer":0,"feedback":["Next to = à côté de.","With veut dire avec. Pour à côté de, on dit next to.","For ne complète pas next dans cette expression.","At peut indiquer un lieu, mais next at ne convient pas."],"id":"q382"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The customer _____ called this morning left a message.","translation":"Le client qui a appelé ce matin a laissé un message.","options":["whom","which","whose","who"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":3,"feedback":["Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Which reprend généralement une chose. Ici, c’est une personne.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Who reprend une personne qui fait l’action juste après."],"id":"q383"},{"category":"Expression professionnelle","topic":"En plus de","sentence":"She manages recruitment in _____ to staff training.","translation":"Elle gère le recrutement en plus de la formation du personnel.","options":["additional","additionally","addition","added"],"hint":"L’expression introduit une chose supplémentaire.","rule":"In addition to = en plus de.","answer":2,"feedback":["Additional décrit quelque chose de supplémentaire, comme additional costs. Après in ici, il faut le nom addition.","Additionally signifie en plus, mais s’utilise sans in … to.","In addition to = en plus de.","Added veut dire ajouté. Il ne forme pas in addition to."],"id":"q384"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The meeting ended early _____ a fire alarm.","translation":"La réunion s’est terminée plus tôt à cause d’une alarme incendie.","options":["because of","although","so that","because"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":0,"feedback":["Because of veut dire à cause de et peut être suivi de cette chose.","Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe."],"id":"q385"},{"category":"Expression professionnelle","topic":"En raison de","sentence":"Production slowed _____ to a shortage of parts.","translation":"La production a ralenti en raison d’une pénurie de pièces.","options":["cause","due","owed","because"],"hint":"Le mot suivant le trou est to.","rule":"Due to = en raison de.","answer":1,"feedback":["Cause veut dire cause ou causer, mais cause to ne forme pas cette expression.","Due to = en raison de.","Owed veut dire dû au sens d’une dette. Ici, on indique une cause : due to.","Because se construit avec of devant un nom : because of fog. Ici, to est déjà présent."],"id":"q386"},{"category":"Grammaire","topic":"Accord au présent","sentence":"The head chef _____ with a team of five cooks.","translation":"Le chef de cuisine travaille avec une équipe de cinq cuisiniers.","options":["works","working","work","to work"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":0,"feedback":["Le sujet est une seule personne : au présent, on ajoute s à work.","Working seul ne constitue pas un verbe conjugué complet.","Work sans s convient notamment avec they, pas avec ce sujet singulier.","To work n’est pas le verbe conjugué nécessaire ici."],"id":"q387"},{"category":"Expression professionnelle","topic":"À la demande","sentence":"A receipt can be issued on _____.","translation":"Un reçu peut être délivré sur demande.","options":["requested","ask","request","requesting"],"hint":"L’expression signifie si quelqu’un le demande.","rule":"On request = sur demande.","answer":2,"feedback":["Requested signifie demandé. On requested ne convient pas ici.","Ask est un verbe : demander. On request utilise un nom.","On request = sur demande.","Requesting est une forme en -ing. L’expression est on request."],"id":"q388"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"A group of investors _____ the construction site last month.","translation":"Un groupe d’investisseurs a visité le chantier le mois dernier.","options":["visiting","has visited","visited","visits"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":2,"feedback":["Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visited est au passé. Le moment indiqué est terminé.","Visits est au présent. La phrase situe l’action dans le passé."],"id":"q389"},{"category":"Expression professionnelle","topic":"À temps","sentence":"We submitted the application in _____.","translation":"Nous avons remis la candidature à temps.","options":["clock","hour","minute","time"],"hint":"On arrive avant qu’il ne soit trop tard : in…","rule":"In time = à temps.","answer":3,"feedback":["Clock signifie horloge. In clock ne convient pas.","Hour signifie heure, mais in hour ne signifie pas à temps.","Minute ne forme pas cette expression. In a minute voudrait dire dans une minute.","In time = à temps."],"id":"q390"},{"category":"Grammaire","topic":"Condition future","sentence":"If you need more information, I _____ the details later today.","translation":"Si tu as besoin de plus d’informations, j’enverrai les détails plus tard aujourd’hui.","options":["sent","has sent","will send","sending"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":2,"feedback":["Sent est au passé. Ici, le résultat attendu est futur.","Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition.","Will send indique ce qui se passera si la condition se réalise.","Sending seul n’est pas un verbe conjugué complet."],"id":"q391"},{"category":"Expression professionnelle","topic":"D’avance sur le planning","sentence":"The repairs were finished _____ of schedule.","translation":"Les réparations ont été terminées en avance sur le planning.","options":["front","early","ahead","before"],"hint":"La tâche est finie plus tôt que prévu : … of schedule.","rule":"Ahead of schedule = en avance sur le planning.","answer":2,"feedback":["In front of indique devant dans l’espace. Front of schedule ne convient pas.","Early veut dire tôt. Early of schedule ne convient pas.","Ahead of schedule = en avance sur le planning.","Before veut dire avant et peut être suivi directement d’un nom. Before of ne convient pas."],"id":"q392"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The two engineers solved the problem by _____, without outside support.","translation":"Les deux ingénieurs ont résolu le problème seuls, sans aide extérieure.","options":["themselves","their","theirs","they"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":0,"feedback":["By themselves veut dire eux-mêmes, sans aide.","Their doit être suivi d’un nom, comme their work.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","They sert de sujet et ne vient pas après by ici."],"id":"q393"},{"category":"Expression professionnelle","topic":"Dans les limites du budget","sentence":"Can we complete the renovation _____ budget?","translation":"Pouvons-nous terminer la rénovation sans dépasser le budget ?","options":["among","along","between","within"],"hint":"Les dépenses ne dépassent pas la somme prévue.","rule":"Within budget = dans les limites du budget.","answer":3,"feedback":["Among veut dire parmi. Il ne signifie pas dans les limites d’une somme.","Along veut dire le long de. Il ne convient pas pour parler de dépenses limitées.","Between veut dire entre, par exemple entre deux montants. Ici, il n’y a qu’un budget.","Within budget = dans les limites du budget."],"id":"q394"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"The purchase requires written _____ from the finance department.","translation":"L’achat nécessite une approbation écrite du service financier.","options":["approved","approval","approves","approve"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":1,"feedback":["Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même.","Approval est un nom : l’accord ou l’approbation.","Approves est un verbe conjugué. Ici, il faut un nom.","Approve est un verbe : approuver. Ici, on cherche une chose."],"id":"q395"},{"category":"Expression professionnelle","topic":"En cas de","sentence":"Keep this number nearby in _____ of a problem.","translation":"Garde ce numéro à proximité en cas de problème.","options":["happens","condition","case","situation"],"hint":"Une consigne pour une éventuelle urgence : in… of.","rule":"In case of = en cas de.","answer":2,"feedback":["Happens est un verbe : se produit. In happens of n’est pas correct.","Condition peut désigner une condition. In condition of ne signifie pas en cas de.","In case of = en cas de.","Situation ne forme pas l’expression in case of."],"id":"q396"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The new furniture will _____ next week.","translation":"Les nouveaux meubles arriveront la semaine prochaine.","options":["arrive","arrived","arriving","arrives"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":0,"feedback":["Après will, on garde la forme simple : arrive.","Arrived est au passé. Après will, on garde arrive.","Arriving ne suit pas directement will ; il faudrait une autre construction.","On n’ajoute pas de s au verbe après will."],"id":"q397"},{"category":"Expression professionnelle","topic":"Changer d’avis","sentence":"He changed his _____ after reading the full report.","translation":"Il a changé d’avis après avoir lu le rapport complet.","options":["thought","mind","minded","brain"],"hint":"La personne ne veut plus la même chose : change one’s…","rule":"Change your mind = changer d’avis.","answer":1,"feedback":["Thought veut dire pensée. L’expression changer d’avis est change your mind.","Change your mind = changer d’avis.","Minded est une forme qu’on trouve dans des adjectifs comme open-minded. Ici, il faut le nom mind.","Brain veut dire cerveau. Changer d’avis ne signifie pas changer de cerveau !"],"id":"q398"},{"category":"Grammaire","topic":"Après enjoy","sentence":"The new assistant enjoys _____ in a small team.","translation":"Le nouvel assistant aime travailler dans une petite équipe.","options":["work","worked","to work","working"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":3,"feedback":["Work seul ne suit pas enjoy dans cette construction.","Worked est au passé et ne convient pas après enjoy ici.","Enjoy ne se construit pas avec to work. On utilise working.","Après enjoy, on utilise ici working : aimer travailler."],"id":"q399"},{"category":"Expression professionnelle","topic":"Être en congé","sentence":"He will be on sick _____ until Monday.","translation":"Il sera en congé maladie jusqu’à lundi.","options":["left","leaving","leave","leaves"],"hint":"La personne ne travaille pas pendant quelques jours.","rule":"On leave = en congé.","answer":2,"feedback":["Left peut vouloir dire parti ou gauche. Le nom congé est leave.","Leaving évoque l’action de partir. Ici, on cherche le nom congé.","On leave = en congé.","Leaves peut désigner des feuilles ou signifier part au présent. Dans on leave, le nom ne prend pas de s."],"id":"q400"},{"category":"Grammaire","topic":"Obligation","sentence":"All cooks must _____ hairnets when preparing meals.","translation":"Tous les cuisiniers doivent porter une charlotte lorsqu’ils préparent les repas.","options":["wore","wearing","wear","wears"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":2,"feedback":["Wore est au passé. Après must, il faut la forme simple wear.","Wearing porte -ing. Cette forme ne suit pas directement must.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle.","Wears porte un s. Après must, on garde wear sans s."],"id":"q401"},{"category":"Expression professionnelle","topic":"Respecter une échéance","sentence":"The contractor promised to _____ the revised deadline.","translation":"L’entrepreneur a promis de respecter la nouvelle échéance.","options":["meet","join","arrive","attend"],"hint":"L’équipe veut finir à temps.","rule":"Meet a deadline = respecter une échéance.","answer":0,"feedback":["Meet a deadline = respecter une échéance.","Join veut dire rejoindre une personne ou un groupe.","Arrive veut dire arriver. Il ne se place pas directement devant the deadline ici.","Attend veut dire assister à un événement. Une date limite n’est pas un événement auquel on assiste."],"id":"q402"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The old files _____ destroyed by a specialist company yesterday.","translation":"Les anciens dossiers ont été détruits par une entreprise spécialisée hier.","options":["have","was","are","were"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":3,"feedback":["Have ne forme pas le passif ici. Les objets reçoivent l’action.","Was accompagne une seule chose. Le sujet est au pluriel.","Are est au présent. Le moment indiqué est passé.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé."],"id":"q403"},{"category":"Expression professionnelle","topic":"Passer une commande","sentence":"We need to _____ an order for replacement parts.","translation":"Nous devons passer une commande de pièces de rechange.","options":["spend","place","attend","borrow"],"hint":"On veut commander quelque chose.","rule":"Place an order = passer une commande.","answer":1,"feedback":["Spend veut dire dépenser de l’argent ou passer du temps.","Place an order = passer une commande.","Attend veut dire assister à une réunion ou à un événement.","Borrow veut dire emprunter. Ici, on commande des produits."],"id":"q404"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The brochure _____ translated into Spanish two months ago.","translation":"La brochure a été traduite en espagnol il y a deux mois.","options":["is","was","were","has"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":1,"feedback":["Is est au présent. La phrase indique un moment passé.","Was convient pour une seule chose, dans le passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Has ne forme pas le passif ici. Le sujet reçoit l’action."],"id":"q405"},{"category":"Expression professionnelle","topic":"Demander à obtenir","sentence":"Small businesses can apply _____ financial support.","translation":"Les petites entreprises peuvent demander une aide financière.","options":["at","with","for","on"],"hint":"Repère apply : on demande à obtenir quelque chose.","rule":"Apply for something = faire une demande pour obtenir quelque chose.","answer":2,"feedback":["At sert notamment à indiquer un lieu. Pour demander à obtenir, on dit apply for.","With veut dire avec. Il ne complète pas cette expression.","Apply for something = faire une demande pour obtenir quelque chose.","On ne convient pas ici : apply for indique ce qu’on demande à obtenir."],"id":"q406"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Each branch _____ a local manager.","translation":"Chaque succursale a un responsable local.","options":["having","are","have","has"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":3,"feedback":["Having seul ne fait pas un verbe conjugué complet.","Are veut dire sont. Il ne convient ni au singulier ni au sens.","Have ne convient pas avec ce sujet singulier.","Each ou every présente une personne à la fois : on utilise has."],"id":"q407"},{"category":"Expression professionnelle","topic":"Responsable de","sentence":"The warehouse manager is responsible _____ staff safety.","translation":"Le responsable de l’entrepôt est chargé de la sécurité du personnel.","options":["with","at","by","for"],"hint":"La phrase indique la tâche dont la personne est responsable.","rule":"Responsible for = responsable de.","answer":3,"feedback":["With ne complète pas responsible pour indiquer une tâche.","At convient dans good at, mais pas pour dire responsable de.","By ne complète pas responsible pour indiquer la responsabilité.","Responsible for = responsable de."],"id":"q408"},{"category":"Grammaire","topic":"Manière de faire","sentence":"We compared the two proposals _____ before making a decision.","translation":"Nous avons comparé attentivement les deux propositions avant de prendre une décision.","options":["care","careless","careful","carefully"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":3,"feedback":["Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme.","Careful décrit une personne ou une chose. Ici, on décrit une action.","Carefully explique comment faire l’action : avec attention."],"id":"q409"},{"category":"Expression professionnelle","topic":"Participer à","sentence":"Local suppliers were invited to _____ part in the fair.","translation":"Les fournisseurs locaux ont été invités à participer au salon.","options":["take","make","do","give"],"hint":"On invite les personnes à participer.","rule":"Take part in = participer à.","answer":0,"feedback":["Take part in = participer à.","Make part in n’est pas l’expression participer à.","Do your part veut dire faire sa part, mais do part in ne convient pas.","Give veut dire donner. L’expression participer à est take part in."],"id":"q410"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"The company wants a _____ partner for its overseas operations.","translation":"L’entreprise veut un partenaire fiable pour ses activités à l’étranger.","options":["rely","reliably","reliable","reliability"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":2,"feedback":["Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliably décrit comment on fait une action, pas directement une chose.","Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliability est le nom fiabilité. Ici, on cherche une qualité."],"id":"q411"},{"category":"Expression professionnelle","topic":"À jour","sentence":"Is your emergency contact information up to _____?","translation":"Tes coordonnées d’urgence sont-elles à jour ?","options":["day","year","date","hour"],"hint":"Il faut garder les informations actuelles.","rule":"Up to date = à jour.","answer":2,"feedback":["Day veut dire jour. On ne traduit pas à jour mot par mot.","Year veut dire année. L’expression correcte reste up to date.","Up to date = à jour.","Hour veut dire heure. Up to hour ne signifie pas à jour."],"id":"q412"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"Several _____ for the sales position were incomplete.","translation":"Plusieurs candidatures pour le poste commercial étaient incomplètes.","options":["apply","applicable","applying","applications"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":3,"feedback":["Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature.","Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Applications est un nom au pluriel : des candidatures."],"id":"q413"},{"category":"Expression professionnelle","topic":"Gratuit","sentence":"Children under five enter free of _____.","translation":"Les enfants de moins de cinq ans entrent gratuitement.","options":["charge","invoice","salary","price"],"hint":"Le client ne doit rien payer.","rule":"Free of charge = gratuit, sans frais.","answer":0,"feedback":["Free of charge = gratuit, sans frais.","Invoice veut dire facture. Free of invoice ne signifie pas gratuit.","Salary veut dire salaire. Ici, on parle du prix d’un service.","Price veut dire prix. L’expression est free of charge."],"id":"q414"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"They have rented this warehouse _____ January.","translation":"Ils louent cet entrepôt depuis janvier.","options":["during","until","since","for"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":2,"feedback":["During veut dire pendant. Il ne marque pas ici le début de la période.","Until indique une fin. Ici, on indique le début d’une période encore en cours.","Since indique quand la période a commencé.","For sert à donner une durée, comme for three years."],"id":"q415"},{"category":"Expression professionnelle","topic":"Sous garantie","sentence":"Check whether the laptop is still under _____.","translation":"Vérifie si l’ordinateur portable est encore sous garantie.","options":["warranty","invoice","receipt","purchase"],"hint":"Le fabricant couvre encore les réparations.","rule":"Under warranty = sous garantie.","answer":0,"feedback":["Under warranty = sous garantie.","Invoice est une facture, pas une garantie.","Receipt est un reçu. Under receipt ne signifie pas sous garantie.","Purchase signifie achat. Under purchase ne signifie pas sous garantie."],"id":"q416"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"The two companies have worked together _____ several years.","translation":"Les deux entreprises travaillent ensemble depuis plusieurs années.","options":["during","for","from","since"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":1,"feedback":["During se place devant une période identifiée, comme during the meeting ; pas cette durée seule.","For introduit la durée : combien de temps cela dure.","From donne un départ. Ici, la phrase donne une durée.","Since introduit un début précis, comme since Monday."],"id":"q417"},{"category":"Expression professionnelle","topic":"Au nom de","sentence":"On _____ of the organisers, I welcome you to the conference.","translation":"Au nom des organisateurs, je vous souhaite la bienvenue à la conférence.","options":["regard","side","purpose","behalf"],"hint":"Une personne parle pour tout un groupe.","rule":"On behalf of = au nom de.","answer":3,"feedback":["With regard to signifie concernant. On regard of ne convient pas.","On the side of signifie du côté de ; on side of ne convient pas.","On purpose veut dire volontairement. On purpose of ne convient pas.","On behalf of = au nom de."],"id":"q418"},{"category":"Grammaire","topic":"Après décider","sentence":"Our team decided _____ the registration process earlier this year.","translation":"Notre équipe a décidé d’ouvrir les inscriptions plus tôt cette année.","options":["opening","open","opened","to open"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":3,"feedback":["Opening ne suit pas directement decided dans cette construction.","Il manque to entre decided et open.","Opened est une forme passée. Après decided, on utilise ici to open.","Decide to open veut dire décider d’ouvrir."],"id":"q419"},{"category":"Expression professionnelle","topic":"À l’avance","sentence":"The meeting room must be reserved two days in _____.","translation":"La salle de réunion doit être réservée deux jours à l’avance.","options":["front","advance","early","ahead"],"hint":"L’action doit se faire avant la date prévue.","rule":"In advance = à l’avance.","answer":1,"feedback":["In front indique devant dans l’espace, pas à l’avance dans le temps.","In advance = à l’avance.","Early veut dire tôt. On dit book early, sans in.","Ahead peut exprimer une avance, mais on ne dit pas in ahead."],"id":"q420"},{"category":"Grammaire","topic":"Après une préposition","sentence":"After _____ the company, she started her own business.","translation":"Après avoir quitté l’entreprise, elle a créé sa propre activité.","options":["leave","leaves","leaving","left"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":2,"feedback":["Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Leaves aurait besoin d’un sujet, par exemple she leaves.","Après before ou after sans nouveau sujet, leaving convient.","Left est au passé. Cette forme ne convient pas directement ici."],"id":"q421"},{"category":"Expression professionnelle","topic":"Être chargé de","sentence":"Who is in _____ of organising the training day?","translation":"Qui est chargé d’organiser la journée de formation ?","options":["role","charge","task","duty"],"hint":"La personne organise ou dirige l’activité.","rule":"In charge of = chargé de, responsable de.","answer":1,"feedback":["Role veut dire rôle. In role of ne convient pas pour cette expression.","In charge of = chargé de, responsable de.","Task veut dire tâche, mais in task of ne convient pas.","On duty signifie en service. In duty of ne signifie pas responsable de."],"id":"q422"},{"category":"Grammaire","topic":"Comparaison","sentence":"The revised delivery route is _____ than the original one.","translation":"Le nouvel itinéraire de livraison est plus efficace que l’itinéraire initial.","options":["efficiently","efficient","more efficient","most efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":2,"feedback":["Efficiently décrit une action. Ici, on compare la qualité de deux choses.","Efficient seul ne forme pas cette comparaison avec than.","More efficient than veut dire plus efficace que.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison."],"id":"q423"},{"category":"Expression professionnelle","topic":"Suivre quelque chose","sentence":"It is difficult to keep _____ of so many requests.","translation":"Il est difficile de suivre autant de demandes.","options":["attention","part","care","track"],"hint":"On veut savoir où en sont les dossiers.","rule":"Keep track of = suivre, tenir le suivi de.","answer":3,"feedback":["On dit pay attention to pour faire attention à.","On dit take part in pour participer à. Ce n’est pas assurer le suivi.","On dit take care of pour s’occuper de, pas keep care of.","Keep track of = suivre, tenir le suivi de."],"id":"q424"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The desk is strong _____ to support the equipment.","translation":"Le bureau est assez solide pour supporter le matériel.","options":["enough","very","too","much"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":0,"feedback":["Enough se place après la qualité : assez grand, assez rapide…","Very se place avant la qualité, pas après.","Too se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif."],"id":"q425"},{"category":"Expression professionnelle","topic":"Peu de préavis","sentence":"The room became available at short _____.","translation":"La salle s’est libérée avec peu de préavis.","options":["message","news","warning","notice"],"hint":"La personne a été prévenue peu de temps avant.","rule":"At short notice = avec peu de préavis.","answer":3,"feedback":["Message veut dire message. At short message ne signifie pas avec peu de préavis.","News veut dire nouvelles ou actualités. At short news ne convient pas.","On peut dire with little warning, mais pas at short warning pour cette expression.","At short notice = avec peu de préavis."],"id":"q426"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"There is not _____ water left in the cooler.","translation":"Il ne reste pas beaucoup d’eau dans la fontaine.","options":["several","much","many","a few"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":1,"feedback":["Several accompagne un nom comptable au pluriel, comme several minutes.","Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","Many accompagne des choses comptables au pluriel, comme many files.","A few accompagne un nom comptable au pluriel, comme a few chairs."],"id":"q427"},{"category":"Expression professionnelle","topic":"Par écrit","sentence":"Please put your complaint in _____.","translation":"Merci de formuler ta réclamation par écrit.","options":["write","writing","written","wrote"],"hint":"La confirmation doit être écrite.","rule":"In writing = par écrit.","answer":1,"feedback":["Write est le verbe écrire. In write n’est pas correct.","In writing = par écrit.","Written veut dire écrit. On pourrait dire in written form, mais form manque ici.","Wrote est la forme passée de write. Elle ne convient pas après in ici."],"id":"q428"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"The designers presented _____ ideas to the client.","translation":"Les designers ont présenté leurs idées au client.","options":["they","their","theirs","them"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":1,"feedback":["They veut dire ils ou elles et sert de sujet.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après.","Them remplace des personnes après un verbe ou une préposition, pas devant ce nom."],"id":"q429"},{"category":"Expression professionnelle","topic":"Voyage d’affaires","sentence":"She booked a hotel for her first business _____.","translation":"Elle a réservé un hôtel pour son premier voyage d’affaires.","options":["trip","traffic","transport","route"],"hint":"La personne voyage pour son travail.","rule":"Business trip = voyage d’affaires.","answer":0,"feedback":["Business trip = voyage d’affaires.","Traffic désigne la circulation. Ce n’est pas un voyage.","Transport désigne le transport, mais business transport ne convient pas ici pour un voyage.","Route veut dire itinéraire. Il ne désigne pas ici le voyage lui-même."],"id":"q430"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The factory has reduced _____ electricity consumption.","translation":"L’usine a réduit sa consommation d’électricité.","options":["it’s","itself","it","its"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":3,"feedback":["It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","It remplace une chose mais n’indique pas la possession devant un nom.","Its indique ce qui appartient à l’entreprise ou à la chose."],"id":"q431"},{"category":"Expression professionnelle","topic":"De suite","sentence":"Orders increased for the second quarter in a _____.","translation":"Les commandes ont augmenté pour le deuxième trimestre consécutif.","options":["line","queue","rank","row"],"hint":"Les périodes se suivent sans interruption.","rule":"In a row = de suite, consécutivement.","answer":3,"feedback":["In a line signifie en ligne, comme des personnes alignées.","In a queue signifie dans une file d’attente.","Rank peut désigner un rang ou un grade, mais in a rank ne signifie pas de suite.","In a row = de suite, consécutivement."],"id":"q432"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"The architect _____ designed our office has won a prize.","translation":"L’architecte qui a conçu notre bureau a remporté un prix.","options":["whom","who","which","whose"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":1,"feedback":["Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Who reprend une personne qui fait l’action juste après.","Which reprend généralement une chose. Ici, c’est une personne.","Whose indique à qui appartient quelque chose ; il faudrait ici un nom après."],"id":"q433"},{"category":"Expression professionnelle","topic":"Rupture de stock","sentence":"We cannot ship the batteries because they are out of _____.","translation":"Nous ne pouvons pas expédier les batteries, car elles sont en rupture de stock.","options":["receipt","sale","stock","invoice"],"hint":"Il n’en reste plus à vendre ; de nouveaux exemplaires arrivent bientôt.","rule":"Out of stock = en rupture de stock.","answer":2,"feedback":["Receipt signifie reçu. Out of receipt ne convient pas.","For sale veut dire à vendre. Out of sale n’est pas l’expression rupture de stock.","Out of stock = en rupture de stock.","Invoice signifie facture. Out of invoice ne convient pas."],"id":"q434"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"The train was delayed _____ a technical fault.","translation":"Le train a été retardé à cause d’un problème technique.","options":["because","because of","although","so that"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":1,"feedback":["Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","Because of veut dire à cause de et peut être suivi de cette chose.","Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","So that veut dire pour que ; il faudrait un sujet et un verbe après."],"id":"q435"},{"category":"Expression professionnelle","topic":"Appareil en panne","sentence":"The sign says that the escalator is out of _____.","translation":"Le panneau indique que l’escalator est en panne.","options":["arrangement","order","stock","sequence"],"hint":"L’appareil ne fonctionne plus.","rule":"Out of order = en panne.","answer":1,"feedback":["Arrangement peut signifier organisation. Out of arrangement ne signifie pas en panne.","Out of order = en panne.","Out of stock signifie qu’il n’en reste plus à vendre. Ici, l’appareil est présent mais ne fonctionne pas.","Out of sequence veut dire dans le désordre, pas en panne."],"id":"q436"},{"category":"Grammaire","topic":"Accord au présent","sentence":"Our translator _____ for several international clients.","translation":"Notre traductrice travaille pour plusieurs clients internationaux.","options":["work","works","working","to work"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":1,"feedback":["Work sans s convient notamment avec they, pas avec ce sujet singulier.","Le sujet est une seule personne : au présent, on ajoute s à work.","Working seul ne constitue pas un verbe conjugué complet.","To work n’est pas le verbe conjugué nécessaire ici."],"id":"q437"},{"category":"Expression professionnelle","topic":"Conformément à","sentence":"The work was completed in _____ with the safety rules.","translation":"Le travail a été effectué conformément aux règles de sécurité.","options":["accordingly","accorded","accordance","according"],"hint":"Respecter une règle : in … with.","rule":"In accordance with = conformément à.","answer":2,"feedback":["Accordingly veut dire en conséquence. In accordingly with ne convient pas.","Accorded est une forme verbale. L’expression fixe est in accordance with.","In accordance with = conformément à.","According s’utilise avec to : according to. On ne mélange pas avec in … with."],"id":"q438"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The supplier _____ our offices yesterday afternoon.","translation":"Le fournisseur a visité nos bureaux hier après-midi.","options":["visiting","has visited","visits","visited"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":3,"feedback":["Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visits est au présent. La phrase situe l’action dans le passé.","Visited est au passé. Le moment indiqué est terminé."],"id":"q439"},{"category":"Expression professionnelle","topic":"Selon","sentence":"According _____ the survey, most customers are satisfied.","translation":"Selon l’enquête, la plupart des clients sont satisfaits.","options":["to","at","with","for"],"hint":"Repère according : quel petit mot vient avec lui ?","rule":"According to = selon.","answer":0,"feedback":["According to = selon.","According at n’est pas l’expression selon.","With appartient à in accordance with. Avec according, on utilise to.","According for n’est pas l’expression selon."],"id":"q440"},{"category":"Grammaire","topic":"Condition future","sentence":"If the customer confirms the address, we _____ the samples on Monday.","translation":"Si le client confirme l’adresse, nous enverrons les échantillons lundi.","options":["will send","sent","sending","has sent"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":0,"feedback":["Will send indique ce qui se passera si la condition se réalise.","Sent est au passé. Ici, le résultat attendu est futur.","Sending seul n’est pas un verbe conjugué complet.","Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition."],"id":"q441"},{"category":"Expression professionnelle","topic":"Attendre avec plaisir","sentence":"They look forward _____ working with your company.","translation":"Ils se réjouissent de travailler avec ton entreprise.","options":["at","to","for","on"],"hint":"On se réjouit de ce qui va arriver.","rule":"Look forward to + nom ou -ing = attendre avec plaisir.","answer":1,"feedback":["At ne complète pas look forward.","Look forward to + nom ou -ing = attendre avec plaisir.","On dit wait for, mais look forward to.","On ne complète pas look forward."],"id":"q442"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The trainees completed the task by _____, without their supervisor’s help.","translation":"Les stagiaires ont accompli la tâche seuls, sans l’aide de leur superviseur.","options":["their","themselves","theirs","they"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":1,"feedback":["Their doit être suivi d’un nom, comme their work.","By themselves veut dire eux-mêmes, sans aide.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","They sert de sujet et ne vient pas après by ici."],"id":"q443"},{"category":"Expression professionnelle","topic":"Se conformer aux règles","sentence":"All applications must comply _____ the stated requirements.","translation":"Toutes les candidatures doivent respecter les exigences indiquées.","options":["on","for","with","to"],"hint":"Respecter des règles se dit comply…","rule":"Comply with = se conformer à.","answer":2,"feedback":["On ne complète pas comply dans cette expression.","For ne complète pas comply dans cette expression.","Comply with = se conformer à.","On dit conform to, mais comply with."],"id":"q444"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"No payment can be made without the director’s _____.","translation":"Aucun paiement ne peut être effectué sans l’accord du directeur.","options":["approves","approval","approve","approved"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":1,"feedback":["Approves est un verbe conjugué. Ici, il faut un nom.","Approval est un nom : l’accord ou l’approbation.","Approve est un verbe : approuver. Ici, on cherche une chose.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même."],"id":"q445"},{"category":"Expression professionnelle","topic":"Compter sur","sentence":"We rely _____ accurate figures when planning the budget.","translation":"Nous nous appuyons sur des chiffres exacts pour planifier le budget.","options":["at","for","with","on"],"hint":"Rely signifie compter sur quelqu’un.","rule":"Rely on = compter sur.","answer":3,"feedback":["At ne convient pas après rely.","For peut introduire ce qu’on attend, mais la personne vient après on : rely on someone for help.","With signifie avec. Pour compter sur, on utilise rely on.","Rely on = compter sur."],"id":"q446"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"Your confirmation email will _____ within a few minutes.","translation":"Ton courriel de confirmation arrivera dans quelques minutes.","options":["arriving","arrive","arrives","arrived"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":1,"feedback":["Arriving ne suit pas directement will ; il faudrait une autre construction.","Après will, on garde la forme simple : arrive.","On n’ajoute pas de s au verbe après will.","Arrived est au passé. Après will, on garde arrive."],"id":"q447"},{"category":"Expression professionnelle","topic":"S’occuper de demandes","sentence":"The legal department deals _____ contract disputes.","translation":"Le service juridique s’occupe des litiges contractuels.","options":["with","on","at","for"],"hint":"Deal… signifie ici traiter ou gérer.","rule":"Deal with = traiter, s’occuper de.","answer":0,"feedback":["Deal with = traiter, s’occuper de.","On ne convient pas dans cette expression. Deal with signifie traiter.","At ne convient pas après deal pour dire traiter une demande.","For ne convient pas dans deal with a complaint."],"id":"q448"},{"category":"Grammaire","topic":"Après enjoy","sentence":"I enjoy _____ with people from different backgrounds.","translation":"J’aime travailler avec des personnes de différents horizons.","options":["work","to work","worked","working"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":3,"feedback":["Work seul ne suit pas enjoy dans cette construction.","Enjoy ne se construit pas avec to work. On utilise working.","Worked est au passé et ne convient pas après enjoy ici.","Après enjoy, on utilise ici working : aimer travailler."],"id":"q449"},{"category":"Expression professionnelle","topic":"Faire attention","sentence":"You must _____ attention during the safety demonstration.","translation":"Tu dois être attentif pendant la démonstration de sécurité.","options":["make","do","pay","hold"],"hint":"On demande d’être attentif.","rule":"Pay attention to = faire attention à.","answer":2,"feedback":["Make attention ne convient pas. On dit pay attention.","Do attention ne convient pas. On dit pay attention.","Pay attention to = faire attention à.","Hold someone’s attention signifie retenir son attention. Hold attention to ne convient pas."],"id":"q450"},{"category":"Grammaire","topic":"Obligation","sentence":"Technicians must _____ eye protection when cutting metal.","translation":"Les techniciens doivent porter une protection pour les yeux lorsqu’ils découpent du métal.","options":["wears","wore","wearing","wear"],"hint":"Repère must : le verbe juste après garde sa forme simple.","rule":"Must + verbe simple : must wear = devoir porter.","answer":3,"feedback":["Wears porte un s. Après must, on garde wear sans s.","Wore est au passé. Après must, il faut la forme simple wear.","Wearing porte -ing. Cette forme ne suit pas directement must.","Après must, on garde le verbe simple : wear. Le sujet ne change pas cette règle."],"id":"q451"},{"category":"Expression professionnelle","topic":"Prendre contact","sentence":"Please get in _____ with technical support.","translation":"Merci de prendre contact avec l’assistance technique.","options":["speak","touch","call","reach"],"hint":"Une expression pour contacter quelqu’un : get in…","rule":"Get in touch with = prendre contact avec.","answer":1,"feedback":["Speak veut dire parler. On peut dire speak with someone, mais pas get in speak with.","Get in touch with = prendre contact avec.","Call veut dire appeler, mais get in call with ne convient pas.","In reach peut vouloir dire à portée. Get in reach with ne veut pas dire contacter."],"id":"q452"},{"category":"Grammaire","topic":"Passif au passé, pluriel","sentence":"The notices _____ posted on the board last Friday.","translation":"Les avis ont été affichés sur le panneau vendredi dernier.","options":["are","have","were","was"],"hint":"Regarde le sujet pluriel et le moment passé.","rule":"They were + participe passé : ils ont été…","answer":2,"feedback":["Are est au présent. Le moment indiqué est passé.","Have ne forme pas le passif ici. Les objets reçoivent l’action.","Were convient : il y en a plusieurs et l’action a eu lieu dans le passé.","Was accompagne une seule chose. Le sujet est au pluriel."],"id":"q453"},{"category":"Expression professionnelle","topic":"Effectuer","sentence":"An expert will _____ out the repairs tomorrow.","translation":"Un expert effectuera les réparations demain.","options":["turn","put","bring","carry"],"hint":"Il faut réaliser une inspection ou un contrôle.","rule":"Carry out = effectuer, réaliser.","answer":3,"feedback":["Turn out peut signifier se révéler. Il ne signifie pas effectuer une inspection.","Put out peut signifier éteindre. Il ne signifie pas effectuer des contrôles.","Bring out peut signifier publier ou faire ressortir. Il ne signifie pas effectuer ici.","Carry out = effectuer, réaliser."],"id":"q454"},{"category":"Grammaire","topic":"Passif au passé, singulier","sentence":"The award _____ presented to the designer last night.","translation":"Le prix a été remis au designer hier soir.","options":["has","was","were","is"],"hint":"Une seule chose reçoit l’action à un moment passé.","rule":"It was + participe passé : cela a été…","answer":1,"feedback":["Has ne forme pas le passif ici. Le sujet reçoit l’action.","Was convient pour une seule chose, dans le passé.","Were accompagne notamment they. Ici, il s’agit d’une seule chose.","Is est au présent. La phrase indique un moment passé."],"id":"q455"},{"category":"Expression professionnelle","topic":"Organiser une réunion","sentence":"Can we _____ up an online meeting this afternoon?","translation":"Pouvons-nous organiser une réunion en ligne cet après-midi ?","options":["take","set","give","break"],"hint":"L’expression avec up signifie organiser.","rule":"Set up = organiser, mettre en place.","answer":1,"feedback":["Take up peut signifier commencer une activité ou occuper du temps. Il ne signifie pas organiser une réunion.","Set up = organiser, mettre en place.","Give up signifie abandonner.","Break up signifie notamment se séparer ou disperser, pas organiser."],"id":"q456"},{"category":"Grammaire","topic":"Chaque personne","sentence":"Every room _____ a smoke detector.","translation":"Chaque chambre possède un détecteur de fumée.","options":["are","has","have","having"],"hint":"Chaque personne : on les prend une par une.","rule":"Each / every + nom singulier → has.","answer":1,"feedback":["Are veut dire sont. Il ne convient ni au singulier ni au sens.","Each ou every présente une personne à la fois : on utilise has.","Have ne convient pas avec ce sujet singulier.","Having seul ne fait pas un verbe conjugué complet."],"id":"q457"},{"category":"Expression professionnelle","topic":"Reporter","sentence":"They decided to _____ off the training session until June.","translation":"Ils ont décidé de reporter la formation jusqu’en juin.","options":["put","set","take","turn"],"hint":"La date est repoussée à plus tard.","rule":"Put off = reporter à plus tard.","answer":0,"feedback":["Put off = reporter à plus tard.","Set off peut signifier partir ou déclencher. Il ne signifie pas reporter.","Take off peut signifier décoller ou enlever.","Turn off signifie notamment éteindre un appareil."],"id":"q458"},{"category":"Grammaire","topic":"Manière de faire","sentence":"Please handle the glass samples _____.","translation":"Manipule les échantillons de verre avec précaution.","options":["careful","care","carefully","careless"],"hint":"Le mot répond à la question : comment faire cette action ?","rule":"Verbe + carefully = faire quelque chose avec attention.","answer":2,"feedback":["Careful décrit une personne ou une chose. Ici, on décrit une action.","Care est un nom ou un verbe ; il ne signifie pas avec attention ici.","Carefully explique comment faire l’action : avec attention.","Careless décrit quelqu’un de peu soigneux. Il ne décrit pas l’action sous cette forme."],"id":"q459"},{"category":"Expression professionnelle","topic":"Refuser une offre","sentence":"She politely turned _____ the invitation.","translation":"Elle a poliment refusé l’invitation.","options":["down","into","off","out"],"hint":"Turn… signifie ici refuser.","rule":"Turn down = refuser une offre ou une demande.","answer":0,"feedback":["Turn down = refuser une offre ou une demande.","Turn into veut dire se transformer en. Ici, il ne s’agit pas d’une transformation.","Turn off signifie notamment éteindre.","Turn out peut signifier se révéler. Il ne signifie pas refuser cette offre."],"id":"q460"},{"category":"Grammaire","topic":"Décrire une chose","sentence":"This is a _____ method of checking the figures.","translation":"C’est une méthode fiable pour vérifier les chiffres.","options":["reliable","reliability","rely","reliably"],"hint":"Le trou se trouve devant la chose qu’on décrit.","rule":"Reliable + nom = une chose fiable.","answer":0,"feedback":["Reliable décrit la chose : elle est fiable, on peut compter dessus.","Reliability est le nom fiabilité. Ici, on cherche une qualité.","Rely est un verbe : compter sur. Ici, il faut une qualité.","Reliably décrit comment on fait une action, pas directement une chose."],"id":"q461"},{"category":"Expression professionnelle","topic":"Remplir les informations","sentence":"Could you _____ in the date and reference number?","translation":"Peux-tu compléter la date et le numéro de référence ?","options":["break","fill","set","come"],"hint":"On complète ce qui manque sur un document.","rule":"Fill in = remplir, compléter.","answer":1,"feedback":["Break in peut vouloir dire entrer par effraction.","Fill in = remplir, compléter.","Set in décrit notamment une situation qui s’installe, comme le froid. Il ne signifie pas remplir.","Come in veut dire entrer. Il ne signifie pas remplir les informations."],"id":"q462"},{"category":"Grammaire","topic":"Nom après plusieurs","sentence":"Our personnel department received several _____ from experienced engineers.","translation":"Notre service du personnel a reçu plusieurs candidatures d’ingénieurs expérimentés.","options":["applying","apply","applicable","applications"],"hint":"On parle de plusieurs candidatures. Il faut un nom au pluriel.","rule":"Application = candidature ; applications = candidatures.","answer":3,"feedback":["Applying est une forme du verbe postuler. Il faut ici un nom pluriel.","Apply est un verbe : postuler. Ici, il faut ce qu’on a reçu ou examiné.","Applicable décrit quelque chose qui peut s’appliquer. Ce n’est pas une candidature.","Applications est un nom au pluriel : des candidatures."],"id":"q463"},{"category":"Expression professionnelle","topic":"Ne plus avoir","sentence":"The café ran _____ of milk before lunchtime.","translation":"Le café n’avait plus de lait avant midi.","options":["out","through","away","over"],"hint":"Le stock est épuisé : run… of.","rule":"Run out of = ne plus avoir, épuiser son stock de.","answer":0,"feedback":["Run out of = ne plus avoir, épuiser son stock de.","Run through peut signifier parcourir ou passer en revue. Run through of ne convient pas.","Run away signifie s’enfuir.","Run over ne forme pas l’expression ne plus avoir avec of."],"id":"q464"},{"category":"Grammaire","topic":"Depuis un point de départ","sentence":"She has been responsible for purchasing _____ her promotion last year.","translation":"Elle est responsable des achats depuis sa promotion l’année dernière.","options":["until","for","during","since"],"hint":"La phrase donne le début de la période, pas sa durée.","rule":"Since + point de départ = depuis.","answer":3,"feedback":["Until indique une fin. Ici, on indique le début d’une période encore en cours.","For sert à donner une durée, comme for three years.","During veut dire pendant. Il ne marque pas ici le début de la période.","Since indique quand la période a commencé."],"id":"q465"},{"category":"Expression professionnelle","topic":"Licencier du personnel","sentence":"The firm may _____ off staff if orders continue to fall.","translation":"L’entreprise pourrait licencier du personnel si les commandes continuent de baisser.","options":["lay","remove","resign","pick"],"hint":"L’entreprise doit supprimer des emplois : … off.","rule":"Lay off = licencier, souvent pour des raisons économiques.","answer":0,"feedback":["Lay off = licencier, souvent pour des raisons économiques.","Remove veut dire retirer. Il ne se construit pas avec off employees pour licencier.","Resign veut dire démissionner. On ne dit pas resign off employees.","Pick off peut signifier éliminer une cible, pas licencier du personnel."],"id":"q466"},{"category":"Grammaire","topic":"Pendant une durée","sentence":"I have been responsible for this project _____ eight weeks.","translation":"Je suis responsable de ce projet depuis huit semaines.","options":["for","since","from","during"],"hint":"La phrase dit combien de temps, et non depuis quelle date.","rule":"For + durée : for two weeks = depuis ou pendant deux semaines.","answer":0,"feedback":["For introduit la durée : combien de temps cela dure.","Since introduit un début précis, comme since Monday.","From donne un départ. Ici, la phrase donne une durée.","During se place devant une période identifiée, comme during the meeting ; pas cette durée seule."],"id":"q467"},{"category":"Expression professionnelle","topic":"Examiner un problème","sentence":"An investigator is looking _____ the missing payment.","translation":"Un enquêteur examine le paiement manquant.","options":["forward","after","into","between"],"hint":"L’équipe va chercher ce qui ne fonctionne pas.","rule":"Look into = examiner, enquêter sur.","answer":2,"feedback":["Look forward to signifie attendre avec plaisir. Ici, il n’y a pas to et on examine un problème.","Look after signifie prendre soin de. Ce n’est pas examiner la cause d’un problème.","Look into = examiner, enquêter sur.","Look between signifie regarder entre des choses. Cela ne convient pas ici."],"id":"q468"},{"category":"Grammaire","topic":"Après décider","sentence":"The bank decided _____ a branch in the new shopping district.","translation":"La banque a décidé d’ouvrir une agence dans le nouveau quartier commerçant.","options":["opened","open","opening","to open"],"hint":"On dit décider de faire quelque chose : decide to…","rule":"Decide to + verbe simple.","answer":3,"feedback":["Opened est une forme passée. Après decided, on utilise ici to open.","Il manque to entre decided et open.","Opening ne suit pas directement decided dans cette construction.","Decide to open veut dire décider d’ouvrir."],"id":"q469"},{"category":"Expression professionnelle","topic":"Annuler","sentence":"They called _____ the meeting after the director became ill.","translation":"Ils ont annulé la réunion après que le directeur est tombé malade.","options":["down","over","off","away"],"hint":"Call… signifie ici annuler complètement.","rule":"Call off = annuler.","answer":2,"feedback":["Call down ne signifie pas annuler ce concert.","Call over peut signifier appeler quelqu’un pour qu’il s’approche. Ce n’est pas annuler.","Call off = annuler.","Away ne forme pas avec call l’expression annuler un événement."],"id":"q470"},{"category":"Grammaire","topic":"Après une préposition","sentence":"Save your work before _____ your desk.","translation":"Enregistre ton travail avant de quitter ton bureau.","options":["leaves","left","leave","leaving"],"hint":"Il n’y a pas de nouveau sujet après before ou after.","rule":"Before / after + verbe en -ing.","answer":3,"feedback":["Leaves aurait besoin d’un sujet, par exemple she leaves.","Left est au passé. Cette forme ne convient pas directement ici.","Leave pourrait suivre un sujet : before you leave. Ce sujet manque ici.","Après before ou after sans nouveau sujet, leaving convient."],"id":"q471"},{"category":"Expression professionnelle","topic":"Réduire","sentence":"The office plans to _____ down on paper consumption.","translation":"Le bureau prévoit de réduire sa consommation de papier.","options":["take","cut","make","give"],"hint":"On veut réduire une consommation : … down on.","rule":"Cut down on = réduire sa consommation de.","answer":1,"feedback":["Take down peut signifier noter ou démonter, mais take down on ne signifie pas réduire.","Cut down on = réduire sa consommation de.","Make down on ne convient pas. Pour réduire, on dit cut down on.","Give down on ne forme pas cette expression."],"id":"q472"},{"category":"Grammaire","topic":"Comparaison","sentence":"This machine is _____ than the equipment in our other factory.","translation":"Cette machine est plus efficace que le matériel de notre autre usine.","options":["efficiently","most efficient","efficient","more efficient"],"hint":"Than annonce une comparaison.","rule":"More + adjectif long + than : plus… que.","answer":3,"feedback":["Efficiently décrit une action. Ici, on compare la qualité de deux choses.","Most efficient veut dire le plus efficace. Ici, than demande une comparaison.","Efficient seul ne forme pas cette comparaison avec than.","More efficient than veut dire plus efficace que."],"id":"q473"},{"category":"Expression professionnelle","topic":"Proposer une idée","sentence":"We need to _____ up with a new marketing plan.","translation":"Nous devons proposer un nouveau plan marketing.","options":["send","come","make","bring"],"hint":"Trouver une idée se dit … up with.","rule":"Come up with = trouver, proposer une idée.","answer":1,"feedback":["Send signifie envoyer. Send up with ne signifie pas proposer une idée.","Come up with = trouver, proposer une idée.","Make up a story signifie inventer une histoire, sans with. Make up with ne signifie pas trouver une solution.","Bring up a subject signifie aborder un sujet, sans with. Bring up with ne convient pas ici."],"id":"q474"},{"category":"Grammaire","topic":"Assez + qualité","sentence":"The screen is bright _____ to use outdoors.","translation":"L’écran est assez lumineux pour être utilisé à l’extérieur.","options":["too","much","enough","very"],"hint":"On décrit une qualité suffisante pour faire quelque chose.","rule":"Adjectif + enough + to : assez… pour.","answer":2,"feedback":["Too se place avant la qualité, pas après.","Much ne convient pas directement après cet adjectif.","Enough se place après la qualité : assez grand, assez rapide…","Very se place avant la qualité, pas après."],"id":"q475"},{"category":"Expression professionnelle","topic":"Provisoirement","sentence":"The vacant office will serve as a classroom for the time _____.","translation":"Le bureau vide servira provisoirement de salle de classe.","options":["being","be","been","was"],"hint":"Il s’agit d’une solution pour le moment.","rule":"For the time being = pour le moment.","answer":0,"feedback":["For the time being = pour le moment.","Be ne complète pas cette expression fixe.","Been est une forme de be. L’expression pour le moment est for the time being.","Was indique le passé de be ; il ne complète pas cette expression."],"id":"q476"},{"category":"Grammaire","topic":"Quantité indénombrable","sentence":"The department does not have _____ money for new furniture.","translation":"Le département n’a pas beaucoup d’argent pour de nouveaux meubles.","options":["much","a few","several","many"],"hint":"On ne compte pas directement ce nom : on utilise une quantité.","rule":"Not much + nom indénombrable = pas beaucoup de…","answer":0,"feedback":["Much accompagne ce qu’on ne compte pas directement, comme le temps ou l’argent.","A few accompagne un nom comptable au pluriel, comme a few chairs.","Several accompagne un nom comptable au pluriel, comme several minutes.","Many accompagne des choses comptables au pluriel, comme many files."],"id":"q477"},{"category":"Expression professionnelle","topic":"Dès que possible","sentence":"Contact your manager as soon _____ possible.","translation":"Contacte ton responsable dès que possible.","options":["like","so","as","than"],"hint":"As soon… possible signifie dès que possible.","rule":"As soon as possible = dès que possible.","answer":2,"feedback":["Like peut signifier comme, mais as soon like possible ne convient pas.","So ne termine pas la construction as soon as possible.","As soon as possible = dès que possible.","Than sert souvent à comparer : faster than. Ici, on utilise as … as."],"id":"q478"},{"category":"Grammaire","topic":"Leur, leurs","sentence":"Employees can collect _____ new uniforms on Monday.","translation":"Les employés peuvent récupérer leur nouvelle tenue lundi.","options":["them","they","their","theirs"],"hint":"Le mot indique à qui appartient la chose placée juste après.","rule":"Their + nom = leur ou leurs.","answer":2,"feedback":["Them remplace des personnes après un verbe ou une préposition, pas devant ce nom.","They veut dire ils ou elles et sert de sujet.","Their se place devant ce qui appartient aux personnes : leurs coordonnées, leurs idées…","Theirs remplace déjà ce qui leur appartient. On n’ajoute pas de nom juste après."],"id":"q479"},{"category":"Expression professionnelle","topic":"Au plus tard","sentence":"Applications are due no later _____ 30 September.","translation":"Les candidatures doivent être remises au plus tard le 30 septembre.","options":["then","as","than","that"],"hint":"No later… indique la dernière date possible.","rule":"No later than = au plus tard.","answer":2,"feedback":["Then veut dire ensuite. Ne le confonds pas avec than, utilisé pour comparer.","As s’utilise dans as late as, mais ici il faut no later than.","No later than = au plus tard.","That ne complète pas la comparaison no later than."],"id":"q480"},{"category":"Grammaire","topic":"Possession, une entreprise","sentence":"The airline has added three destinations to _____ network.","translation":"La compagnie aérienne a ajouté trois destinations à son réseau.","options":["itself","it’s","its","it"],"hint":"La chose qui suit appartient au sujet de la phrase.","rule":"Its + nom = son, sa ou ses, pour une chose ou une organisation.","answer":2,"feedback":["Itself veut dire lui-même ou elle-même. Ce n’est pas son ou sa.","It’s veut dire it is ou it has. Ce n’est pas son ou sa.","Its indique ce qui appartient à l’entreprise ou à la chose.","It remplace une chose mais n’indique pas la possession devant un nom."],"id":"q481"},{"category":"Expression professionnelle","topic":"À côté de","sentence":"Please leave the parcel next _____ the reception desk.","translation":"Laisse le colis à côté de l’accueil.","options":["at","for","with","to"],"hint":"Next… indique ce qui se trouve juste à côté.","rule":"Next to = à côté de.","answer":3,"feedback":["At peut indiquer un lieu, mais next at ne convient pas.","For ne complète pas next dans cette expression.","With veut dire avec. Pour à côté de, on dit next to.","Next to = à côté de."],"id":"q482"},{"category":"Grammaire","topic":"Qui, une personne","sentence":"Staff members _____ attend the workshop will receive a certificate.","translation":"Les membres du personnel qui participent à l’atelier recevront un certificat.","options":["whose","which","whom","who"],"hint":"La personne dont on parle fait l’action juste après le trou.","rule":"Personne + who + verbe = la personne qui…","answer":3,"feedback":["Whose indique à qui appartient quelque chose ; il faudrait ici un nom après.","Which reprend généralement une chose. Ici, c’est une personne.","Whom reçoit l’action. Ici, la personne fait l’action : on utilise who.","Who reprend une personne qui fait l’action juste après."],"id":"q483"},{"category":"Expression professionnelle","topic":"En plus de","sentence":"In _____ to English, he speaks Dutch and German.","translation":"En plus de l’anglais, il parle néerlandais et allemand.","options":["addition","additionally","additional","added"],"hint":"L’expression introduit une chose supplémentaire.","rule":"In addition to = en plus de.","answer":0,"feedback":["In addition to = en plus de.","Additionally signifie en plus, mais s’utilise sans in … to.","Additional décrit quelque chose de supplémentaire, comme additional costs. Après in ici, il faut le nom addition.","Added veut dire ajouté. Il ne forme pas in addition to."],"id":"q484"},{"category":"Grammaire","topic":"Cause devant un nom","sentence":"Production stopped _____ a shortage of raw materials.","translation":"La production s’est arrêtée à cause d’une pénurie de matières premières.","options":["although","because","so that","because of"],"hint":"Après le trou, il y a une chose, pas une phrase complète.","rule":"Because of + chose ; because + sujet + verbe.","answer":3,"feedback":["Although veut dire bien que et demande ici une phrase avec un sujet et un verbe.","Because veut dire parce que : il faudrait dire ce qui se passe, avec un sujet et un verbe.","So that veut dire pour que ; il faudrait un sujet et un verbe après.","Because of veut dire à cause de et peut être suivi de cette chose."],"id":"q485"},{"category":"Expression professionnelle","topic":"En raison de","sentence":"The delivery was postponed _____ to severe weather.","translation":"La livraison a été reportée en raison du mauvais temps.","options":["because","cause","due","owed"],"hint":"Le mot suivant le trou est to.","rule":"Due to = en raison de.","answer":2,"feedback":["Because se construit avec of devant un nom : because of fog. Ici, to est déjà présent.","Cause veut dire cause ou causer, mais cause to ne forme pas cette expression.","Due to = en raison de.","Owed veut dire dû au sens d’une dette. Ici, on indique une cause : due to."],"id":"q486"},{"category":"Grammaire","topic":"Accord au présent","sentence":"The branch manager _____ closely with the sales team.","translation":"Le responsable de l’agence travaille en étroite collaboration avec l’équipe commerciale.","options":["to work","working","works","work"],"hint":"Une seule personne et une habitude au présent.","rule":"He / she + works : le s marque le présent au singulier.","answer":2,"feedback":["To work n’est pas le verbe conjugué nécessaire ici.","Working seul ne constitue pas un verbe conjugué complet.","Le sujet est une seule personne : au présent, on ajoute s à work.","Work sans s convient notamment avec they, pas avec ce sujet singulier."],"id":"q487"},{"category":"Expression professionnelle","topic":"À la demande","sentence":"Training sessions are offered on _____.","translation":"Des séances de formation sont proposées sur demande.","options":["requesting","requested","ask","request"],"hint":"L’expression signifie si quelqu’un le demande.","rule":"On request = sur demande.","answer":3,"feedback":["Requesting est une forme en -ing. L’expression est on request.","Requested signifie demandé. On requested ne convient pas ici.","Ask est un verbe : demander. On request utilise un nom.","On request = sur demande."],"id":"q488"},{"category":"Grammaire","topic":"Action passée terminée","sentence":"The consultant _____ the production line three weeks ago.","translation":"Le consultant a visité la chaîne de production il y a trois semaines.","options":["visiting","has visited","visited","visits"],"hint":"Repère le moment terminé : yesterday, last… ou ago.","rule":"Moment passé terminé → past simple : visited.","answer":2,"feedback":["Visiting seul n’est pas un verbe conjugué complet.","Has visited ne s’utilise pas ici avec ce moment passé terminé.","Visited est au passé. Le moment indiqué est terminé.","Visits est au présent. La phrase situe l’action dans le passé."],"id":"q489"},{"category":"Expression professionnelle","topic":"À temps","sentence":"Will the brochures be ready in _____ for the trade fair?","translation":"Les brochures seront-elles prêtes à temps pour le salon professionnel ?","options":["minute","clock","time","hour"],"hint":"On arrive avant qu’il ne soit trop tard : in…","rule":"In time = à temps.","answer":2,"feedback":["Minute ne forme pas cette expression. In a minute voudrait dire dans une minute.","Clock signifie horloge. In clock ne convient pas.","In time = à temps.","Hour signifie heure, mais in hour ne signifie pas à temps."],"id":"q490"},{"category":"Grammaire","topic":"Condition future","sentence":"If the report is ready this evening, I _____ it to the board tomorrow.","translation":"Si le rapport est prêt ce soir, je l’enverrai au conseil d’administration demain.","options":["will send","sending","sent","has sent"],"hint":"Si la condition se réalise, que fera la personne ensuite ?","rule":"If + présent, puis will + verbe pour ce résultat futur.","answer":0,"feedback":["Will send indique ce qui se passera si la condition se réalise.","Sending seul n’est pas un verbe conjugué complet.","Sent est au passé. Ici, le résultat attendu est futur.","Has sent dit que l’envoi a déjà eu lieu ; ici, on attend la condition."],"id":"q491"},{"category":"Expression professionnelle","topic":"D’avance sur le planning","sentence":"Our team is currently _____ of schedule.","translation":"Notre équipe est actuellement en avance sur le planning.","options":["ahead","before","early","front"],"hint":"La tâche est finie plus tôt que prévu : … of schedule.","rule":"Ahead of schedule = en avance sur le planning.","answer":0,"feedback":["Ahead of schedule = en avance sur le planning.","Before veut dire avant et peut être suivi directement d’un nom. Before of ne convient pas.","Early veut dire tôt. Early of schedule ne convient pas.","In front of indique devant dans l’espace. Front of schedule ne convient pas."],"id":"q492"},{"category":"Grammaire","topic":"Sans aide, eux-mêmes","sentence":"The two colleagues prepared the display by _____, without hiring a designer.","translation":"Les deux collègues ont préparé le présentoir eux-mêmes, sans engager de designer.","options":["they","their","theirs","themselves"],"hint":"Les personnes ont tout fait sans aide.","rule":"By themselves = seuls, sans aide.","answer":3,"feedback":["They sert de sujet et ne vient pas après by ici.","Their doit être suivi d’un nom, comme their work.","Theirs veut dire le leur ou les leurs. Il ne veut pas dire eux-mêmes.","By themselves veut dire eux-mêmes, sans aide."],"id":"q493"},{"category":"Expression professionnelle","topic":"Dans les limites du budget","sentence":"The department delivered the campaign _____ budget.","translation":"Le service a réalisé la campagne dans les limites du budget.","options":["between","along","within","among"],"hint":"Les dépenses ne dépassent pas la somme prévue.","rule":"Within budget = dans les limites du budget.","answer":2,"feedback":["Between veut dire entre, par exemple entre deux montants. Ici, il n’y a qu’un budget.","Along veut dire le long de. Il ne convient pas pour parler de dépenses limitées.","Within budget = dans les limites du budget.","Among veut dire parmi. Il ne signifie pas dans les limites d’une somme."],"id":"q494"},{"category":"Grammaire","topic":"Nom : approbation","sentence":"We received final _____ for the office renovation yesterday.","translation":"Nous avons reçu l’approbation finale pour la rénovation du bureau hier.","options":["approve","approval","approves","approved"],"hint":"On cherche le nom de l’autorisation donnée.","rule":"Approval = accord, approbation.","answer":1,"feedback":["Approve est un verbe : approuver. Ici, on cherche une chose.","Approval est un nom : l’accord ou l’approbation.","Approves est un verbe conjugué. Ici, il faut un nom.","Approved signifie approuvé. Ce mot ne désigne pas l’accord lui-même."],"id":"q495"},{"category":"Expression professionnelle","topic":"En cas de","sentence":"In _____ of delay, passengers will receive a message.","translation":"En cas de retard, les passagers recevront un message.","options":["condition","case","happens","situation"],"hint":"Une consigne pour une éventuelle urgence : in… of.","rule":"In case of = en cas de.","answer":1,"feedback":["Condition peut désigner une condition. In condition of ne signifie pas en cas de.","In case of = en cas de.","Happens est un verbe : se produit. In happens of n’est pas correct.","Situation ne forme pas l’expression in case of."],"id":"q496"},{"category":"Grammaire","topic":"Action prévue avec will","sentence":"The technician will _____ shortly after lunch.","translation":"Le technicien arrivera peu après le déjeuner.","options":["arrives","arrive","arriving","arrived"],"hint":"Le mot juste avant le trou est will.","rule":"Will + verbe simple : will arrive = arrivera.","answer":1,"feedback":["On n’ajoute pas de s au verbe après will.","Après will, on garde la forme simple : arrive.","Arriving ne suit pas directement will ; il faudrait une autre construction.","Arrived est au passé. Après will, on garde arrive."],"id":"q497"},{"category":"Expression professionnelle","topic":"Changer d’avis","sentence":"The client might change her _____ about the colour.","translation":"La cliente pourrait changer d’avis concernant la couleur.","options":["brain","thought","mind","minded"],"hint":"La personne ne veut plus la même chose : change one’s…","rule":"Change your mind = changer d’avis.","answer":2,"feedback":["Brain veut dire cerveau. Changer d’avis ne signifie pas changer de cerveau !","Thought veut dire pensée. L’expression changer d’avis est change your mind.","Change your mind = changer d’avis.","Minded est une forme qu’on trouve dans des adjectifs comme open-minded. Ici, il faut le nom mind."],"id":"q498"},{"category":"Grammaire","topic":"Après enjoy","sentence":"The engineers enjoy _____ on practical solutions.","translation":"Les ingénieurs aiment travailler sur des solutions concrètes.","options":["to work","working","worked","work"],"hint":"Après enjoy, le verbe prend une terminaison particulière.","rule":"Enjoy + verbe en -ing : enjoy working.","answer":1,"feedback":["Enjoy ne se construit pas avec to work. On utilise working.","Après enjoy, on utilise ici working : aimer travailler.","Worked est au passé et ne convient pas après enjoy ici.","Work seul ne suit pas enjoy dans cette construction."],"id":"q499"},{"category":"Expression professionnelle","topic":"Être en congé","sentence":"Please approve my annual _____ request.","translation":"Merci d’approuver ma demande de congé annuel.","options":["left","leaving","leaves","leave"],"hint":"La personne ne travaille pas pendant quelques jours.","rule":"On leave = en congé.","answer":3,"feedback":["Left peut vouloir dire parti ou gauche. Le nom congé est leave.","Leaving évoque l’action de partir. Ici, on cherche le nom congé.","Leaves peut désigner des feuilles ou signifier part au présent. Dans on leave, le nom ne prend pas de s.","On leave = en congé."],"id":"q500"}];
